local config = {
  ui_story_5083_50830100_1_dialog_content = "What's the reason behind nightmares? To be honest... I don't really know either.",
  ui_story_5083_50830100_2_dialog_content = "But they're definitely connected to your memories.",
  ui_story_5083_50830100_3_dialog_content = "Maybe it's a past that you can't accept, or regrets that you can't let go of—",
  ui_story_5083_50830100_4_dialog_content = "It makes no sense to me, so just give it a rest. I trust you, so just do what you gotta do.",
  ui_story_5083_50830100_5_dialog_content = "Alright, then just lie down and relax... While I try to resonate with your mind...",
  ui_story_5083_50830100_6_dialog_content = "Man, I'm getting pretty sleepy... Does this mean I'm gonna have that same dream again...?",
  ui_story_5083_50830100_7_dialog_content = "Ah, forget it... I'm sure I'll be fine with you around...",
  ui_story_5083_50830100_8_dialog_content = "Just sleep... And get ready to face it...",
  ui_story_5083_50830100_9_dialog_content = "<color=#e8d9bb>A shrill whistle pierces the air.</color>",
  ui_story_5083_50830100_10_dialog_content = "\"I don't know what I've been told!\"",
  ui_story_5083_50830100_11_dialog_content = "\"Killing Eclipsites never gets old!\"",
  ui_story_5083_50830100_12_dialog_content = "Is this...?",
  ui_story_5083_50830100_13_dialog_content = "\"March!\"",
  ui_story_5083_50830100_14_dialog_content = "\"March!\"",
  ui_story_5083_50830100_15_dialog_content = "Training grounds, huh? That's an old drill song too...",
  ui_story_5083_50830100_16_dialog_content = "What gives, Barton?! Don't just stop in the middle of the track!",
  ui_story_5083_50830100_17_dialog_content = "Dogg... is that you...?",
  ui_story_5083_50830100_18_dialog_content = "Still half-asleep? That's your problem, pal.",
  ui_story_5083_50830100_19_dialog_content = "Dogg actually managed to pass Barton?!",
  ui_story_5083_50830100_20_dialog_content = "Nah, it's because Barton stopped all of a sudden... This is gonna be good.",
  ui_story_5083_50830100_21_dialog_content = "Barton, you imbecile! This is a training ground, not a daydreaming ground!",
  ui_story_5083_50830100_22_dialog_content = "What happened to become the legion's most exemplary solder? If you want to shame my legion by slacking off, then just get the hell out of here!",
  ui_story_5083_50830100_23_dialog_content = "The rest of you, keep running!",
  ui_story_5083_50830100_24_dialog_content = "Commander Pango, humph... Who said I was slacking off?!",
  ui_story_5083_50830100_25_dialog_content = "Just try to keep up with me!",
  ui_story_5083_50830100_26_dialog_content = "\"Present arms!\"",
  ui_story_5083_50830100_27_dialog_content = "Take this—Arghhh!",
  ui_story_5083_50830100_28_dialog_content = "Don't let him mess up your cadence, soldiers! Repeat after me—\"Love my weapon, yes I do!\"",
  ui_story_5083_50830100_29_dialog_content = "\"Love my weapon, yes I do!\"",
  ui_story_5083_50830100_30_dialog_content = "\"Got a whole lotta ammo ready for you—\"",
  ui_story_5083_50830100_31_dialog_content = "<size=45>Ooooooh!</size>",
  ui_story_5083_50830100_32_dialog_content = "Heh, you finally caught up, Barton.",
  ui_story_5083_50830100_33_dialog_content = "Huff—Huff—That was nothing!",
  ui_story_5083_50830100_34_dialog_content = "You sure about that? Judging from how winded you look, I'm pretty sure I'm winning this last lap.",
  ui_story_5083_50830100_35_dialog_content = "Heh... Let's... just see about that!",
  ui_story_5083_50830100_36_dialog_content = "Those two idiots...",
  ui_story_5083_50830100_37_dialog_content = "<color=#e8d9bb>The two soldiers struggle desperately for the lead, leaving the rest of the 2nd Legion far behind.</color>",
  ui_story_5083_50830100_38_dialog_content = "<color=#e8d9bb>Unwilling to admit defeat, they pour all of their heart and strength into taking first place.</color>",
  ui_story_5083_50830100_39_dialog_content = "<color=#e8d9bb>Faster and faster, they push themselves until—</color>",
  ui_story_5083_50830100_40_dialog_content = "<size=45>Hraaaaahhhh!!!</size>",
  ui_story_5083_50830100_41_dialog_content = "<color=#e8d9bb>Using the last of their energy, the two leap across the finish line and fall flat on their faces.</color>",
  ui_story_5083_50830100_42_dialog_content = "*gasping* W-Well? You convinced yet?",
  ui_story_5083_50830100_43_dialog_content = "Even after giving you a head start, I still caught up.",
  ui_story_5083_50830100_44_dialog_content = "Hmph... I was just conserving my energy earlier... Besides, you didn't actually win did you?",
  ui_story_5083_50830100_45_dialog_content = "<color=#e8d9bb>As the rest of the soldiers cross the finish line one by one, the whistle sounds again—</color>",
  ui_story_5083_50830100_46_dialog_content = "Training's over for today, so why are you grunts still laying around? By now, you're usually stuffing your faces in the mess hall!",
  ui_story_5083_50830100_47_dialog_content = "What's the matter? Can't stand up, can you?",
  ui_story_5083_50830100_48_dialog_content = "You wish. Let's go!",
  ui_story_5083_50830100_49_dialog_content = "I wonder what's for lunch today...",
  ui_story_5083_50830100_50_dialog_content = "Anything but another energy bar in my oatmeal! I've had enough of that.",
  ui_story_5083_50830100_51_dialog_content = "Look, Barton... Check your 9 o'clock.",
  ui_story_5083_50830100_52_dialog_content = "The mess hall's packed today... No, wait, What's going on over there?",
  ui_story_5083_50830100_53_dialog_content = "Lieutenant Reinhardt! You're so strong! How can I train to be as tough as you?",
  ui_story_5083_50830100_54_dialog_content = "Train hard, I suppose.",
  ui_story_5083_50830100_55_dialog_content = "Is it alright if I train with you next time, Lieutenant?",
  ui_story_5083_50830100_56_dialog_content = "Sure, as long as you can keep up. My training can get a little tough at times.",
  ui_story_5083_50830100_57_dialog_content = "Could you look over here, Lieutenant? Smile at the camera—",
  ui_story_5083_50830100_58_dialog_content = "Hahaha, cheese!",
  ui_story_5083_50830100_59_dialog_content = "What's this about?",
  ui_story_5083_50830100_60_dialog_content = "I hear she graduated two years early, just like you. Apparently we have another <color=#FFB400>super cadet</color> on our hands.",
  ui_story_5083_50830100_61_dialog_content = "But unlike you, she's always surrounded by a crowd. Maybe it means your personality could use some work, eh, Barton?",
  ui_story_5083_50830100_62_dialog_content = "... Still, it's hard to imagine that someone like her is on the same level as you.",
  ui_story_5083_50830100_63_dialog_content = "A worthy opponent...",
  ui_story_5083_50830100_64_dialog_content = "Oh? Someone interesting just appeared...",
  ui_story_5083_50830100_65_dialog_content = "I'm sorry?",
  ui_story_5083_50830100_66_dialog_content = "It's nothing. Now, could you please step aside? I'm pretty hungry.",
  ui_story_5083_50830100_67_dialog_content = "P-Please let me sit with you—",
  ui_story_5083_50830100_68_dialog_content = "She's clearly just a new recruit with no real accomplishments to speak of. From what I've heard, she only gets this kind of attention because the committee is supporting her.",
  ui_story_5083_50830100_69_dialog_content = "Humph, just another showpiece for the higher-ups. She's no match for you... And even less of a match for me!",
  ui_story_5083_50830100_70_dialog_content = "That light...",
  ui_story_5083_50830100_71_dialog_content = "What?",
  ui_story_5083_50830100_72_dialog_content = "Interesting... She gives off an undeniable light, one that makes it hard for me to look away.",
  ui_story_5083_50830100_73_dialog_content = "Something tells me that one of us is going to be Grand Marshal in the future.",
  ui_story_5083_50830100_74_dialog_content = "It takes a lot more to decide on a new Grand Marshal... Hang on, don't tell me you're blinded by that phony's light too?",
  ui_story_5083_50830100_75_dialog_content = "... Oh, no! These jerks are going to eat all the good stuff if we don't get in there right now!",
  ui_story_5083_50830100_76_dialog_content = "Hey, wait for me!",
  ui_story_5083_50830100_77_dialog_content = "We had to fight tooth and nail for a couple of fruit cans. Our meals were even scarier than our training sessions sometimes.",
  ui_story_5083_50830100_78_dialog_content = "I want an apple one. What about you?",
  ui_story_5083_50830100_79_dialog_content = "I don't care, just give me whatever's left... Hey!",
  ui_story_5083_50830100_80_dialog_content = "Oops!",
  ui_story_5083_50830100_81_dialog_content = "Look, it's the girl who crushed you in the last competition! I hear she already made Tech Officer.",
  ui_story_5083_50830100_82_dialog_content = "No one asked for an introduction, now give me back that can!",
  ui_story_5083_50830100_83_dialog_content = "Oh yeah, you're that one guy... Uh... Ah, whatever! Good game, fellow soldier!",
  ui_story_5083_50830100_84_dialog_content = "It's Barton! You didn't even try to remember my name, did you?!",
  ui_story_5083_50830100_85_dialog_content = "Sorry, it's just that I eliminated you so easily, along with a bunch of other people.",
  ui_story_5083_50830100_86_dialog_content = "Tch... We'll decide on the real winner next time, Gronru! Mark my words!",
  ui_story_5083_50830100_87_dialog_content = "Just you wait... I'll win everything back and more!",
  ui_story_5083_50830100_88_dialog_content = "I don't think I've ever seen a soldier wash dishes with so much fury, Barton. I gotta say, I'm impressed!",
  ui_story_5083_50830100_89_dialog_content = "... C-Commander!",
  ui_story_5083_50830100_90_dialog_content = "The sun must've risen over the undercity this morning. You usually just rinse the dishes before tossing them aside, but now you're washing them as though your life depends on it.",
  ui_story_5083_50830100_91_dialog_content = "Tell me, did you hit your head or something?",
  ui_story_5083_50830100_92_dialog_content = "Not at all, sir!",
  ui_story_5083_50830100_93_dialog_content = "Then tell me what's going through it right now.",
  ui_story_5083_50830100_94_dialog_content = "I don't know, sir. I think I need a day off to sort things out!",
  ui_story_5083_50830100_95_dialog_content = "Trouble balancing work and rest? Or maybe that battle had too much of an impact on you? You're not still feeling the fear, are you?",
  ui_story_5083_50830100_96_dialog_content = "No, sir. That's not it!",
  ui_story_5083_50830100_97_dialog_content = "Then pull yourself together, soldier! But again, you're a lot more productive like this—",
  ui_story_5083_50830100_98_dialog_content = "Wow!",
  ui_story_5083_50830100_99_dialog_content = "But you're still weak and full of openings! You really think you can be the shining star of the 2nd Legion?",
  ui_story_5083_50830100_100_dialog_content = "Sir, I wasn't expecting a sneak attack from someone I trust!",
  ui_story_5083_50830100_101_dialog_content = "I taught you to always keep your guard up and your weapons ready. If you had done as I instructed, I never would've been able to take you by surprise so easily.",
  ui_story_5083_50830100_102_dialog_content = "You don't seem convinced, but any strategy that leads to victory is right! Not all problems require a direct approach, and in war, results are all that matter.",
  ui_story_5083_50830100_103_dialog_content = "Looks like you still need some tempering before you can be used in battle.",
  ui_story_5083_50830100_104_dialog_content = "Head back to the training grounds and give me twenty more laps at your usual speed!",
  ui_story_5083_50830100_105_dialog_content = "... Yes, sir!",
  ui_story_5083_50830100_106_dialog_content = "Awfully quiet out here, isn't it? How am I supposed to know if you're actually running, soldier?! Let me hear you sing out loud!",
  ui_story_5083_50830100_107_dialog_content = "Yes, sir!",
  ui_story_5083_50830100_108_dialog_content = "\"I don't know what I've been told!\"",
  ui_story_5083_50830100_109_dialog_content = "Louder!",
  ui_story_5083_50830100_110_dialog_content = "<size=45>\"Killing Eclipsites never gets old!\"</size>",
  ui_story_5083_50830100_111_dialog_content = "What the... is Barton doing extra training on the side?",
  ui_story_5083_50830100_112_dialog_content = "You're not getting ahead of me like that!",
  ui_story_5083_50830100_113_dialog_content = "Hey Barton! I caught up to you again!",
  ui_story_5083_50830100_114_dialog_content = "It's not a race, moron.",
  ui_story_5083_50830100_115_dialog_content = "It is now that I'm here, and you're not taking first place on my watch!",
  ui_story_5083_50830100_116_dialog_content = "Argh—Get back here, you idiot!",
  ui_story_5083_50830100_117_dialog_content = "You're the idiot!",
  ui_story_5083_50830100_118_dialog_content = "Hahahaha—",
  ui_story_5083_50830100_119_dialog_content = "Lieutenant Reinhardt?",
  ui_story_5083_50830100_120_dialog_content = "Those two... are interesting.",
  ui_story_5083_50830200_1_dialog_content = "<color=#e8d9bb>A shrill whistle pierces the air.</color>",
  ui_story_5083_50830200_2_dialog_content = "Get dressed and grab your gear!",
  ui_story_5083_50830200_3_dialog_content = "On the double, grunts!",
  ui_story_5083_50830200_4_dialog_content = "Aaaaaahhh—",
  ui_story_5083_50830200_5_dialog_content = "Hnng...?",
  ui_story_5083_50830200_6_dialog_content = "Three, two, one!",
  ui_story_5083_50830200_7_dialog_content = "<color=#e8d9bb>A bucket of ice water drenches Barton, chilling him to the bone and jolting him wide-awake.</color>",
  ui_story_5083_50830200_8_dialog_content = "<size=45>Aaaahhhh!!!</size>",
  ui_story_5083_50830200_9_dialog_content = "Get going, you lazy good-for-nothings! No pain, no gain!",
  ui_story_5083_50830200_10_dialog_content = "If you can't wake up and be combat-ready in under five seconds, how do you expect to survive on the front lines?",
  ui_story_5083_50830200_11_dialog_content = "You need to be as fast and fatal as a bullet! You have ten seconds to get to the training grounds; double the workout for anyone late!",
  ui_story_5083_50830200_12_dialog_content = "And Barton, you get to wear this bucket on your head!",
  ui_story_5083_50830200_13_dialog_content = "If you haven't caught up by the time Dogg gets to his second lap, I'm giving you an extra lap for every second it takes!",
  ui_story_5083_50830200_14_dialog_content = "Crap, I'm cold and soaking wet... I can't get my belt on! Why does it have to be me?!",
  ui_story_5083_50830200_15_dialog_content = "Serves you right! If you had listened to me, stayed vigilant, and always kept your weapons ready, you wouldn't be in such a mess!",
  ui_story_5083_50830200_16_dialog_content = "You think the Eclipsites are gonna wait for you to take a shower and enjoy a nice breakfast? They can attack from anywhere at any time, so we must always stay alert!",
  ui_story_5083_50830200_17_dialog_content = "How am I supposed to protect myself from water in my sleep?!",
  ui_story_5083_50830200_18_dialog_content = "That's your problem, not mine! If you can't keep dry, you can forget about setting an example for anyone!",
  ui_story_5083_50830200_19_dialog_content = "This is completely unreasonable... I'll be fine as long as I have a gun—",
  ui_story_5083_50830200_20_dialog_content = "Guns shouldn't be the first thing you reach for, you moron! Now stop fumbling around with your belt and get going!",
  ui_story_5083_50830200_21_dialog_content = "Dogg's running as fast as he can too! He's not even trying to help me out!",
  ui_story_5083_50830200_22_dialog_content = "Heh! Now show me how you plan on catching up to them.",
  ui_story_5083_50830200_23_dialog_content = "I'm not giving up! <size=45>Watch this!</size>",
  ui_story_5083_50830200_24_dialog_content = "<color=#e8d9bb>Barton roars as he flings the bucket aside and tears his pants into shorts, then dashes madly towards the rest of his group.</color>",
  ui_story_5083_50830200_25_dialog_content = "Even Barton has slow starts sometimes, huh? That's not like him at all...",
  ui_story_5083_50830200_26_dialog_content = "<size=45>I'm coming for you, Dogg!!!</size>",
  ui_story_5083_50830200_27_dialog_content = "Here you are—what the heck's up with that look?!",
  ui_story_5083_50830200_28_dialog_content = "Your clothes are all twisted and torn up... What are you, a clown?! Stop trying to disgrace the 2nd Legion!",
  ui_story_5083_50830200_29_dialog_content = "Shut up! My pants were only stopping me from catching up to you, so what's your excuse for letting me?!",
  ui_story_5083_50830200_30_dialog_content = "You look so ridiculous that I had to slow down and tell you off!",
  ui_story_5083_50830200_31_dialog_content = "Hah! You were clearly afraid just now—",
  ui_story_5083_50830200_32_dialog_content = "<color=#e8d9bb>Suddenly, a person bolts past the two of them, putting a stop to their petty squabbling.</color>",
  ui_story_5083_50830200_33_dialog_content = "Hup, two, three, four...",
  ui_story_5083_50830200_34_dialog_content = "...",
  ui_story_5083_50830200_35_dialog_content = "<color=#e8d9bb>Struck silent, Barton and Dogg try their best to keep up with their newest challenger.</color>",
  ui_story_5083_50830200_36_dialog_content = "Hup, two, three, four...",
  ui_story_5083_50830200_37_dialog_content = "<color=#e8d9bb>Faster and faster, the three of them go... With the rest of the soldiers watching them intently, they finish multiple laps at a breakneck pace—and run straight past the finish line.</color>",
  ui_story_5083_50830200_38_dialog_content = "I won't lose—",
  ui_story_5083_50830200_39_dialog_content = "<color=#e8d9bb>The three cross the finish line at the same time. Utterly exhausted, Barton and Dogg bring themselves to a gradual stop. However—</color>",
  ui_story_5083_50830200_40_dialog_content = "Hup, two, three, four...",
  ui_story_5083_50830200_41_dialog_content = "<color=#e8d9bb>Reinhardt continues running, albeit at a slightly slower pace.</color>",
  ui_story_5083_50830200_42_dialog_content = "No way...",
  ui_story_5083_50830200_43_dialog_content = "She's taking it way too far.",
  ui_story_5083_50830200_44_dialog_content = "We can't let her taunt us like this. Can you still run?",
  ui_story_5083_50830200_45_dialog_content = "Of course I can! Let's—",
  ui_story_5083_50830200_46_dialog_content = "<color=#e8d9bb>The whistle sounds, and every soldier falls in around the commander.</color>",
  ui_story_5083_50830200_47_dialog_content = "Tch, let's go join the others.",
  ui_story_5083_50830200_48_dialog_content = "She's with the 1st Legion, right? She's got some nerve, interrupting the 2nd Legion's training and mocking us like that...",
  ui_story_5083_50830200_49_dialog_content = "Whatever. What's the point of sticking around if we can't even keep up with the 1st Legion's newest rookie?",
  ui_story_5083_50830200_50_dialog_content = "Pfft—",
  ui_story_5083_50830200_51_dialog_content = "If you can't beat me, what makes you think you'll ever catch up to Reinhardt?",
  ui_story_5083_50830200_52_dialog_content = "Not you again... Hmph, don't be so cocky. I just have to keep growing and getting stronger.",
  ui_story_5083_50830200_53_dialog_content = "Oh? So you're not denying that I beat you?",
  ui_story_5083_50830200_54_dialog_content = "That's right. No sense in denying it when I clearly lost—",
  ui_story_5083_50830200_55_dialog_content = "But the real question is... Why are you hanging out in the shade during training?!",
  ui_story_5083_50830200_56_dialog_content = "I'll have you know that as a Tech Officer, I'm doing plenty of serious work right now!",
  ui_story_5083_50830200_57_dialog_content = "Serious work, my foot... And what's with that contraption?",
  ui_story_5083_50830200_58_dialog_content = "Quit screwing around over here, Barton. We're supposed to group up with the others.",
  ui_story_5083_50830200_59_dialog_content = "Don't worry, that old guy can wait a few more seconds—",
  ui_story_5083_50830200_60_dialog_content = "Don't underestimate my latest invention! It has the potential to change the lives of every soldier in Illumina—",
  ui_story_5083_50830200_61_dialog_content = "Introducing the Next-gen Intelligent Assist Drone! Once these go into production, they'll be every soldier's optimal rear guard.",
  ui_story_5083_50830200_62_dialog_content = "Wow! Does this mean you've gotten even stronger since the last Emperor's Cup?",
  ui_story_5083_50830200_63_dialog_content = "Now you're starting to get it! See? You have no idea how much time I spent on this design!",
  ui_story_5083_50830200_64_dialog_content = "Barton!",
  ui_story_5083_50830200_65_dialog_content = "What?!",
  ui_story_5083_50830200_66_dialog_content = "Barton! Dogg! What do you slackers think you're doing?!",
  ui_story_5083_50830200_67_dialog_content = "Change into your uniforms and drag your sorry butts to the Central Tower! You're standing under its light for the rest of the day, no exceptions!!!",
  ui_story_5083_50830200_68_dialog_content = "Wh-What?!?",
  ui_story_5083_50830200_69_dialog_content = "<color=#e8d9bb>The Central Tower. This bustling and well-lit transportation hub serves as the heart of Gannon City—</color>",
  ui_story_5083_50830200_70_dialog_content = "<color=#e8d9bb>As well as a highly-conspicuous place to punish Illumina's more unruly soldiers.</color>",
  ui_story_5083_50830200_71_dialog_content = "...",
  ui_story_5083_50830200_72_dialog_content = "...",
  ui_story_5083_50830200_73_dialog_content = "... Sorry.",
  ui_story_5083_50830200_74_dialog_content = "Huh?",
  ui_story_5083_50830200_75_dialog_content = "I'm the reason you also got...",
  ui_story_5083_50830200_76_dialog_content = "You've been acting real strange the last few days, Barton.",
  ui_story_5083_50830200_77_dialog_content = "Is it because of that battle?",
  ui_story_5083_50830200_78_dialog_content = "I told you not to overthink things, man. You weren't entirely to blame for that.",
  ui_story_5083_50830200_79_dialog_content = "Things just didn't go your way, that's all... So stop sulking already. Otherwise, it won't feel right once I finally beat you.",
  ui_story_5083_50830200_80_dialog_content = "After all... Commander Pango once said you were the most promising of his newest recruits.",
  ui_story_5083_50830200_81_dialog_content = "Huh? He actually complimented me?",
  ui_story_5083_50830200_82_dialog_content = "You really are an idiot sometimes—",
  ui_story_5083_50830200_83_dialog_content = "Thanks, Dogg.",
  ui_story_5083_50830200_84_dialog_content = "?!",
  ui_story_5083_50830200_85_dialog_content = "I almost forgot, but I didn't get to properly thank you for last time.",
  ui_story_5083_50830200_86_dialog_content = "So thanks for coming to my rescue in the nick of time.",
  ui_story_5083_50830200_87_dialog_content = "... I was just following Commander Pango's orders, so don't mention it.",
  ui_story_5083_50830200_88_dialog_content = "Ugh... It's so hot—",
  ui_story_5083_50830200_89_dialog_content = "<color=#e8d9bb>Under the scorching light of the Central Tower, the two soldiers spend the entire day sweating and standing at attention.</color>",
  ui_story_5083_50830200_90_dialog_content = "<color=#e8d9bb>At the end of the day, their merciless commander finally appears and frees them from their punishment—</color>",
  ui_story_5083_50830200_91_dialog_content = "Finally... Another minute and the light of Illumina would've cooked me dry.",
  ui_story_5083_50830200_92_dialog_content = "I'm amazed Dogg still had enough energy to go to the mess hall... Guess I'll go shower first...",
  ui_story_5083_50830200_93_dialog_content = "Beep—Barton sighted.",
  ui_story_5083_50830200_94_dialog_content = "Huh? It's a drone... And it knows who I am?",
  ui_story_5083_50830200_95_dialog_content = "Wait, are you Gronru's drone from earlier today?",
  ui_story_5083_50830200_96_dialog_content = "No, Barton... I am your Navigator.",
  ui_story_5083_50830200_97_dialog_content = "Eh? What's that supposed to mean?",
  ui_story_5083_50830200_98_dialog_content = "I am here to guide you...",
  ui_story_5083_50830200_99_dialog_content = "That doesn't exactly clear things up... You know, in spite of your outdated appearance, I find you quite appealing.",
  ui_story_5083_50830200_100_dialog_content = "... Does this mean drones are standard-issue equipment now?",
  ui_story_5083_50830200_101_dialog_content = "I wouldn't mind that at all! Well, if you're here to guide me, then lead the way!",
  ui_story_5083_50830200_102_dialog_content = "Understood.",
  ui_story_5083_50830200_103_dialog_content = "Beep—Barton, I...",
  ui_story_5083_50830200_104_dialog_content = "I will guide you out of this...",
  ui_story_5083_50830301_1_dialog_content = "Beep—Barton... My sensors indicate that you require a shower...",
  ui_story_5083_50830301_2_dialog_content = "The dormitory showers are currently full. Scanning for alternative options... I have located a public bath house in the residential sector. Now routing... Please follow me.",
  ui_story_5083_50830301_3_dialog_content = "Hey, not bad at all! You're much smarter than any other model I've seen!",
  ui_story_5083_50830301_4_dialog_content = "Maybe I should crack you open and take a look at what's inside?",
  ui_story_5083_50830301_5_dialog_content = "Beep—Beep—Please don't—",
  ui_story_5083_50830301_6_dialog_content = "Just joking, little guy. Dismantling a never-before-seen model like you would probably land me in unspeakable amounts of trouble.",
  ui_story_5083_50830301_7_dialog_content = "Beep—Our destination is 300 meters away. At the next intersection, please take the elevator to the second floor.",
  ui_story_5083_50830301_8_dialog_content = "You really come in handy, little guy! Gannon City can be really tricky to navigate sometimes.",
  ui_story_5083_50830301_9_dialog_content = "I just wish we could use you in the other Undercities!",
  ui_story_5083_50830301_10_dialog_content = "Current location: Residential Sector, Alley 9, Upper Floor... Upcoming location: Central Monument—",
  ui_story_5083_50830301_11_dialog_content = "Wait.",
  ui_story_5083_50830301_12_dialog_content = "Beep—Yes, Barton...?",
  ui_story_5083_50830301_13_dialog_content = "That memorial...",
  ui_story_5083_50830301_14_dialog_content = "Even from here, I can still see it clearly.",
  ui_story_5083_50830301_15_dialog_content = "I wonder... if they names have been added to it already?",
  ui_story_5083_50830301_16_dialog_content = "<color=#e8d9bb>That battle, which took place not long ago, was Barton's very first time experiencing live combat.</color>",
  ui_story_5083_50830301_17_dialog_content = "<color=#e8d9bb>It was a dark and overcast day. The rain fell like countless, endless threads from the sky.</color>",
  ui_story_5083_50830301_18_dialog_content = "Quickly! Move those sandbags to our frontmost line!",
  ui_story_5083_50830301_19_dialog_content = "The second trench on our right flank has been flooded with Eclipsites! Send soldiers to clear it out on the double!",
  ui_story_5083_50830301_20_dialog_content = "We don't have enough sandbags, ma'am!",
  ui_story_5083_50830301_21_dialog_content = "Or soldiers, for that matter... We can't secure all of our positions anymore.",
  ui_story_5083_50830301_22_dialog_content = "Have the people finished evacuating yet?",
  ui_story_5083_50830301_23_dialog_content = "No, ma'am... The damage to the Undercity's power core has locked up most of our transport systems, making evacuation much slower.",
  ui_story_5083_50830301_24_dialog_content = "What should we do now?",
  ui_story_5083_50830301_25_dialog_content = "Find whatever you can to reinforce our frontline defenses, and divide the rest of the work among our remaining forces. There's no other choice.",
  ui_story_5083_50830301_26_dialog_content = "Where's Lieutenant Barton? I can't make all the decisions around here, so I'll let him assess the situation.",
  ui_story_5083_50830301_27_dialog_content = "He just got back from the front lines, and is resting in the rear.",
  ui_story_5083_50830301_28_dialog_content = "Scouts! How much longer until those monsters launch another attack?",
  ui_story_5083_50830301_29_dialog_content = "Not long, ma'am! They're replenishing their forces as we speak!",
  ui_story_5083_50830301_30_dialog_content = "Where's the Comms Officer? Have we finished repairing the road yet? How long until Commander Pango and his soldiers get here?!",
  ui_story_5083_50830301_31_dialog_content = "I'm sorry, ma'am, but the entire comms team is gone now.",
  ui_story_5083_50830301_32_dialog_content = "What are your orders, ma'am?",
  ui_story_5083_50830301_33_dialog_content = "Commander Pango and his forces will definitely come. We just have to hold out until then.",
  ui_story_5083_50830301_34_dialog_content = "Six of our Undercities are under attack right now, and there are people out there in greater need of reinforcements than us.",
  ui_story_5083_50830301_35_dialog_content = "If the commander gets held up on the front lines...",
  ui_story_5083_50830301_36_dialog_content = "Then we must hold out for those people too.",
  ui_story_5083_50830301_37_dialog_content = "How can we... I still have family back home...",
  ui_story_5083_50830301_38_dialog_content = "I'm sorry... But I can't promise you anything right now.",
  ui_story_5083_50830301_39_dialog_content = "Our duty is to protect this place with our lives. We can't afford to let any Eclipsites get past us.",
  ui_story_5083_50830301_40_dialog_content = "Our Illumina comrades are counting on us to protect them...",
  ui_story_5083_50830301_41_dialog_content = "If we must die, we die with honor on the battlefield.",
  ui_story_5083_50830301_42_dialog_content = "I'm scared... My mother gave me a brand-new scarf before I left, but now... I don't even remember when it got burned away like this...",
  ui_story_5083_50830301_43_dialog_content = "...",
  ui_story_5083_50830301_44_dialog_content = "... I know it's wrong of me to do this, but have someone wake Lieutenant Barton up right now.",
  ui_story_5083_50830301_45_dialog_content = "Maybe he'll know what to do.",
  ui_story_5083_50830301_46_dialog_content = "Lieutenant Barton—Lieutenant—",
  ui_story_5083_50830301_47_dialog_content = "What is it? It feels like I just fell asleep... But it's fine. Get some rest too; there's no telling when they'll make a charge again.",
  ui_story_5083_50830301_48_dialog_content = "Sir! Our comms squad has been eliminated, and we have no way of communicating with the rest of the Legion.",
  ui_story_5083_50830301_49_dialog_content = "The Battalion Commander and the Discipline Officer... were also lost while covering our last retreat.",
  ui_story_5083_50830301_50_dialog_content = "Understood... According to the chain of command, I should be in charge now, right?",
  ui_story_5083_50830301_51_dialog_content = "Hand me the map.",
  ui_story_5083_50830301_52_dialog_content = "Our scouts report that the Eclipsites are concentrating on the higher grounds to the north. We have no way of attacking them at range right now.",
  ui_story_5083_50830301_53_dialog_content = "Most of the Undercity's functions were disabled after the first wave of attacks.",
  ui_story_5083_50830301_54_dialog_content = "At this point, we have no way of knowing if or when the commander will arrive with reinforcements.",
  ui_story_5083_50830301_55_dialog_content = "Also... Some of the soldiers believe we should abandon this position and evacuate along with the civilians.",
  ui_story_5083_50830301_56_dialog_content = "But that would mean abandoning the entire Undercity, sir!",
  ui_story_5083_50830301_57_dialog_content = "How many people do we have left?",
  ui_story_5083_50830301_58_dialog_content = "Less than three hundred... We just don't have the numbers to defend this Undercity anymore.",
  ui_story_5083_50830301_59_dialog_content = "... This is way harder than any military simulation, that's for sure.",
  ui_story_5083_50830301_60_dialog_content = "I can't believe that old guy thought we could defend an entire city by ourselves... If we hadn't risked our lives to push our way out, we probably would've died back there.",
  ui_story_5083_50830301_61_dialog_content = "Looks like there's only one option left for us...",
  ui_story_5083_50830301_62_dialog_content = "Lieutenant Barton! <size=45>A messenger has arrived!</size>",
  ui_story_5083_50830301_63_dialog_content = "Come in. Please tell me if you have some good news for us.",
  ui_story_5083_50830301_64_dialog_content = "Yes, sir! Commander Pango's surprise offensive was a huge success, and three undercities have been saved! They're en route to this position as we speak!",
  ui_story_5083_50830301_65_dialog_content = "Your orders are to hold out until they arrive!",
  ui_story_5083_50830301_66_dialog_content = "I thought you said it was good news? Have you seen the state we're in right now?!",
  ui_story_5083_50830301_67_dialog_content = "I'm sorry, sir... Commander Pango knows how hard it must be, but three undercities wouldn't have been saved if it wasn't for the bravery and sacrifices of your soldiers.",
  ui_story_5083_50830301_68_dialog_content = "So please trust in him. Help will be here soon enough, sir.",
  ui_story_5083_50830301_69_dialog_content = "The Eclipsites are on the move, Lieutenant Barton. What are your orders?",
  ui_story_5083_50830301_70_dialog_content = "If we retreat into the Undercity before the evacuation is complete, there's no guarantee that the Eclipsites won't just go around us...",
  ui_story_5083_50830301_71_dialog_content = "But this position is already in shambles... It won't be easy to keep it from getting overrun—",
  ui_story_5083_50830301_72_dialog_content = "So we charge in.",
  ui_story_5083_50830301_73_dialog_content = "I'm sorry?",
  ui_story_5083_50830301_74_dialog_content = "As commanding officer, I'm ordering all soldiers to prepare to charge into the enemy!",
  ui_story_5083_50830301_75_dialog_content = "We can't let those monsters get away with this!",
  ui_story_5083_50830301_76_dialog_content = "Think of the people counting on us! Think of your parents back in Gannon City... Are you willing to roll over and die like cowards in this place?",
  ui_story_5083_50830301_77_dialog_content = "P-Please calm down, Lieutenant! Commander Pango's orders were to hold this position!",
  ui_story_5083_50830301_78_dialog_content = "How could you say that? We've been fighting non-stop for ten days straight. Are you seriously suggesting we just hole up here and wait for the inevitable?",
  ui_story_5083_50830301_79_dialog_content = "Can't you smell the fear in their hearts? Because I can, and I refuse to let them die here!",
  ui_story_5083_50830301_80_dialog_content = "The soldiers of the 2nd Legion never back down and never surrender!",
  ui_story_5083_50830301_81_dialog_content = "If we're all going to die, then at least we'll go out in a blaze of glory!",
  ui_story_5083_50830301_82_dialog_content = "Barton... You...",
  ui_story_5083_50830301_83_dialog_content = "We're charging straight into the enemy, and we won't stop until we force them to retreat!",
  ui_story_5083_50830301_84_dialog_content = "<size=45>All forces, grab your weapons and steel your resolve—</size>",
  ui_story_5083_50830301_85_dialog_content = "<size=45>CHAAARGE!!!</size>",
  ui_story_5083_50830302_1_dialog_content = "<color=#e8d9bb>Barton's call to arms rings out in the bleakness of the predawn light. As flames threaten to engulf the Undercity, a brutal struggle unfolds.</color>",
  ui_story_5083_50830302_2_dialog_content = "Keep firing! Don't let up!",
  ui_story_5083_50830302_3_dialog_content = "We caught them off-guard! Now's our chance—",
  ui_story_5083_50830302_4_dialog_content = "Roar!",
  ui_story_5083_50830302_5_dialog_content = "Don't stop! Our goal is to retake the high ground and give our forces a chance to transport our heavy artillery up there!",
  ui_story_5083_50830302_6_dialog_content = "<color=#e8d9bb>The bugle continues to signal their advance, and the brave soldiers of Illumina press further into the enemy's ranks.</color>",
  ui_story_5083_50830302_7_dialog_content = "Graaaaaah!",
  ui_story_5083_50830302_8_dialog_content = "Keep going!",
  ui_story_5083_50830302_9_dialog_content = "<color=#e8d9bb>Whenever the soldier holding the bugle falls, another quickly takes their place.</color>",
  ui_story_5083_50830302_10_dialog_content = "Where are the gunners? Don't fall behind just yet!",
  ui_story_5083_50830302_11_dialog_content = "<color=#e8d9bb>In this meat grinder of a battlefield, Barton's face is already covered in blood and sweat. Even so, he still leads the charge with Illumina's banner held high.</color>",
  ui_story_5083_50830302_12_dialog_content = "I'll cover you, now go!",
  ui_story_5083_50830302_13_dialog_content = "<color=#e8d9bb>With a flag in one hand and his comrade's firearm in the other, he opens fire on the Eclipsites as they spill down the slope—</color>",
  ui_story_5083_50830302_14_dialog_content = "You're not taking this back from me!!!",
  ui_story_5083_50830302_15_dialog_content = "<color=#e8d9bb>With a single powerful thrust, Barton pierces the Eclipsite with his banner and plants it firmly at the top of the hill. Soon, the light of Illumina shines into the eyes of every soldier present—</color>",
  ui_story_5083_50830302_16_dialog_content = "Come and get me, you filthy monsters!",
  ui_story_5083_50830302_17_dialog_content = "Barton—!",
  ui_story_5083_50830302_18_dialog_content = "That voice... Dogg?!",
  ui_story_5083_50830302_19_dialog_content = "<color=#e8d9bb>As dawn breaks, Barton finally sees the battlefield through his bloodstained vision. In the distance, an entire battalion of soldiers appears.</color>",
  ui_story_5083_50830302_20_dialog_content = "You idiot... I can't believe you ran straight into the belly of the beast!",
  ui_story_5083_50830302_21_dialog_content = "Guess there's no going back now... All forces, prepare to charge at the enemy!",
  ui_story_5083_50830302_22_dialog_content = "Protect the high ground at all costs, so that Lieutenant Barton can continue laying suppressive fire!",
  ui_story_5083_50830302_23_dialog_content = "Yes, sir!",
  ui_story_5083_50830302_24_dialog_content = "Hahaha! My backup's finally here, Eclipsites—now die!",
  ui_story_5083_50830302_25_dialog_content = "<color=#e8d9bb>The bugle signals charge after bloody charge. The valiant soldiers of Illumina continue their relentless assault, and soon, the dark tide ebbs away under the light of dawn.</color>",
  ui_story_5083_50830302_26_dialog_content = "<color=#e8d9bb>As the sun shines down on the battlefield, the bodies of countless soldiers are seen forming a barricade around the Undercity. Even in death, they continue to defend their home.</color>",
  ui_story_5083_50830302_27_dialog_content = "Hey Barton... You still alive?",
  ui_story_5083_50830302_28_dialog_content = "Urgh... I think so... Can't see through all this blood on my face, but I don't seem to be missing any important parts.",
  ui_story_5083_50830302_29_dialog_content = "You moron...",
  ui_story_5083_50830302_30_dialog_content = "You were about to die in this place, you know that? What a nightmare...",
  ui_story_5083_50830302_31_dialog_content = "Shh! Hear that?",
  ui_story_5083_50830302_32_dialog_content = "<color=#e8d9bb>As the sun grows brighter, a powerful horn rings out without stopping—</color>",
  ui_story_5083_50830302_33_dialog_content = "It's our main force... The old man's finally here...",
  ui_story_5083_50830302_34_dialog_content = "They seriously... Showed up when they said they would... Damn...",
  ui_story_5083_50830302_35_dialog_content = "Dogg! Barton!",
  ui_story_5083_50830302_36_dialog_content = "... Where in the hell are those two knuckleheads?!",
  ui_story_5083_50830302_37_dialog_content = "<color=#e8d9bb>Upon seeing the piles of bodies strewn across the battlefield, the iron-blooded commander of the 2nd Legion murmurs in a quivering tone.</color>",
  ui_story_5083_50830302_38_dialog_content = "All those kids... No...",
  ui_story_5083_50830302_39_dialog_content = "Dogg! Barton! You... You damned fools!!! Don't tell me...",
  ui_story_5083_50830302_40_dialog_content = "You...",
  ui_story_5083_50830302_41_dialog_content = "You idiots are still alive!",
  ui_story_5083_50830302_42_dialog_content = "Commander... Our mission... is complete, sir.",
  ui_story_5083_50830302_43_dialog_content = "Sorry old man... We didn't give up any part of the Undercity... but... a few things might've gotten banged up during the fight...",
  ui_story_5083_50830302_44_dialog_content = "That's right... By pushing back the Eclipsites, you protected this Undercity and prevented the other two from getting invaded... You won, boys.",
  ui_story_5083_50830302_45_dialog_content = "Barton... this is your first time leading troops and the casualty ratio is already almost one to ten?!",
  ui_story_5083_50830302_46_dialog_content = "<size=45>How dare you!!!</size> I should have you court-martialed for disobeying orders and playing the hero!!!",
  ui_story_5083_50830302_47_dialog_content = "Getting yourself killed is one thing, but you nearly got Dogg killed too!",
  ui_story_5083_50830302_48_dialog_content = "But we're still alive, aren't we?",
  ui_story_5083_50830302_49_dialog_content = "None of this would've happened if you had just listened to me!",
  ui_story_5083_50830302_50_dialog_content = "I'll record this incident in the report and deem your first time in command a complete failure!",
  ui_story_5083_50830302_51_dialog_content = "What?! But you gave us an impossible mission! If we hadn't taken the fight to the Eclipsites, we would've gotten overrun a long time ago!",
  ui_story_5083_50830302_52_dialog_content = "Hey! Get back here, you stinkin' old man! I demand a better explanation than that!!",
  ui_story_5083_50830302_53_dialog_content = "Damn it... He didn't see how bad it was here, and he's still giving me grief... We nearly got trapped in this hellhole!",
  ui_story_5083_50830302_54_dialog_content = "Give it a rest, Barton. The commander's just worried about you.",
  ui_story_5083_50830302_55_dialog_content = "He's only chewing you out because you nearly died, that's all.",
  ui_story_5083_50830302_56_dialog_content = "As soon as he realized our comms were down, he sent me and my team ahead to provide reinforcements.",
  ui_story_5083_50830302_57_dialog_content = "...",
  ui_story_5083_50830302_58_dialog_content = "Now get up. It's time for us to go back...",
  ui_story_5083_50830302_59_dialog_content = "We won? We won! I actually survived...",
  ui_story_5083_50830302_60_dialog_content = "But the platoon leader and the others...",
  ui_story_5083_50830302_61_dialog_content = "Almost all of them fell in battle...",
  ui_story_5083_50830302_62_dialog_content = "An entire battalion of soldiers... as well as the reinforcements...",
  ui_story_5083_50830302_63_dialog_content = "... When I got up just now, I realized that the commander had been searching for our bodies the whole time... Is that why his voice was shaking earlier?",
  ui_story_5083_50830302_64_dialog_content = "Did I make the wrong call, Dogg?",
  ui_story_5083_50830302_65_dialog_content = "There's no use worrying about that now.",
  ui_story_5083_50830302_66_dialog_content = "There were more Eclipsites than our scouts originally reported.",
  ui_story_5083_50830302_67_dialog_content = "Regardless of what happened, you managed to complete the mission.",
  ui_story_5083_50830302_68_dialog_content = "Not only did you defend this Undercity, you also killed a huge number of Eclipsites.",
  ui_story_5083_50830302_69_dialog_content = "... The brave men and women who fought at your side died honorably and without regrets. I'm sure of it.",
  ui_story_5083_50830302_70_dialog_content = "If... If I hadn't given the order to attack...",
  ui_story_5083_50830302_71_dialog_content = "Would there be more of them standing right now?",
  ui_story_5083_50830302_72_dialog_content = "Don't think about it.",
  ui_story_5083_50830302_73_dialog_content = "This is war, Barton. Unlike our military simulations, nothing is guaranteed out here.",
  ui_story_5083_50830302_74_dialog_content = "Even the greatest commanders have no way of knowing if a battle will go according to their orders.",
  ui_story_5083_50830302_75_dialog_content = "Maps and models can never reflect every part of battle, or the fearless spirit of Illumina's soldiers.",
  ui_story_5083_50830302_76_dialog_content = "Your counteroffensive was successful, and you emerged victorious. Those are the results of your first time in command.",
  ui_story_5083_50830302_77_dialog_content = "Victorious, huh...",
  ui_story_5083_50830302_78_dialog_content = "As for where to improve and how to save even more lives next time... That's for you to think about as we keep moving forward.",
  ui_story_5083_50830302_79_dialog_content = "Maybe you'll make a different call next time. Either way, the outcome of this battle is already decided.",
  ui_story_5083_50830302_80_dialog_content = "And as survivors, we have to shoulder everything. Not just the good, but the bad too.",
  ui_story_5083_50830302_81_dialog_content = "Accepting the outcome of battle, and sharing our victory with the rest...",
  ui_story_5083_50830302_82_dialog_content = "That's all we can do as commanders right now.",
  ui_story_5083_50830400_1_dialog_content = "Beep—You have a new message, Barton.",
  ui_story_5083_50830400_2_dialog_content = "The following message is from Commander Pango of the 2nd Legion, and it does not reflect my personal views—",
  ui_story_5083_50830400_3_dialog_content = "Hey, punk! You're not still lazing around in bed, are you?!",
  ui_story_5083_50830400_4_dialog_content = "Just because it's not training day doesn't mean you get to take it easy!",
  ui_story_5083_50830400_5_dialog_content = "Get your sorry behind to the residential sector! I have a job just for you!",
  ui_story_5083_50830400_6_dialog_content = "And that job is to, uh... Ahem, to make sure no one is selling supplies under the table out there.",
  ui_story_5083_50830400_7_dialog_content = "You have one day to finish the mission! Doesn't matter if you make it or not, as long as you spend the entire day in the residential sector! And don't even think about coming back early, got it?! Dismissed!",
  ui_story_5083_50830400_8_dialog_content = "Sweet!",
  ui_story_5083_50830400_9_dialog_content = "Beep—Why are you so happy? The commander was yelling at you.",
  ui_story_5083_50830400_10_dialog_content = "Ha, you don't know that, do you? We walk past the upper floor of the residential sector all the time, but it's off-limits for hanging out.",
  ui_story_5083_50830400_11_dialog_content = "They're always putting up new buildings down there, so I've always wanted to check it out for myself!",
  ui_story_5083_50830400_12_dialog_content = "Beep—Please stop shaking me...",
  ui_story_5083_50830400_13_dialog_content = "<size=45>Woo-hoo! Time for some fun!!!</size>",
  ui_story_5083_50830400_14_dialog_content = "You're looking pretty spiffy, Barton. I hear you're heading down to the residential sector today?",
  ui_story_5083_50830400_15_dialog_content = "That's right! Anyone need anything from the distribution center? I'm heading down there, so just hand me your vouchers, and I'll grab your stuff.",
  ui_story_5083_50830400_16_dialog_content = "H-Hey! One at a time, or the vouchers will become a mess. Besides, I can only carry so much!",
  ui_story_5083_50830400_17_dialog_content = "The commander said he gave you a mission, but it looks like he just wants to give you a day off.",
  ui_story_5083_50830400_18_dialog_content = "Is that so? Guess his people skills aren't much better than yours, huh?",
  ui_story_5083_50830400_19_dialog_content = "... Just get lost already, you moron!",
  ui_story_5083_50830400_20_dialog_content = "Check it out! It's the new allocation area that they plopped right next to the residential sector!",
  ui_story_5083_50830400_21_dialog_content = "Beep—There must be a better word for it than plopped, Barton...",
  ui_story_5083_50830400_22_dialog_content = "I have no idea what you're talking about. Now point me to the nearest place for fun; I still have plenty of shopping!",
  ui_story_5083_50830400_23_dialog_content = "... What about your mission?",
  ui_story_5083_50830400_24_dialog_content = "Ah, don't worry about it. Even Dogg thinks I'm here for a break, so let's just trust him.",
  ui_story_5083_50830400_25_dialog_content = "Commander Pango practically raised him. I don't think anyone knows the old man better than he does.",
  ui_story_5083_50830400_26_dialog_content = "Now let's go have some fun! Lead the way!",
  ui_story_5083_50830400_27_dialog_content = "Beep—Yes, Barton... I discovered a place known as the Hidden Arcade 60 meters away, in the alleyway to our right.",
  ui_story_5083_50830400_28_dialog_content = "An arcade, huh... Do they really have that kind of thing in the allocation area? We're still at war, after all... Let's go take a look.",
  ui_story_5083_50830400_29_dialog_content = "S-Seriously?! These must be the video games I heard about back in the academy—",
  ui_story_5083_50830400_30_dialog_content = "Welcome to the Hidden Arcade. Though we are still at war, I sincerely hope that you will find some peace and enjoyment here.",
  ui_story_5083_50830400_31_dialog_content = "All of our games were designed and developed by the boss of the arcade. New customers are entitled to one round of free play!",
  ui_story_5083_50830400_32_dialog_content = "If you achieve a high score in Naval King, you can choose a prize that corresponds to your score!",
  ui_story_5083_50830400_33_dialog_content = "Should you fail in your attempt, simply exchange your vouchers for tokens and continue playing for an even higher score!",
  ui_story_5083_50830400_34_dialog_content = "Your boss sounds like a real winner to me! Watch this, I'll beat the entire level in one go!",
  ui_story_5083_50830400_35_dialog_content = "Game Over! Score: 5.",
  ui_story_5083_50830400_36_dialog_content = "I'm sorry sir, but you need a score of 500 for a Naval King t-shirt or a score of 1,000 for the game itself. Would you like to exchange your vouchers for some tokens?",
  ui_story_5083_50830400_37_dialog_content = "Darn right I do! Here you go.",
  ui_story_5083_50830400_38_dialog_content = "Now watch this—!",
  ui_story_5083_50830400_39_dialog_content = "Game Over! Score: 40.",
  ui_story_5083_50830400_40_dialog_content = "Hey, how many vouchers does it cost to buy that Naval King t-shirt?",
  ui_story_5083_50830400_41_dialog_content = "Heheh... Since you've spent enough to obtain VIP status, you now have the privilege of buying it for a 100-point voucher. Would you like to purchase it?",
  ui_story_5083_50830400_42_dialog_content = "Wow Barton, I didn't think you'd like that shirt so much.",
  ui_story_5083_50830400_43_dialog_content = "Wh-What are you doing here?!",
  ui_story_5083_50830400_44_dialog_content = "I happen to be the developer behind all these games! Well, me and Denier.",
  ui_story_5083_50830400_45_dialog_content = "Hardly. You're the one who put in all the work since I don't really care about this stuff.",
  ui_story_5083_50830400_46_dialog_content = "Denier's my junior, by the way!",
  ui_story_5083_50830400_47_dialog_content = "I've heard of you, Barton... Not a bad score you got there.",
  ui_story_5083_50830400_48_dialog_content = "Uh, hi... Listen Gronru, your game machines ate up a bunch of my vouchers.",
  ui_story_5083_50830400_49_dialog_content = "I was supposed to use some of them to buy stuff for my squadmates, so could you...",
  ui_story_5083_50830400_50_dialog_content = "Hahaha, I didn't expect you to be so bad at video games! Still, I'm grateful that you enjoyed them so much.",
  ui_story_5083_50830400_51_dialog_content = "Now I know it'll be a huge hit with everyone!",
  ui_story_5083_50830400_52_dialog_content = "Looks like testing them out here was the right move after all. I even made back some of the money I put into these games!",
  ui_story_5083_50830400_53_dialog_content = "... Wait, so you're running a private business for profit here?",
  ui_story_5083_50830400_54_dialog_content = "I mean, we do offer free trials... So it shouldn't be a problem, right?",
  ui_story_5083_50830400_55_dialog_content = "Sigh, it's a huge problem, Gronru. When you get arrested, try not to drag me down with you.",
  ui_story_5083_50830400_56_dialog_content = "As if! I'll tell them you helped me build all of these game machines!",
  ui_story_5083_50830400_57_dialog_content = "What?! I-I only helped because you ordered me to, Tech Officer!",
  ui_story_5083_50830400_58_dialog_content = "Yes, but you enjoyed it, didn't you?",
  ui_story_5083_50830400_59_dialog_content = "As far as research goes... I guess it was pretty fun.",
  ui_story_5083_50830400_60_dialog_content = "See? And I can tell you're interested in these games too, Barton. Think you can let me off the hook this time?",
  ui_story_5083_50830400_61_dialog_content = "Well, I enjoy tinkering with new gadgets as much as the next guy. Tell you what, give me back the vouchers, and I'll pretend this never happened.",
  ui_story_5083_50830400_62_dialog_content = "Oh, don't be like that! What's wrong with patronizing our establishment a little?",
  ui_story_5083_50830400_63_dialog_content = "After all, every new piece of technology I develop is designed to help out frontline soldiers like you.",
  ui_story_5083_50830400_64_dialog_content = "Help out, huh... Wait, that reminds me! Do you recognize this drone?",
  ui_story_5083_50830400_65_dialog_content = "Huh? Where'd it go?",
  ui_story_5083_50830400_66_dialog_content = "What drone?",
  ui_story_5083_50830400_67_dialog_content = "It's this old-looking drone that came to me earlier today. It calls itself my Navigator!",
  ui_story_5083_50830400_68_dialog_content = "I've been following around and chatting with it all day.",
  ui_story_5083_50830400_69_dialog_content = "Wow, that sounds pretty hi-tech, doesn't it, Denier?",
  ui_story_5083_50830400_70_dialog_content = "Agreed. I don't think Illumina has that kind of intelligent technology yet, and for you to say it's \"old-looking\" makes even less sense...",
  ui_story_5083_50830400_71_dialog_content = "Really? Because I thought you made it. Wonder where the little guy went... Well, I'm sure it can't get lost since it's a navigation drone and all.",
  ui_story_5083_50830400_72_dialog_content = "I'll show it to you next time I get a chance.",
  ui_story_5083_50830400_73_dialog_content = "I'd like to take a look at it as well... Anything that leads to a stronger future will always interest me.",
  ui_story_5083_50830400_74_dialog_content = "Here are your vouchers, Barton. Don't forget to keep this place our little secret, okay?",
  ui_story_5083_50830400_75_dialog_content = "Will do, and thanks! I rarely get the chance to see this part of town, so I'm not ready to go back just yet. How about I treat the two of you to a nice meal?",
  ui_story_5083_50830400_76_dialog_content = "Count me in! I knew you were a good guy, Barton!",
  ui_story_5083_50830400_77_dialog_content = "I've also had my fill of the lab's food, so thanks... And if it's really good, I'd like to recommend it to my sister.",
  ui_story_5083_50830400_78_dialog_content = "Oh yeah! Hey Barton, did you know that her big sister is none other than the great Reinhardt?",
  ui_story_5083_50830400_79_dialog_content = "Don't put it like that, Gronru. It's embarrassing.",
  ui_story_5083_50830400_80_dialog_content = "Really? I couldn't tell at all, since your sister shines brighter than anyone else.",
  ui_story_5083_50830400_81_dialog_content = "... I'll catch up to her someday.",
  ui_story_5083_50830400_82_dialog_content = "Is that so? Because I think you're doing just fine already—Now let's go eat!",
  ui_story_5083_50830400_83_dialog_content = "That wasn't bad at all. Guess I can recommend it to... Her.",
  ui_story_5083_50830400_84_dialog_content = "Hmm... You two really are a lot different from each other.",
  ui_story_5083_50830400_85_dialog_content = "I know you've already seen Reinhardt in action, but you still haven't had a chance to see Denier shine, Barton.",
  ui_story_5083_50830400_86_dialog_content = "You like military simulations, right? Maybe you two could play a match.",
  ui_story_5083_50830400_87_dialog_content = "I'd be fine with any other competition, but a test of combat strategies against a researcher? Sure, bring it on!",
  ui_story_5083_50830400_88_dialog_content = "I didn't ask you to make trouble for me, Gronru... But fine. I accept your challenge, Lieutenant Barton. Fair warning, though: I wouldn't underestimate me if I were you.",
  ui_story_5083_50830400_89_dialog_content = "<color=#e8d9bb>The group returns to Gronru's hidden shop, where Barton and Denier engage in a simulated battle on a sand table.</color>",
  ui_story_5083_50830400_90_dialog_content = "<color=#e8d9bb>Much to Barton's surprise, Denier's tactics are far more vicious and relentless than anything he expected from a researcher.</color>",
  ui_story_5083_50830400_91_dialog_content = "<color=#e8d9bb>By sacrificing pawn after pawn, she presses deeper into Barton's turf, which catches him off-guard. By the time he realizes the precariousness of his situation, he is already moments away from defeat.</color>",
  ui_story_5083_50830400_92_dialog_content = "(This isn't good! I already lost to Gronru; I can't afford to lose to her friend too!)",
  ui_story_5083_50830400_93_dialog_content = "<color=#e8d9bb>Blushing with embarrassment, Barton suddenly slams his next piece into position, damaging Denier's side of the board.</color>",
  ui_story_5083_50830400_94_dialog_content = "<color=#e8d9bb>As she scrambles to reset her pieces, Barton presses his advantage and launches a series of attacks.</color>",
  ui_story_5083_50830400_95_dialog_content = "That was a dirty move, Barton... See? Denier's about to cry...",
  ui_story_5083_50830400_96_dialog_content = "Morals mean nothing on the battlefield; all that matters is winning and losing! My commanding officer taught me to win at all costs, and that's exactly what I'm gonna do!",
  ui_story_5083_50830400_97_dialog_content = "<color=#e8d9bb>Despite his harsh words, the gap was already too difficult to bridge. After placing her pieces back on the sand board, Denier shakily regains her composure.</color>",
  ui_story_5083_50830400_98_dialog_content = "<color=#e8d9bb>Baiting, flanking, and crushing her opponent by constantly sacrificing her pieces... That's how Denier emerged victorious in their battle.</color>",
  ui_story_5083_50830400_99_dialog_content = "Hahahaha! Looks like she's got you beat in both strategy and manners, Barton!",
  ui_story_5083_50830400_100_dialog_content = "You call yourself a lieutenant with those underhanded tactics? Just wait till I tell...",
  ui_story_5083_50830400_101_dialog_content = "Er... W-Wait a minute, you two! You can't tell anyone else about what happened here today! Please!",
  ui_story_5083_50830400_102_dialog_content = "If word gets out, I'll never live it down! <size=45>Please! I'll do anything!!!</size>",
  ui_story_5083_50830500_1_dialog_content = "<color=#e8d9bb>A gloomy-looking Barton reappears at the camp's gates carrying several bags of different sizes. I have to go warn him—</color>",
  ui_story_5083_50830500_2_dialog_content = "Where did you go? You went missing for half the day, you know...",
  ui_story_5083_50830500_3_dialog_content = "Beep—Danger, Barton—",
  ui_story_5083_50830500_4_dialog_content = "What danger? We're in the camp... Huh?",
  ui_story_5083_50830500_5_dialog_content = "<color=#e8d9bb>Reinhardt stands at the center of the 2nd Legion's training grounds, a spear in hand. She appears to have been waiting for a long time.</color>",
  ui_story_5083_50830500_6_dialog_content = "She looks like she's ready to kill someone. Wonder who got on her bad side?",
  ui_story_5083_50830500_7_dialog_content = "...",
  ui_story_5083_50830500_8_dialog_content = "<size=45>Barton—!</size>",
  ui_story_5083_50830500_9_dialog_content = "How dare you use cheap tricks against my sister! I'm gonna teach you a lesson you'll never forget!!",
  ui_story_5083_50830500_10_dialog_content = "What's she, a little kid? How could she tell her sister on me?!",
  ui_story_5083_50830500_11_dialog_content = "Beep—Suggested course of action: RUN!",
  ui_story_5083_50830500_12_dialog_content = "Here's your stuff, everyone! Sorry, but I gotta go—",
  ui_story_5083_50830500_13_dialog_content = "Get back here, you coward!!!",
  ui_story_5083_50830500_14_dialog_content = "<color=#e8d9bb>Reinhardt mercilessly chases after Barton, her blazing spear cutting through the darkness of night all the while.</color>",
  ui_story_5083_50830500_15_dialog_content = "Hey, cut it out already! I'm gonna fight back if this keeps up.",
  ui_story_5083_50830500_16_dialog_content = "Think you can bully me the same way you bullied my sister? Bring it on then!",
  ui_story_5083_50830500_17_dialog_content = "Quit swinging that thing around when you're talking! It's dangerous!",
  ui_story_5083_50830500_18_dialog_content = "<color=#e8d9bb>Barton continues scrambling away from Reinhardt, who refuses to let him go. Before long, the two run the length of three entire streets—</color>",
  ui_story_5083_50830500_19_dialog_content = "Alright, that does it! Take this!",
  ui_story_5083_50830500_20_dialog_content = "Sand? Seriously? You're despicable.",
  ui_story_5083_50830500_21_dialog_content = "Whatever it takes to win! Now take this!",
  ui_story_5083_50830500_22_dialog_content = "<color=#FFB400>Star-Piercing Spear</color>!",
  ui_story_5083_50830500_23_dialog_content = "<color=#e8d9bb>The two fight back and forth across the street, causing no small amount of panic. Soldiers rush over to the scene, but are unsure how to break up the savage scuffle.</color>",
  ui_story_5083_50830500_24_dialog_content = "Hope you're ready for my water-pipe style!",
  ui_story_5083_50830500_25_dialog_content = "Take that!",
  ui_story_5083_50830500_26_dialog_content = "Haha, not bad! Keep it up!",
  ui_story_5083_50830500_27_dialog_content = "<size=45>Knock it off, you buffoons!</size>",
  ui_story_5083_50830500_28_dialog_content = "Brawling amongst yourselves like a bunch of kids... If you're feeling that restless, then go back to the training grounds and give me a hundred laps each!!!",
  ui_story_5083_50830500_29_dialog_content = "Ugh, this is all your fault. Now I have to run a hundred laps too.",
  ui_story_5083_50830500_30_dialog_content = "You think you don't deserve that after bullying your juniors?",
  ui_story_5083_50830500_31_dialog_content = "You talk as if your sister didn't use the most inhumane tactics to beat me... I'm not sure she needs you to defend her like this at all.",
  ui_story_5083_50830500_32_dialog_content = "Quit all that bickering and pick up the pace, you morons!",
  ui_story_5083_50830500_33_dialog_content = "Feel free to duke it out again once you finish your hundred laps, assuming you can still stand afterward!",
  ui_story_5083_50830500_34_dialog_content = "Huff, huff...",
  ui_story_5083_50830500_35_dialog_content = "Whoa, you're not taking this seriously, are you? Heh... Now I'm really fired up! Let's go!",
  ui_story_5083_50830500_36_dialog_content = "Just try to keep up! I'm still gonna smack you around even if you can't stand!",
  ui_story_5083_50830500_37_dialog_content = "<color=#e8d9bb>The two young soldiers ran around the track with all their strength. As their lap counts increased, their steps also grew more and more fatigued.</color>",
  ui_story_5083_50830500_38_dialog_content = "I'm surprised you were able to catch up... But I'm not done yet!",
  ui_story_5083_50830500_39_dialog_content = "<color=#e8d9bb>Sixty laps, seventy laps... Their footsteps became slow and erratic, as though their legs were full of lead.</color>",
  ui_story_5083_50830500_40_dialog_content = "This punishment might be a bit much, Commander Pango...",
  ui_story_5083_50830500_41_dialog_content = "Did I ask for your opinion? People are still cleaning up the mess they left, you know!",
  ui_story_5083_50830500_42_dialog_content = "Since those arrogant punks love fighting so much, I figured I'd let them suffer a little extra today.",
  ui_story_5083_50830500_43_dialog_content = "<color=#e8d9bb>Eighty laps, ninety laps... The two start to wobble from side to side, but they continue spurring each other on to the end.</color>",
  ui_story_5083_50830500_44_dialog_content = "Hey... Still got any fight left in you?",
  ui_story_5083_50830500_45_dialog_content = "Do you... even have to ask? All I can think about... is how I'm gonna deal with that spear of yours.",
  ui_story_5083_50830500_46_dialog_content = "<color=#e8d9bb>Ninety-nine, one hundred—The commander's whistle signals the end of their grueling punishment, and the two immediately collapse to the ground.</color>",
  ui_story_5083_50830500_47_dialog_content = "Are you... still alive... over there?",
  ui_story_5083_50830500_48_dialog_content = "Yep... still breathing...!",
  ui_story_5083_50830500_49_dialog_content = "Still want... to fight? I'm ready... whenever you are...",
  ui_story_5083_50830500_50_dialog_content = "Heh... I won't fight you... If you can't even stand up, but don't worry, I'll accept any challenge from you any day.",
  ui_story_5083_50830500_51_dialog_content = "Oh yeah...? How noble of you... Hahaha—cough, cough—",
  ui_story_5083_50830500_52_dialog_content = "<color=#e8d9bb>Reinhardt laughs heartily, but a coughing fit quickly puts a stop to it. Nevertheless, she manages to get on her feet and holds out her hand.</color>",
  ui_story_5083_50830500_53_dialog_content = "Coughs, consider yourself my rival. You've earned it.",
  ui_story_5083_50830500_54_dialog_content = "Your commander makes a good point. We're all soldiers of Illumina—a little competition is healthy, but we shouldn't fight amongst ourselves.",
  ui_story_5083_50830500_55_dialog_content = "According to Illumina etiquette, we should shake hands and make amends.",
  ui_story_5083_50830500_56_dialog_content = "You have all the qualities I look for in a person, and I'm sure I'll need your help in the future.",
  ui_story_5083_50830500_57_dialog_content = "Unbelievable... You're even more full of yourself than I thought, and you're still just a new recruit.",
  ui_story_5083_50830500_58_dialog_content = "It won't hurt to tell you, but I have this little dream of becoming Grand Marshal someday.",
  ui_story_5083_50830500_59_dialog_content = "You call that a \"little dream\"? Interesting...",
  ui_story_5083_50830500_60_dialog_content = "Alright, I believe in you! There's no faking the kind of presence you give off, that's for sure.",
  ui_story_5083_50830500_61_dialog_content = "We're square for now, but don't get cocky! We'll have plenty of chances to compete in the future.",
  ui_story_5083_50830500_62_dialog_content = "Looking forward to it.",
  ui_story_5083_50830500_63_dialog_content = "That look in her eyes told me she was dead serious. Her light burns even brighter than the commander's.",
  ui_story_5083_50830500_64_dialog_content = "Hmph, Illumina will be much better off with someone like that in charge... Can't wait to see where she goes!",
  ui_story_5083_50830500_65_dialog_content = "What are you muttering about, Barton? Get over here!",
  ui_story_5083_50830500_66_dialog_content = "Our Legion is finally fully staffed again, so it's time for our customary group photo.",
  ui_story_5083_50830500_67_dialog_content = "Commander Pango stuck around because he wanted to wait for you. No wonder he was so mad when he saw you fighting with Reinhardt instead! Now hurry up and get over here!",
  ui_story_5083_50830500_68_dialog_content = "A group photo... Sure!",
  ui_story_5083_50830500_69_dialog_content = "Here, we saved you a spot right next to Commander Pango.",
  ui_story_5083_50830500_70_dialog_content = "Thanks!",
  ui_story_5083_50830500_71_dialog_content = "Hmph, still walking eh? Guess my training wasn't entirely wasted on you after all.",
  ui_story_5083_50830500_72_dialog_content = "I'm still young and full of life, unlike a certain commander—",
  ui_story_5083_50830500_73_dialog_content = "That's enough, you two... It's time for your speech, Commander.",
  ui_story_5083_50830500_74_dialog_content = "Hmph!",
  ui_story_5083_50830500_75_dialog_content = "Hmph!",
  ui_story_5083_50830500_76_dialog_content = "... Soldiers of the 2nd Legion! We're gathered here today to celebrate your graduation from boot camp! Congratulations on surviving this old man's training program!",
  ui_story_5083_50830500_77_dialog_content = "I'm proud to say that I've molded each and every one of you into the finest warriors of Illumina. But make no mistake: the Eclipsites you'll face in the future are a hundred times more brutal!",
  ui_story_5083_50830500_78_dialog_content = "But as soldiers of the 2nd Legion, we will never back down or surrender! Now, let's get this picture over with, so you can go home and enjoy all three of your hard-earned days off!",
  ui_story_5083_50830500_79_dialog_content = "Three cheers for Commander Pango!",
  ui_story_5083_50830500_80_dialog_content = "Don't thank me yet! The future won't come easy for any of you; once you come back from the front lines, expect more training from your dear old commander! That's all!",
  ui_story_5083_50830500_81_dialog_content = "Alright, now everyone smiles big—Splendor Illumina!",
  ui_story_5083_50830500_82_dialog_content = "<size=45>Splendor Illumina!</size>",
  ui_story_5083_50830600_1_dialog_content = "Vacation time's almost over, so don't let me catch you slacking off!",
  ui_story_5083_50830600_2_dialog_content = "I'll be sure to work hard on my marksmanship, Commander!",
  ui_story_5083_50830600_3_dialog_content = "If you shoot an Eclipsite dead and it falls on you, the ones behind it will jump on you right away. How do you expect to maintain a clear shot under those circumstances?",
  ui_story_5083_50830600_4_dialog_content = "Besides, there are Eclipsites out there that are impervious to guns. What you need to do is train your swordsmanship, Barton!",
  ui_story_5083_50830600_5_dialog_content = "A good melee weapon will never let you down! As long as you remember that when you draw your blade, you'll never find yourself trapped by the enemy!",
  ui_story_5083_50830600_6_dialog_content = "...",
  ui_story_5083_50830600_7_dialog_content = "A soldier of Illumina doesn't fear death! Every day, we fight with our lives to liberate Astra from the Eclipsite scourge! What we do fear, however, is dying a pointless death!",
  ui_story_5083_50830600_8_dialog_content = "That's why staying alive has to be your first priority in battle! Do I make myself clear?!",
  ui_story_5083_50830600_9_dialog_content = "Yes, sir!",
  ui_story_5083_50830600_10_dialog_content = "Then get to work, soldier! Don't squander your time like you did these last two days!",
  ui_story_5083_50830600_11_dialog_content = "... As veteran soldiers, there's no way we can keep losing to the 1st Legion's new recruits.",
  ui_story_5083_50830600_12_dialog_content = "Understood, Commander!",
  ui_story_5083_50830600_13_dialog_content = "Just like Dogg, Commander Pango has a tough time saying what's on his mind.",
  ui_story_5083_50830600_14_dialog_content = "You'd think an old person would be more blunt about things... He must really want me to put Reinhardt in her place, huh?",
  ui_story_5083_50830600_15_dialog_content = "Beep—I'm not sure that's entirely correct, Barton.",
  ui_story_5083_50830600_16_dialog_content = "Hahaha! You're pretty shy for a drone, you know? You always seem to vanish whenever other people show up. Anyway, you're supposed to be my Navigator, right?",
  ui_story_5083_50830600_17_dialog_content = "... Do you need directions?",
  ui_story_5083_50830600_18_dialog_content = "Nah, but there is one place I want to see today. Let's go.",
  ui_story_5083_50830600_19_dialog_content = "Beep—You want to spend your last day off at a museum, Barton?",
  ui_story_5083_50830600_20_dialog_content = "That's just how it is with us soldiers; if we're not fighting, we're training for a fight. Besides, every place is basically the same when you live underground.",
  ui_story_5083_50830600_21_dialog_content = "... Still, it'd be nice to have one of Gronru's game machines at home to pass the time.",
  ui_story_5083_50830600_22_dialog_content = "If we weren't at war, I feel like I could play games for the rest of my life.",
  ui_story_5083_50830600_23_dialog_content = "That or set up an exploration team to sail over the seas.",
  ui_story_5083_50830600_24_dialog_content = "<color=#FFB400>Peace</color>... Haha! Just thinking about it is enough for me.",
  ui_story_5083_50830600_25_dialog_content = "Beep—Activating Illumina Museum guidance mode.",
  ui_story_5083_50830600_26_dialog_content = "<color=#FFB400>Undercity 80</color>, originally the closest sector to the Dark Zone.",
  ui_story_5083_50830600_27_dialog_content = "During the Dark Zone War, this Undercity contributed essential transportation services to the Illumina war effort.",
  ui_story_5083_50830600_28_dialog_content = "Commander Pango mentioned it before, too... According to him, the battle that took place there was especially brutal, and the 2nd Legion was almost entirely wiped out.",
  ui_story_5083_50830600_29_dialog_content = "As kids, we spent a lot of time learning about the past in these museums. We used to be so jealous of these legends... They were the coolest.",
  ui_story_5083_50830600_30_dialog_content = "But now I know the kinds of sacrifices that went into making these legends... And that's not something I want to see anymore.",
  ui_story_5083_50830600_31_dialog_content = "Moving on... The Darkover Crisis, which continues to this day, is believed to have started with the attack on Eraveil two years ago... To the best of our knowledge, the Caelestites were completely...",
  ui_story_5083_50830600_32_dialog_content = "Huh? Why'd you stop all of a sudden...?",
  ui_story_5083_50830600_33_dialog_content = "Yo, Barton.",
  ui_story_5083_50830600_34_dialog_content = "What are you doing here?",
  ui_story_5083_50830600_35_dialog_content = "Brushing up on my history, of course. Illumina's history, the war's history, that kind of stuff.",
  ui_story_5083_50830600_36_dialog_content = "... What do you think Illumina will be like in the future, Barton?",
  ui_story_5083_50830600_37_dialog_content = "Why do you ask?",
  ui_story_5083_50830600_38_dialog_content = "The mysterious Caelestites were wiped out by a single surprise attack. Because of that, us Aurorians will never receive their guidance ever again.",
  ui_story_5083_50830600_39_dialog_content = "The <color=#FFB400>Darkover Crisis</color> still isn't over, and we just keep losing more and more soldiers. Look out the window—You can see the memorial to the fallen from here, can't you?",
  ui_story_5083_50830600_40_dialog_content = "The names of every brother and sister we lost in the war are engraved there... But I can still hear their voices echoing in my head.",
  ui_story_5083_50830600_41_dialog_content = "All of us started learning history from a young age... And the older I get, the closer I feel to the things that are preserved here.",
  ui_story_5083_50830600_42_dialog_content = "After watching my friends give their lives in battle, only for their sacrifices to become history lessons for later generations... I started feeling confused, Barton.",
  ui_story_5083_50830600_43_dialog_content = "Confused?",
  ui_story_5083_50830600_44_dialog_content = "Astra is in mortal danger, and although I'm willing to give my life for its sake, I just can't see its future...",
  ui_story_5083_50830600_45_dialog_content = "You know the people of Lumopolis are fighting with each other now, right? Their promise to help us never materialized, and we've already stopped trading resources with them.",
  ui_story_5083_50830600_46_dialog_content = "All of Astra is in shambles right now. I'm not sure what I'm fighting for anymore, or if we can even win.",
  ui_story_5083_50830600_47_dialog_content = "... Are you afraid?",
  ui_story_5083_50830600_48_dialog_content = "Of course I'm afraid... Luck was the only reason we survived when the rest of our comrades didn't.",
  ui_story_5083_50830600_49_dialog_content = "You told me this was something we had to bear for the rest of our lives. I'm doing my best to live with it...",
  ui_story_5083_50830600_50_dialog_content = "Did you know the Committee has been interfering with the Grand Marshal's plans? They still can't decide on the best way to proceed with the war. Pretty reassuring, huh?",
  ui_story_5083_50830600_51_dialog_content = "Still, I bet my fear is nothing compared to that of the soldiers who came back from the Dark Zone War.",
  ui_story_5083_50830600_52_dialog_content = "As it stands, Illumina doesn't have a clear captain at the helm. Doesn't that scare you, Barton?",
  ui_story_5083_50830600_53_dialog_content = "If that's the case, then we'll do it.",
  ui_story_5083_50830600_54_dialog_content = "You, me, and that Reinhardt girl from the 1st Legion!",
  ui_story_5083_50830600_55_dialog_content = "We're allowed to have a say in things, right?",
  ui_story_5083_50830600_56_dialog_content = "After all, this is the future we're talking about! Who better to face the challenges down the road than the next generation of leaders?",
  ui_story_5083_50830600_57_dialog_content = "No matter what anyone thinks, I'll never back down. I won't let Illumina capsize just because no one can figure out how to steer it!",
  ui_story_5083_50830600_58_dialog_content = "So if you're not sure what to do, just put your life in my hands and I'll lead the way!",
  ui_story_5083_50830600_59_dialog_content = "Heh... Pretty big talk for a guy with absolutely no sea legs.",
  ui_story_5083_50830600_60_dialog_content = "*Sighs* I just... Don't know how you can be so confident while I'm still stuck inside my own head.",
  ui_story_5083_50830600_61_dialog_content = "I'm a child of Illumina too, Barton. There's no telling who will be in charge of this ship in the future.",
  ui_story_5083_50830600_62_dialog_content = "But one thing's for sure: I'm gonna prove to Commander Pango that I'm the elite soldier he's been waiting for all this time!",
  ui_story_5083_50830600_63_dialog_content = "Do whatever you want, Dogg. It's not like I'm trying to impress that old man or anything.",
  ui_story_5083_50830600_64_dialog_content = "Actually, I put in a request before coming here today—I want to put together a commando unit for the 2nd Legion.",
  ui_story_5083_50830600_65_dialog_content = "After what happened last time, I realized that our defenses fall through pretty quickly when we're faced with Eclipsites.",
  ui_story_5083_50830600_66_dialog_content = "That's why I want to establish an <color=#FFB400>assault branch</color> and train soldiers to take the fight to the Eclipsites. I'm sure we'll need fighters like that in the future.",
  ui_story_5083_50830600_67_dialog_content = "If only Lumopolis decided to work with us... They could've helped us with training mounted soldiers.",
  ui_story_5083_50830600_68_dialog_content = "I know technology is going to decide a lot of battles for us in the future... But there's no denying the importance of ground units too.",
  ui_story_5083_50830600_69_dialog_content = "And given that our production levels are still lagging behind, we can only rely on cold steel to carve out a path and keep the enemy at bay.",
  ui_story_5083_50830600_70_dialog_content = "That's some impressive insight, Dogg... I haven't thought about things that much, to be honest.",
  ui_story_5083_50830600_71_dialog_content = "But if that's your plan, then why do you want the commander's approval so badly? Why do you feel like you have to prove yourself?",
  ui_story_5083_50830600_72_dialog_content = "He's our commander, and he trained us up to the best of his abilities. Isn't that reason enough?",
  ui_story_5083_50830600_73_dialog_content = "It is, but I'm sure that's not the only reason.",
  ui_story_5083_50830600_74_dialog_content = "Heh... Despite being a muscle-bound idiot, you can be pretty perceptive sometimes.",
  ui_story_5083_50830600_75_dialog_content = "... My old man was good friends with Commander Pango back in the day. That's how he ended up looking after me.",
  ui_story_5083_50830600_76_dialog_content = "He raised me and took care of me like I was his own. To me, Commander Pango's no different than my father.",
  ui_story_5083_50830600_77_dialog_content = "His son was my older brother, and his wife was my mother.",
  ui_story_5083_50830600_78_dialog_content = "I didn't know the commander had a family... Did something happen to them...?",
  ui_story_5083_50830600_79_dialog_content = "Six years ago, the Undercity where we lived fell under attack.",
  ui_story_5083_50830600_80_dialog_content = "But being the soldier that he is, Commander Pango was fighting on the front lines at the time.",
  ui_story_5083_50830600_81_dialog_content = "He sacrificed his wife to evacuate me and the other noncombatants.",
  ui_story_5083_50830600_82_dialog_content = "The commander never spoke about it, but he immediately requested to be transferred away from the front lines. Ever since then, he's refused to lead any defensive operations in the Undercities.",
  ui_story_5083_50830600_83_dialog_content = "... I'm sure he still blames himself for what happened.",
  ui_story_5083_50830600_84_dialog_content = "Is that why the old man... Never sticks around camp for that long?",
  ui_story_5083_50830600_85_dialog_content = "None of it was his fault—I just wish I could make him see that.",
  ui_story_5083_50830600_86_dialog_content = "I'm almost as old as my brother was back then, too... I want Commander Pango to know that one of his sons is still alive.",
  ui_story_5083_50830600_87_dialog_content = "But no matter how hard I try, his eyes... Are always on you.",
  ui_story_5083_50830600_88_dialog_content = "I get jealous of you sometimes, Barton. Is it because I'm not strong enough?",
  ui_story_5083_50830600_89_dialog_content = "At the end of the day... I just want to take my brother's place and fill the hole in the commander's heart.",
  ui_story_5083_50830600_90_dialog_content = "Dogg... As far as I'm concerned, you're already more than enough. There's no reason for you to become anyone else.",
  ui_story_5083_50830600_91_dialog_content = "As much of a pain as you can be, there isn't anyone else in all of Astra like you! You don't have to live in anyone's shadow!",
  ui_story_5083_50830600_92_dialog_content = "I'm sure the old man agrees with me, too. Why else would he be so hard on you as well?",
  ui_story_5083_50830600_93_dialog_content = "And thanks to you, I finally understand just how indirect the guy can be. He'll probably never open up to you about that stuff.",
  ui_story_5083_50830600_94_dialog_content = "Besides, you said you're his <color=#FFB400>kid</color> too, right? I can't think of anyone who wants to see one of their kids trying to replace another.",
  ui_story_5083_50830600_95_dialog_content = "Barton... You...",
  ui_story_5083_50830600_96_dialog_content = "Heh—Hahahaha! Man, I had no idea you had anything other than muscles in your brain!",
  ui_story_5083_50830600_97_dialog_content = "These words really don't suit you at all, Barton. After the scene you caused yesterday, you're the last person who should be giving me advice, hahaha!",
  ui_story_5083_50830600_98_dialog_content = "I'm not joking, Dogg.",
  ui_story_5083_50830600_99_dialog_content = "I know. Thank you, Barton; you've given me a lot to think about.",
  ui_story_5083_50830600_100_dialog_content = "Don't mention it. Just try being a little more direct from now on... Dogg.",
  ui_story_5083_50830700_1_dialog_content = "<color=#e8d9bb>Not long afterward, the Commando Division of the 2nd Legion was officially established, and Dogg was chosen as its commander following his promotion to Major. Barton, on the other hand, was promoted to Captain and made vice-commander of the Mechanized Infantry Battalion.</color>",
  ui_story_5083_50830700_2_dialog_content = "<color=#e8d9bb>But Dogg's concerns proved to be correct, and soon, the severity of the Darkover Crisis reached terrible new heights.</color>",
  ui_story_5083_50830700_3_dialog_content = "<color=#e8d9bb>The Eclipsites breached Illumina's defensive line and began surrounding Undercities 13 and 19, the Federation's foremost defensive installations.</color>",
  ui_story_5083_50830700_4_dialog_content = "<color=#e8d9bb>Communications were disabled early in the fight. By the time a messenger broke out and arrived in Gannon City, the two Undercities had already been under siege for several days.</color>",
  ui_story_5083_50830700_5_dialog_content = "<color=#e8d9bb>An emergency between Gannon City's leaders was called, but even after hours of deliberation, a decision could not be made—</color>",
  ui_story_5083_50830700_6_dialog_content = "We can't wait any longer! With every minute we waste jabbering around over here, who knows how many lives are being lost?!",
  ui_story_5083_50830700_7_dialog_content = "The 2nd Legion is ready to deploy, Grand Marshal. Just give the order and we'll be on our way.",
  ui_story_5083_50830700_8_dialog_content = "According to the messenger, Undercity 13 was only equipped to survive one more day of being under siege. At this point, there's no hope for them.",
  ui_story_5083_50830700_9_dialog_content = "And while Undercity 19's situation seemed less dire, it's highly possible that our forces will only find a dead city full of Eclipsites once they arrive.",
  ui_story_5083_50830700_10_dialog_content = "The defense commander of Undercity 13 is an old war-time friend of yours, Pango. You should know better than anyone—",
  ui_story_5083_50830700_11_dialog_content = "Honorable soldiers like him and his subordinates would sooner blow up the entire Undercity than let it fall into enemy hands!",
  ui_story_5083_50830700_12_dialog_content = "That way, they could prevent the Eclipsites from harnessing our resources and keep Gannon City safe!",
  ui_story_5083_50830700_13_dialog_content = "You're absolutely right! I know those stubborn fools better than most, and that's exactly what they'd do—",
  ui_story_5083_50830700_14_dialog_content = "But I also know how powerful and tenacious they are!",
  ui_story_5083_50830700_15_dialog_content = "There are still plenty of civilians and resources trapped in those cities, and those soldiers are willing to risk their lives for them!",
  ui_story_5083_50830700_16_dialog_content = "They won't leave their cities to die until the bitter end! That's why I know they're waiting for us to save them!",
  ui_story_5083_50830700_17_dialog_content = "Half of my legion is still fighting in the Dark Zone, and you've only just replenished your legion with fresh recruits.",
  ui_story_5083_50830700_18_dialog_content = "And with the 1st Legion too busy fortifying our defenses... Who do we have left to deploy?",
  ui_story_5083_50830700_19_dialog_content = "Even with all of our forces present, defending Gannon City from the Eclipsites wouldn't be easy. Do you really think we can afford to spare any soldiers?",
  ui_story_5083_50830700_20_dialog_content = "And with how far those two Undercities are from us, we wouldn't be able to use trains to send reinforcements. We'd have to send them on foot.",
  ui_story_5083_50830700_21_dialog_content = "With communications down, we don't know what's waiting for us out there. What if our troops get ambushed along the way? They'd be in serious danger!",
  ui_story_5083_50830700_22_dialog_content = "You don't think those two Undercities are in serious danger right now?!?",
  ui_story_5083_50830700_23_dialog_content = "How could you be so heartless, Motor?!",
  ui_story_5083_50830700_24_dialog_content = "You take that back, Pango! Do you have any idea how many soldiers I've lost to the Dark Zone?! You're not the only one who has to worry about people's lives!",
  ui_story_5083_50830700_25_dialog_content = "I'm done listening to this garbage...",
  ui_story_5083_50830700_26_dialog_content = "Barton!",
  ui_story_5083_50830700_27_dialog_content = "Those people treat us like their shields, and yet they toss us to the ground as soon as the going gets tough.",
  ui_story_5083_50830700_28_dialog_content = "You're not at liberty to speak your mind here, soldier.",
  ui_story_5083_50830700_29_dialog_content = "Oh I'm sorry, I'll just see myself out then—Besides, hanging around you people makes me sick.",
  ui_story_5083_50830700_30_dialog_content = "Who do you think you are, talking like that?!",
  ui_story_5083_50830700_31_dialog_content = "Sorry about that, sir. I'm pretty sure his mouth isn't entirely hooked up to his brain.",
  ui_story_5083_50830700_32_dialog_content = "What do you think you're doing, Dogg?! Don't talk like that about your fellow soldier!",
  ui_story_5083_50830700_33_dialog_content = "Are you men done yet?",
  ui_story_5083_50830700_34_dialog_content = "I'm sure your squabbling is very important, but the 1st Legion is still fighting for their lives out there.",
  ui_story_5083_50830700_35_dialog_content = "Tell me, young officers: do you support your commander's decision?",
  ui_story_5083_50830700_36_dialog_content = "Of course, Grand Marshal.",
  ui_story_5083_50830700_37_dialog_content = "... Actually, I believe the 3rd Legion's commander has a point.",
  ui_story_5083_50830700_38_dialog_content = "What? Have you lost it, Dogg?!",
  ui_story_5083_50830700_39_dialog_content = "I told you, I can still hear the voices of my fallen comrades in my head... We can't afford to be careless, or else their sacrifices will have been in vain.",
  ui_story_5083_50830700_40_dialog_content = "... You're dismissed for now.",
  ui_story_5083_50830700_41_dialog_content = "Understood, Commander Pango! I just ask that you and Captain Barton carefully weigh the risks before making any decisions.",
  ui_story_5083_50830700_42_dialog_content = "The children of Illumina grow up under the splendor of the Central Tower! They know full well the righteousness of our cause!",
  ui_story_5083_50830700_43_dialog_content = "Before our soldiers are dispatched to the different Undercities, they're made aware of this possibility well in advance.",
  ui_story_5083_50830700_44_dialog_content = "The time for discussion is over, Pango. We need to work together in order to defend Gannon City.",
  ui_story_5083_50830700_45_dialog_content = "If they're willing to give their lives for Illumina, then it falls to us to make sure their sacrifices are not in vain.",
  ui_story_5083_50830700_46_dialog_content = "If you don't go, then my soldiers and I will!",
  ui_story_5083_50830700_47_dialog_content = "No, Pango.",
  ui_story_5083_50830700_48_dialog_content = "Motor's right: we have almost no knowledge of the situation out there, and we can't afford any more losses. In any case, the 1st Legion won't spare any soldiers for this.",
  ui_story_5083_50830700_49_dialog_content = "We're supposed to be helping each other through this ordeal. Now isn't the time for infighting.",
  ui_story_5083_50830700_50_dialog_content = "If our soldiers see this, their morale will plummet.",
  ui_story_5083_50830700_51_dialog_content = "Grr... We're leaving, Barton!",
  ui_story_5083_50830700_52_dialog_content = "Maintain your position and take no unauthorized actions, Commander! That's an order!",
  ui_story_5083_50830700_53_dialog_content = "Hey, you two. I take it things didn't go too well in there?",
  ui_story_5083_50830700_54_dialog_content = "With that coward in charge of the 1st Legion? Of course not!",
  ui_story_5083_50830700_55_dialog_content = "Don't run off just yet! I'm here to deliver new <color=#FFB400>orders</color>.",
  ui_story_5083_50830700_56_dialog_content = "\"Effective immediately, the 2nd Legion must deploy to Undercities 13 and 19 to provide reinforcements, with Lieutenant Reinhardt and a portion of the 1st Legion also providing support...\"",
  ui_story_5083_50830700_57_dialog_content = "That's more or less the gist of it. How does it sound?",
  ui_story_5083_50830700_58_dialog_content = "You're seriously thinking of falsifying military orders?",
  ui_story_5083_50830700_59_dialog_content = "If you're not willing to help, then we'll handle it on our own.",
  ui_story_5083_50830700_60_dialog_content = "I can dispatch a few of the 1st Legion's squads; the rest of them are more than capable of defending Gannon City along with the 3rd Legion.",
  ui_story_5083_50830700_61_dialog_content = "We may not have much of an impact here, but our presence in those Undercities could mean the difference between life and death.",
  ui_story_5083_50830700_62_dialog_content = "Unfortunately, I don't have nearly enough soldiers for this mission. That's why I wanted to ask the 2nd Legion for help.",
  ui_story_5083_50830700_63_dialog_content = "You know what'll happen to you if we go along with this, don't you?",
  ui_story_5083_50830700_64_dialog_content = "I appreciate your concern, Commander... But saving lives is still more important to me.",
  ui_story_5083_50830700_65_dialog_content = "... You're just a lowly lieutenant. What gave you the confidence to approach us with a stunt like this?",
  ui_story_5083_50830700_66_dialog_content = "My belief is that neither of you would ever abandon your comrades.",
  ui_story_5083_50830700_67_dialog_content = "Are you still undecided, Commander Pango? Because I'm going with her either way.",
  ui_story_5083_50830700_68_dialog_content = "First you disobeyed orders, and now you're forging them? You have some serious audacity, Reinhardt.",
  ui_story_5083_50830700_69_dialog_content = "That's all you have to say after following me all this way?",
  ui_story_5083_50830700_70_dialog_content = "Hah! You think I'm just gonna stand around and let you do whatever you want?",
  ui_story_5083_50830700_71_dialog_content = "Interesting... It looks like we're not the only ones fed up with the upper brass, right? Good! It's about time we call the shots around here!",
  ui_story_5083_50830700_72_dialog_content = "Hmph. Undercity 13 is the most dangerous, so leave that one to me.",
  ui_story_5083_50830700_73_dialog_content = "Be my guest, Wrath. How many soldiers do you need?",
  ui_story_5083_50830700_74_dialog_content = "Since troops are in short supply around here, I'll just take a single platoon.",
  ui_story_5083_50830700_75_dialog_content = "How do you expect to pull this off with just one platoon? Forget it, I'm going along, and I'm bringing more soldiers with me!",
  ui_story_5083_50830700_76_dialog_content = "Wait!",
  ui_story_5083_50830700_77_dialog_content = "As infuriating as Motor can be, his Intelligence Department is almost never wrong.",
  ui_story_5083_50830700_78_dialog_content = "Undercity 13's situation is far from optimistic... From a purely time-based perspective, it's true that the city is beyond saving.",
  ui_story_5083_50830700_79_dialog_content = "If we send too many of our forces, there's a good chance they'll be trapped in battle with no way out.",
  ui_story_5083_50830700_80_dialog_content = "Understood... Then it'll just be you and a small team, Wrath.",
  ui_story_5083_50830700_81_dialog_content = "Don't lose your head in battle. Prioritize evacuation and rescue over anything else, got it?",
  ui_story_5083_50830700_82_dialog_content = "Like I need you to give me orders—Just you wait, Reinhardt. I'm bringing everyone back!",
  ui_story_5083_50830700_83_dialog_content = "Wait, I'll go with you! As a vice-commander, I have plenty of soldiers that will follow me into battle.",
  ui_story_5083_50830700_84_dialog_content = "Let her handle this, Barton. I've seen her strength for myself, and she's the best person for this sort of fight.",
  ui_story_5083_50830700_85_dialog_content = "Undercity 19 is much larger, meaning they have a better chance of surviving longer.",
  ui_story_5083_50830700_86_dialog_content = "But if Undercity 13 has already fallen, it's almost certain that the enemy will concentrate their attacks on Undercity 19 next.",
  ui_story_5083_50830700_87_dialog_content = "Barton! You may be an idiot, but I've molded you into one of the most powerful weapons of Illumina.",
  ui_story_5083_50830700_88_dialog_content = "A large-scale battle like that suits you and our Mechanized Infantry Division perfectly.",
  ui_story_5083_50830700_89_dialog_content = "Unfortunately, the guards in charge of the equipment cache only take orders from the highest command, which means forged orders are completely useless. You'll have to take advantage of their shift change and have your soldiers steal as much as they can.",
  ui_story_5083_50830700_90_dialog_content = "Hang on, are you saying you want us to go first and secure Undercity 19 like we did last time?",
  ui_story_5083_50830700_91_dialog_content = "Just listen to Commander Pango's plan, Barton. Leading the entire 2nd Legion out of Gannon City isn't something we can do on our own.",
  ui_story_5083_50830700_92_dialog_content = "Now hurry, before they have a chance to notice! Save yourself some time by using the main elevator to go up!",
  ui_story_5083_50830700_93_dialog_content = "... Just don't let the Committee catch you before you come to our rescue, old man.",
  ui_story_5083_50830700_94_dialog_content = "Wait! Are all of you serious about doing this?",
  ui_story_5083_50830700_95_dialog_content = "Commander, you and Barton will be branded as traitors if you leave like this—Are you really willing to do that to Illumina? To the people you care about?!",
  ui_story_5083_50830700_96_dialog_content = "Insubordination, falsification of orders, and outright treason... The Grand Marshal won't overlook these crimes so easily.",
  ui_story_5083_50830700_97_dialog_content = "...",
  ui_story_5083_50830700_98_dialog_content = "I don't care about any of that, Dogg. I only have one question for you: Are you coming or not?",
  ui_story_5083_50830700_99_dialog_content = "After everything you told me back in the museum, are you seriously telling me you don't want to save them?",
  ui_story_5083_50830700_100_dialog_content = "Of course I want to save them! But...",
  ui_story_5083_50830700_101_dialog_content = "Maybe we can still persuade the Grand Marshal to help us? If I just tell him everything...",
  ui_story_5083_50830700_102_dialog_content = "Hold it right there, Dogg! Who are you to argue with the Grand Marshal.",
  ui_story_5083_50830700_103_dialog_content = "But without his approval, we can't act on this...",
  ui_story_5083_50830700_104_dialog_content = "Allow me to repeat Barton's question: Are you coming or not?",
  ui_story_5083_50830700_105_dialog_content = "We'd be disobeying orders without his consent... I refuse to commit such a heinous crime against Illumina... And leave me at the mercy of the Committee...",
  ui_story_5083_50830700_106_dialog_content = "The real traitors here are the Grand Marshal and the others! How could they just close their eyes while our allies—",
  ui_story_5083_50830700_107_dialog_content = "That's enough, Lieutenant Reinhardt! I'm perfectly capable of educating my own subordinates, thank you very much!",
  ui_story_5083_50830700_108_dialog_content = "Dogg... I understand your dilemma, so just go back to camp.",
  ui_story_5083_50830700_109_dialog_content = "A misguided bullet has no stopping power, so there's no need for you to come along. If you still feel guilty about this, feel free to report us.",
  ui_story_5083_50830700_110_dialog_content = "N-No, Commander Pango... You have to be the one to give me the order! I'll go anywhere as long as you tell me to—",
  ui_story_5083_50830700_111_dialog_content = "I'm not going to force you!",
  ui_story_5083_50830700_112_dialog_content = "You don't have to be so afraid, Dogg; you've done nothing wrong. But things aren't always as black and white as Illumina's laws.",
  ui_story_5083_50830700_113_dialog_content = "Barton. Lieutenant Reinhardt. It's time to get moving.",
  ui_story_5083_50830700_114_dialog_content = "Come along if that's what you want, but if you can't make that choice, just stay here and cover our return route.",
  ui_story_5083_50830700_115_dialog_content = "Either way, we'll be counting on you.",
  ui_story_5083_50830700_116_dialog_content = "Barton, you idiot... Try not to die before they give the order...",
  ui_story_5083_50830700_117_dialog_content = "<color=#e8d9bb>Reinhardt and Barton take advantage of the guard change and lead their group into the equipment cache, taking as much as they can before anyone can notice.</color>",
  ui_story_5083_50830700_118_dialog_content = "<color=#e8d9bb>When the guards finally discover the rebels' actions, Barton is forced to bring up the rear and escort the last armored car through a storm of gunfire.</color>",
  ui_story_5083_50830700_119_dialog_content = "Hurry! We've disrupted their communications. Now load everything into the main elevator before they cut off the power!",
  ui_story_5083_50830700_120_dialog_content = "Phew—That was a close one. They were definitely shooting to kill just now...",
  ui_story_5083_50830700_121_dialog_content = "*Beeping* Well you did commit the highest act of treason, Barton...",
  ui_story_5083_50830700_122_dialog_content = "Eh? When did you get here?",
  ui_story_5083_50830700_123_dialog_content = "Sorry little guy, but you just boarded a ship full of pirates. There's still time to hop off before the elevator goes any higher, you know?",
  ui_story_5083_50830700_124_dialog_content = "Beep—Barton...",
  ui_story_5083_50830700_125_dialog_content = "Your Navigator would never abandon you—",
  ui_story_5083_50830801_1_dialog_content = "<color=#e8d9bb>In the moonless night, a sea of Eclipsites converges menacingly on the entrance to Undercity 19.</color>",
  ui_story_5083_50830801_2_dialog_content = "<color=#e8d9bb>After days of being under siege, all of the city's short-range cannons are either out of ammunition or completely destroyed. The people within can do nothing but wait for the end in helpless silence.</color>",
  ui_story_5083_50830801_3_dialog_content = "<color=#e8d9bb>At the sole entrance to the Undercity, Illumina's soldiers fight tooth and nail to keep the Eclipsites at bay. Without ammo, they resort to their blades; without blades, they resort to their fists.</color>",
  ui_story_5083_50830801_4_dialog_content = "<color=#e8d9bb>Holding fast to the belief that they are the shields of the Federation, they struggle with no other thought in their minds save for the faintest glimmer of hope.</color>",
  ui_story_5083_50830801_5_dialog_content = "<color=#e8d9bb>\"The messenger made it out. Gannon City will send reinforcements soon.\"</color>",
  ui_story_5083_50830801_6_dialog_content = "<color=#e8d9bb>After ten days, that faint glimmer had started to waver. But just before it could be extinguished, the steadfast soldiers see the answer to their prayers beyond a sea of blood and bones—</color>",
  ui_story_5083_50830801_7_dialog_content = "<size=45>Send them flying!</size>",
  ui_story_5083_50830801_8_dialog_content = "There's our opening! Send in our fighters to fortify that position!",
  ui_story_5083_50830801_9_dialog_content = "Replenish everyone's ammunition before inspecting the city's defenses! Use any short-range cannons that are still operational, and repurpose the rest into single-use cannons!",
  ui_story_5083_50830801_10_dialog_content = "Reinhardt! Go check on the status of the city while we hold the entrance!",
  ui_story_5083_50830801_11_dialog_content = "Cologne! Bring that armored transport car over here!",
  ui_story_5083_50830801_12_dialog_content = "I'm with the reinforcements sent from Gannon City! Who's in charge of this city right now?",
  ui_story_5083_50830801_13_dialog_content = "Our commanding officer died in battle—You can relay any information to me!",
  ui_story_5083_50830801_14_dialog_content = "The Mechanized Infantry Division will stabilize the situation on the surface. Take the rest of your soldiers and begin fortifying your defenses!",
  ui_story_5083_50830801_15_dialog_content = "As for the civilians still trapped here, load any valuable resources into our armored vehicle and use it to evacuate immediately—",
  ui_story_5083_50830801_16_dialog_content = "But what about you and your troops?",
  ui_story_5083_50830801_17_dialog_content = "We're going to stay and defend this place until peace has been restored!",
  ui_story_5083_50830801_18_dialog_content = "We're only the advance team, but don't worry; the rest of our forces will be here soon enough.",
  ui_story_5083_50830801_19_dialog_content = "Stay together and don't give up! We're going to protect this city!",
  ui_story_5083_50830801_20_dialog_content = "<color=#e8d9bb>As the wave of darkness continues its relentless assault, Barton leads his battalion of a dozen tanks straight into the enemy's forces, recklessly determined to turn the tides of battle.</color>",
  ui_story_5083_50830801_21_dialog_content = "<color=#e8d9bb>But in the face of such overwhelming numbers, their strength is far from enough—</color>",
  ui_story_5083_50830801_22_dialog_content = "Damn, our tank's treads are shot and there's a gigantic Eclipsite closing in on us! Sorry, Vice-commander Barton—It was an honor fighting alongside you, sir!",
  ui_story_5083_50830801_23_dialog_content = "No wait, I'll be right there—",
  ui_story_5083_50830801_24_dialog_content = "Splendor Illumina!",
  ui_story_5083_50830801_25_dialog_content = "<color=#e8d9bb>The immobilized tank ignites the rest of its ammunition, resulting in a fiery explosion that engulfs every Eclipsite in the vicinity.</color>",
  ui_story_5083_50830801_26_dialog_content = "<size=45>Eat lead, you filthy monsters!!!</size>",
  ui_story_5083_50830801_27_dialog_content = "Get those close-range guns up and running, and don't be stingy with your shots! Take out as many as you can!",
  ui_story_5083_50830801_28_dialog_content = "We need to push them back before they can do the same to us!",
  ui_story_5083_50830801_29_dialog_content = "<size=45>Yes, sir!!!</size>",
  ui_story_5083_50830801_30_dialog_content = "Reporting in! Undercity 13's defensive systems have been completely disabled. Given the current situation, we estimate that the Eclipsites will breach the shelter in approximately twenty minutes.",
  ui_story_5083_50830801_31_dialog_content = "Comms are still down, and our guerilla team was unable to reach the upper floors to repair the lines. The <color=#FFB400>massive Eclipsite</color> that attacked us earlier is gone, but the city is swarming with smaller Eclipsites.",
  ui_story_5083_50830801_32_dialog_content = "With our power station completely destroyed, the only thing still operational is the city's hidden self-destruct system...",
  ui_story_5083_50830801_33_dialog_content = "As soldiers, we're prepared to go down with the city, but there are still so many civilians and resources inside the shelter...",
  ui_story_5083_50830801_34_dialog_content = "<color=#e8d9bb>The colonel gazes up at the higher reaches of the Undercity in silence. The darkness above is punctuated only by the flickering flames of destruction.</color>",
  ui_story_5083_50830801_35_dialog_content = "The boys who are carrying out our guerilla operations are no more than seventeen years old... They don't deserve to die down here with the rest of us old dogs.",
  ui_story_5083_50830801_36_dialog_content = "This place will soon be an Eclipsite nest... Gannon City isn't coming to save us, but that doesn't mean we can make any more problems for them. I'm sure you understand, sir.",
  ui_story_5083_50830801_37_dialog_content = "... We'll wait eighteen more minutes. If they really manage to breach the shelter, we'll detonate the entire city. At the very least, our people won't die at the hands of the Eclipsites.",
  ui_story_5083_50830801_38_dialog_content = "The people in there must be terrified of the sounds coming from the other side of that door... Are you really willing to put them through eighteen more minutes of that suffering?",
  ui_story_5083_50830801_39_dialog_content = "No, I'm giving them eighteen more minutes of hope! I'm sure some of them... Still think that we'll be the ones who open that door.",
  ui_story_5083_50830801_40_dialog_content = "How cruel... I'm sorry, sir, but I just can't accept that. As Gannon City's frontline defenders, we're destined to sacrifice ourselves for the sake of all Illumina—",
  ui_story_5083_50830801_41_dialog_content = "I don't want anyone to come and save us if it means putting themselves in danger... But... Is it so wrong to believe...",
  ui_story_5083_50830801_42_dialog_content = "That the light of hope can stay lit in our city?",
  ui_story_5083_50830801_43_dialog_content = "Does anyone copy? I repeat, does anyone copy?",
  ui_story_5083_50830801_44_dialog_content = "My name is 2nd Lieutenant Wrath, and I'm here with a team of reinforcements from Gannon City. We managed to infiltrate the upper levels of Undercity 13 and restore communications. Are there any survivors down there?",
  ui_story_5083_50830801_45_dialog_content = "...!",
  ui_story_5083_50830801_46_dialog_content = "No, don't answer her! The city is overrun with Eclipsites; they'll never make it out if they come down here!",
  ui_story_5083_50830801_47_dialog_content = "I know better than anyone that this city is beyond saving! Before long, the Central Tower was going to collapse, starting from the power station; none of us had any hope of escape!",
  ui_story_5083_50830801_48_dialog_content = "Don't let them come down here! Activate the self-destruct sequence before this place falls to the darkness! It's the only way we'll have any hope of rebuilding—",
  ui_story_5083_50830801_49_dialog_content = "I can hear gunfire; you're still fighting down there, which means there must be survivors somewhere. Are they in the shelter? Why aren't you responding?",
  ui_story_5083_50830801_50_dialog_content = "Could it be... That you're worried about us going down there?",
  ui_story_5083_50830801_51_dialog_content = "Still no response, huh? Bunch of stubborn old fools... Looks like we'll have to give them a signal.",
  ui_story_5083_50830801_52_dialog_content = "Reinhardt asked me to come along to keep you from doing anything reckless—You realize that one false move will bring an entire city of Eclipsites down on our heads, right?",
  ui_story_5083_50830801_53_dialog_content = "If justice stays silent, darkness can never be driven away.",
  ui_story_5083_50830801_54_dialog_content = "Can't you sense their despair? This is exactly what Reinhardt would do if she were here!",
  ui_story_5083_50830801_55_dialog_content = "<color=#e8d9bb>Undercity 13 is doomed—No one doubts that this is a hopeless mission.</color>",
  ui_story_5083_50830801_56_dialog_content = "<color=#e8d9bb>But in the darkness and despair, a beacon suddenly appears: a lightning bolt from Gannon City that rips through every fear and doubt.</color>",
  ui_story_5083_50830801_57_dialog_content = "<color=#e8d9bb>Wrath rubs her gloves together vigorously to produce a powerful burst of light and sound, drawing the attention of every Eclipsite toward her.</color>",
  ui_story_5083_50830801_58_dialog_content = "Who says this city is beyond saving?! We're their last ray of hope! Their final salvation!",
  ui_story_5083_50830801_59_dialog_content = "Now listen up! My team and I are heading straight to the bottom floor, and we're killing everything in our way! Get every civilian ready to evacuate before then!",
  ui_story_5083_50830801_60_dialog_content = "... Who in the world are you? Why would you go this far for us? There's no way the Grand Marshal approved of this!",
  ui_story_5083_50830801_61_dialog_content = "I told you already, my name is Wrath—The future Grand Marshal of Illumina! I won't let anyone stop me from carrying out my brand of justice!",
  ui_story_5083_50830801_62_dialog_content = "<color=#e8d9bb>Wrath leads the charge against the Eclipsites surging along the stairwell, her dancing blade cutting a bloody swath through their ranks. Eventually, she reaches the bottom floor of the Undercity.</color>",
  ui_story_5083_50830801_63_dialog_content = "Did you all see that? That soldier is the future of Illumina... The fruit of our dedication and training...",
  ui_story_5083_50830801_64_dialog_content = "She is the \"Phospherus\" we've all dreamed of... Her light... Is absolutely dazzling...",
  ui_story_5083_50830801_65_dialog_content = "Our dream stands shining before us now... How can we afford to let it go out?",
  ui_story_5083_50830801_66_dialog_content = "... I'll make sure the shelter's evacuation route is cleared within the next ten minutes, even if it costs me my life.",
  ui_story_5083_50830801_67_dialog_content = "And I'll lead a team to rendezvous with her. The rest is up to you.",
  ui_story_5083_50830801_68_dialog_content = "<color=#FFB400>The light of Phospherus</color>... No matter what happens, I have to let everyone see it—",
  ui_story_5083_50830801_69_dialog_content = "<color=#e8d9bb>In the outskirts of the Undercity, the flames of war raged on for three days straight with no sign of reinforcements in sight.</color>",
  ui_story_5083_50830801_70_dialog_content = "<color=#e8d9bb>With ammo supplies spent once again, the soldiers resorted to close-quarters combat once more.</color>",
  ui_story_5083_50830801_71_dialog_content = "Hold the line! We have to maintain this position, or else they'll block the entrance!",
  ui_story_5083_50830801_72_dialog_content = "Roar—!",
  ui_story_5083_50830801_73_dialog_content = "Not on my watch!",
  ui_story_5083_50830801_74_dialog_content = "Heh, the old man... I mean, Commander Pango was right! Being able to instinctively switch to a melee weapon against multiple Eclipsites is the best way to go.",
  ui_story_5083_50830801_75_dialog_content = "Are you having a moment of realization there, Barton?",
  ui_story_5083_50830801_76_dialog_content = "Not really; the old commander drilled a certain reflex into me, and I'm just seeing it in action for the first time. Heh, I'm starting to feel right at home in these kinds of battles.",
  ui_story_5083_50830801_77_dialog_content = "We won't be able to hold this position much longer. I suggest you take a team and try to cut an escape route through the enemy. It's our best chance at getting these people back to Gannon City.",
  ui_story_5083_50830801_78_dialog_content = "What about you? Don't tell me you're staying here?",
  ui_story_5083_50830801_79_dialog_content = "I told them that I would fight with them until the end... If we can't defend the Undercity, we'll blow it up and make sure the Eclipsites can't use it in any way.",
  ui_story_5083_50830801_80_dialog_content = "That's not happening, Reinhardt! Commander Pango gave his word that he would come, and he never goes back on his word!",
  ui_story_5083_50830801_81_dialog_content = "... We have no way of communicating with anyone outside the city, and none of our messengers have returned. Do you really trust him that much, Barton?",
  ui_story_5083_50830801_82_dialog_content = "He may be a jerk, but the old man has never lied to me before... So of course I do! I trust him just like I trust you to cover my back!",
  ui_story_5083_50830801_83_dialog_content = "Then I have no reason to doubt him either!",
  ui_story_5083_50830801_84_dialog_content = "Hmph. For the sake of Illumina and all of our fallen comrades... I refuse to surrender to these Eclipsites or run away in disgrace.",
  ui_story_5083_50830801_85_dialog_content = "Then we'll stand back to back and fight until the moment all hope is lost!",
  ui_story_5083_50830801_86_dialog_content = "A large Eclipsite is approaching, Reinhardt! I-I think it might be their leader!",
  ui_story_5083_50830801_87_dialog_content = "Puny soldiers of Illumina—Kneel before me, the unstoppable Duskcaller!",
  ui_story_5083_50830801_88_dialog_content = "An Eclipsite capable of speech? You don't see that every day... Sorry pal, but my legs don't really kneel. If that's a problem, you can take it up with my blade.",
  ui_story_5083_50830801_89_dialog_content = "We're not the kind to surrender, so just save it. I'll let my Star-Piercing Spear show you the true light of Illumina!",
  ui_story_5083_50830801_90_dialog_content = "I have seen Mother hunting the stars of the night sky, drawn by their irresistible will.",
  ui_story_5083_50830801_91_dialog_content = "You pathetic Aurorians merely survive within the dark of the abyss, and yet you dare act with such impunity.",
  ui_story_5083_50830801_92_dialog_content = "The light will soon fade from this place... And Gannon City will share a similar fate. The \"true light of Illumina\" is but a farce...",
  ui_story_5083_50830801_93_dialog_content = "Hey Reinhardt, looks like we got a poet on our hands.",
  ui_story_5083_50830801_94_dialog_content = "No matter how cultured you think you are... You'll never understand, monster.",
  ui_story_5083_50830801_95_dialog_content = "One day, we'll climb out of these trenches and return to a peaceful Astra—That will be our new beginning, and our chance to follow the light anew.",
  ui_story_5083_50830801_96_dialog_content = "Illumina is the dawn that pierces the night and heralds the light of day! Our faith unites us, and by our faith you will be stopped!",
  ui_story_5083_50830801_97_dialog_content = "We are all embers... The sparks of Illumina's splendor! You could never hope to extinguish our light!",
  ui_story_5083_50830801_98_dialog_content = "Couldn't have said it better myself! No matter how many Eclipsites you throw at us, you'll never break our spirit!",
  ui_story_5083_50830801_99_dialog_content = "I will make you pay dearly for your arrogance, weaklings—Attack!",
  ui_story_5083_50830801_100_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5083_50830801_101_dialog_content = "<color=#e8d9bb>An artillery shell suddenly connects with the Eclipsite and explodes, sending it reeling.</color>",
  ui_story_5083_50830801_102_dialog_content = "<color=#e8d9bb>A bugle sounds as Undercity 19's emergency broadcast system begins to ring, signaling the long-awaited arrival of reinforcements.</color>",
  ui_story_5083_50830801_103_dialog_content = "<color=#e8d9bb>The soldiers turn their blood-soaked faces to the horizon. Bathed in light, an entire legion appears and begins marching on the enemy.</color>",
  ui_story_5083_50830801_104_dialog_content = "<color=#e8d9bb>The banner of the 2nd Legion flies above their heads—A symbol of dawn's might.</color>",
  ui_story_5083_50830801_105_dialog_content = "Such impudence... How dare you attack me, foolish Aurorians! You will pay with your blood—",
  ui_story_5083_50830801_106_dialog_content = "Now's our chance, Reinhardt! Attack!",
  ui_story_5083_50830802_1_dialog_content = "Phospherus... No! All of you must die here! Astra is destined for endless suffering... The eternal night will not be stopped!",
  ui_story_5083_50830802_2_dialog_content = "Sorry, but overcoming evil is also the destiny of every hero in stories like this.",
  ui_story_5083_50830802_3_dialog_content = "Have I failed? No! This can't be—",
  ui_story_5083_50830802_4_dialog_content = "There is no escaping your destruction... The bell has begun to toll... The hour of your<color=#FFB400>death</color> is at hand...",
  ui_story_5083_50830802_5_dialog_content = "My brother... Shall continue my glorious work... Ack! <color=#FFB400>Mother</color>...",
  ui_story_5083_50830802_6_dialog_content = "What was he going on about? It sounds like there's still another tough enemy waiting for us out there...",
  ui_story_5083_50830802_7_dialog_content = "I'm not entirely sure... But we survived, and that's all that matters.",
  ui_story_5083_50830802_8_dialog_content = "Third Division, get to work on salvaging the power station! Reestablish communications and send a message back to Gannon City... No, to every single Undercity in the Federation!",
  ui_story_5083_50830802_9_dialog_content = "Tell them that this city can still be saved, and to not give up on it!",
  ui_story_5083_50830802_10_dialog_content = "Sir, we've just received an emergency dispatch from Undercity 13! Please listen to it!",
  ui_story_5083_50830802_11_dialog_content = "... My Comms Officer says that Undercity 19 is safe now. Was that your doing, Pango?",
  ui_story_5083_50830802_12_dialog_content = "Sorry, old friend... I wasn't able to save you myself.",
  ui_story_5083_50830802_13_dialog_content = "Heh, save your apologies. This was the best possible choice, wasn't it? Take good care of that place, and make sure we don't lose it again.",
  ui_story_5083_50830802_14_dialog_content = "That incredible young officer... Wrath, if I'm not mistaken? She's leading everyone out of the shelter as we speak.",
  ui_story_5083_50830802_15_dialog_content = "What?! Commander Pango, let me take a team over there to help her!",
  ui_story_5083_50830802_16_dialog_content = "He's right! I think there's still hope for saving Undercity 13—",
  ui_story_5083_50830802_17_dialog_content = "Shut it, you two! Let the man finish speaking!",
  ui_story_5083_50830802_18_dialog_content = "We've been fighting without rest for the last fifteen days... Aside from me, the rest of our officers have already fallen.",
  ui_story_5083_50830802_19_dialog_content = "But hearing that Undercity 19 is safe puts my heart at peace.",
  ui_story_5083_50830802_20_dialog_content = "You're not evacuating, are you?",
  ui_story_5083_50830802_21_dialog_content = "Undercity 13 is on the verge of collapse, and someone needs to set off the self-destruct sequence... If the way to Gannon City is blocked, the collapse will also be prevented.",
  ui_story_5083_50830802_22_dialog_content = "There's a chance this city will be rebuilt someday... So I'll stay here and wait until that day comes... However...",
  ui_story_5083_50830802_23_dialog_content = "... Some of your soldiers refuse to leave, right?",
  ui_story_5083_50830802_24_dialog_content = "Heh, that's right. After all, I trained every single one of them into the fine soldiers that they are today.",
  ui_story_5083_50830802_25_dialog_content = "I understand... I still have plenty of fighting to do on my side, so I'm requesting your soldiers to join me over here.",
  ui_story_5083_50830802_26_dialog_content = "That's an order.",
  ui_story_5083_50830802_27_dialog_content = "Understood... They're in your hands now, Pango. Promise you'll take good care of them.",
  ui_story_5083_50830802_28_dialog_content = "I promise... Old friend.",
  ui_story_5083_50830802_29_dialog_content = "This is good-bye, Pango... Remember to stay far away from this city.",
  ui_story_5083_50830802_30_dialog_content = "I'll give them the order to evacuate shortly... Splendor Illumina!",
  ui_story_5083_50830802_31_dialog_content = "I salute you, comrade... Splendor Illumina!",
  ui_story_5083_50830802_32_dialog_content = "What are you doing, Commander Pango?! There are still people in Undercity 13, which means there's still hope for them! Why would you take his soldiers from him—",
  ui_story_5083_50830802_33_dialog_content = "Save your breath and go get some rest! From the look on your face, it seems like you're not thinking straight.",
  ui_story_5083_50830802_34_dialog_content = "But...",
  ui_story_5083_50830802_35_dialog_content = "I gave you an order, Barton! Remember your place, soldier!",
  ui_story_5083_50830802_36_dialog_content = "... Tch!",
  ui_story_5083_50830802_37_dialog_content = "You want to save as many of them as you can, don't you?",
  ui_story_5083_50830802_38_dialog_content = "... All we ever wanted was to build up Illumina. But after all these years of fighting, our old eyes are finally starting to get a little blurry.",
  ui_story_5083_50830802_39_dialog_content = "Young soldiers like you are the only ones who can break through to dawn's light. Your eyes are sharper, and so are your minds...",
  ui_story_5083_50830802_40_dialog_content = "Heh, the Grand Marshal and I weren't much older than you when we fought in the Dark Zone War.",
  ui_story_5083_50830802_41_dialog_content = "I'm not sure when it started... But somehow, we ended up just like the people we resented back then.",
  ui_story_5083_50830802_42_dialog_content = "... Splendor Illumina! I salute you, sir.",
  ui_story_5083_50830802_43_dialog_content = "Ah, just go get some rest. I need a moment alone... To send off my old friend.",
  ui_story_5083_50830802_44_dialog_content = "Beep—Barton... My sensors indicate that your spirits are low. Please come with me...",
  ui_story_5083_50830802_45_dialog_content = "?!",
  ui_story_5083_50830802_46_dialog_content = "Still alive, huh? You don't exactly look like it though.",
  ui_story_5083_50830802_47_dialog_content = "Don't be so surprised! Your messenger managed to reach Gannon City, and the Grand Marshal immediately sent reinforcements once he heard that Undercity 19 was secured.",
  ui_story_5083_50830802_48_dialog_content = "We're just here on our orders.",
  ui_story_5083_50830802_49_dialog_content = "... Are you alright?",
  ui_story_5083_50830802_50_dialog_content = "You... You idiot! Could you have gotten here any later?!",
  ui_story_5083_50830802_51_dialog_content = "Do you have any idea how many people we lost?! Damn it!",
  ui_story_5083_50830802_52_dialog_content = "That's all you have to say to me?! If I hadn't fired on that huge Eclipsite earlier, you would've been done for—Moron!",
  ui_story_5083_50830802_53_dialog_content = "Argh—!!!",
  ui_story_5083_50830802_54_dialog_content = "... So why are you so down, Barton? Is it because... Commander Barton was willing to let his friend go like that?",
  ui_story_5083_50830802_55_dialog_content = "Undercity 13 could still be saved... They could be here right now, helping us defend this place... But instead, they're going to blow it up.",
  ui_story_5083_50830802_56_dialog_content = "The old man even had the nerve to take his friend's most loyal soldiers away from him... And leave him there to die alone...",
  ui_story_5083_50830802_57_dialog_content = "Would you rather they die at his side?",
  ui_story_5083_50830802_58_dialog_content = "I'm sure you know exactly how they feel... If we were in the same position, nothing would keep us away from Commander Pango.",
  ui_story_5083_50830802_59_dialog_content = "They'd have to break our legs and lock us in the escape car to get us to leave.",
  ui_story_5083_50830802_60_dialog_content = "...",
  ui_story_5083_50830802_61_dialog_content = "But if Commander Pango agrees with his friend, then that means there's really no saving Undercity 13.",
  ui_story_5083_50830802_62_dialog_content = "There's no reason for so many people to lose their lives in the explosion... By giving them a new mission, he's also giving them a new reason to survive.",
  ui_story_5083_50830802_63_dialog_content = "That's always been one of Illumina's guiding principles.",
  ui_story_5083_50830802_64_dialog_content = "No one's lying or turning their backs to each other, Barton; Undercity 19 is going to keep fighting. Think of it as... An unspoken agreement between two old officers.",
  ui_story_5083_50830802_65_dialog_content = "So when they come up with something as ridiculous as a \"new mission,\" it's just their way of protecting the soldiers they trained with all their hearts.",
  ui_story_5083_50830802_66_dialog_content = "So why not ask them what they think?! I'm sure none of them want to hear their own commander talk about sacrificing himself...",
  ui_story_5083_50830802_67_dialog_content = "It's because they're his kids, Barton. They're all children of Illumina.",
  ui_story_5083_50830802_68_dialog_content = "That's why he's willing to go so far for them...",
  ui_story_5083_50830900_1_dialog_content = "<color=#e8d9bb>After several days of constant fighting, the Eclipsites finally begin to retreat from the plains, revealing the countless scars left on the battlefield.</color>",
  ui_story_5083_50830900_2_dialog_content = "<color=#e8d9bb>Undercity 19 is saved, but the 2nd Legion has lost more than half of its troops.</color>",
  ui_story_5083_50830900_3_dialog_content = "<color=#e8d9bb>Barton lays down on the ground beside his fallen comrades, gazing blankly towards the seemingly-heatless sun.</color>",
  ui_story_5083_50830900_4_dialog_content = "Get up. It's time for us to go.",
  ui_story_5083_50830900_5_dialog_content = "Commander Pango?",
  ui_story_5083_50830900_6_dialog_content = "I'd like to do that... But the soldiers we took that group photo with are still lying here, and they're never going to get up.",
  ui_story_5083_50830900_7_dialog_content = "I came here to save people. I didn't expect so many of my comrades to perish under my command...",
  ui_story_5083_50830900_8_dialog_content = "... Here.",
  ui_story_5083_50830900_9_dialog_content = "Heavy, isn't it? Remember them, Barton; remember their names and their pasts.",
  ui_story_5083_50830900_10_dialog_content = "As the survivors of this battle, it's our duty to carry on.",
  ui_story_5083_50830900_11_dialog_content = "Damned punk, it looks like this fight really knocked the wits out of you. But you still have to keep going, even if it's just to make sure their names get inscribed on that monument!",
  ui_story_5083_50830900_12_dialog_content = "You think I don't know that?! It's just...",
  ui_story_5083_50830900_13_dialog_content = "No excuses, Barton! We have an obligation to make sure their sacrifices weren't in vain! Or do their actions really mean that little to you?!",
  ui_story_5083_50830900_14_dialog_content = "... Good. Now that Undercity 19 is saved, this battle will serve as a message.",
  ui_story_5083_50830900_15_dialog_content = "This is a message to all Undercities, including those who are still fighting on the front lines.",
  ui_story_5083_50830900_16_dialog_content = "Hearing about our victory here today will strengthen everyone's faith... If Undercity 19 could be saved, then so can any of the other Undercities of Illumina.",
  ui_story_5083_50830900_17_dialog_content = "Someday, Astra will be free from the ravages of this war.",
  ui_story_5083_50830900_18_dialog_content = "But that's a conversation for another time. At the very least, we managed to keep the fire of hope alive, and that has to mean something.",
  ui_story_5083_50830900_19_dialog_content = "Even if it means constantly sacrificing our souls to stoke its flames, it'll all be worth it in the end—",
  ui_story_5083_50830900_20_dialog_content = "Hmph—I don't intend to make that many sacrifices once I'm in charge of this ship.",
  ui_story_5083_50830900_21_dialog_content = "If anyone has to burn for hope's sake, then it'll be me. If that day comes, the flames are gonna burn hotter than ever before...",
  ui_story_5083_50830900_22_dialog_content = "<color=#e8d9bb>The message of Undercity 19's salvation spreads throughout Illumina like wildfire. Before the soldiers even return home, Gannon City is already abuzz with news of their victory.</color>",
  ui_story_5083_50830900_23_dialog_content = "<color=#e8d9bb>According to the official report, Barton and the others are hailed as elite heroes deployed by the Grand Marshal himself.</color>",
  ui_story_5083_50830900_24_dialog_content = "<color=#e8d9bb>In light of their outstanding achievements, every criminal charge previously leveled against them is summarily dropped—</color>",
  ui_story_5083_50830900_25_dialog_content = "What is the creed of Illumina, Pango? Tell me right now!",
  ui_story_5083_50830900_26_dialog_content = "\"One for all, and all for one.\"",
  ui_story_5083_50830900_27_dialog_content = "Don't forget the rest of it! \"For the sake of Illumina, all orders must be followed!\"",
  ui_story_5083_50830900_28_dialog_content = "You operate with total disregard for orders, and you teach your subordinates to do the same!",
  ui_story_5083_50830900_29_dialog_content = "If it wasn't for Undercity 19's salvation, things wouldn't have ended nearly so well for you or your soldiers!",
  ui_story_5083_50830900_30_dialog_content = "Your subordinates lost their lives because of your arrogance!",
  ui_story_5083_50830900_31_dialog_content = "We don't consider ourselves fortunate at all, Grand Marshal! We sacrificed so much in order to—",
  ui_story_5083_50830900_32_dialog_content = "Silence!",
  ui_story_5083_50830900_33_dialog_content = "Y-Your name is Barton, right? You think just because you're a hero that you can speak out of turn?!",
  ui_story_5083_50830900_34_dialog_content = "He meant nothing by it, Grand Marshal! My colleague here is simply an idiot!",
  ui_story_5083_50830900_35_dialog_content = "... And you! Do you have any idea how much trouble you caused by following their example—",
  ui_story_5083_50830900_36_dialog_content = "Pardon the interruption, Grand Marshal.",
  ui_story_5083_50830900_37_dialog_content = "A Committee secretary? Who let you in here?!",
  ui_story_5083_50830900_38_dialog_content = "I'm only here to deliver an urgent message from the Committee, sir.",
  ui_story_5083_50830900_39_dialog_content = "With the success of the rescue operation and the publicity surrounding its heroes, morale within Illumina is at an all-time high. The Committee is very pleased with the actions taken by these brave soldiers.",
  ui_story_5083_50830900_40_dialog_content = "Pleased? With them?! Hah!",
  ui_story_5083_50830900_41_dialog_content = "Particularly deserving of praise is Lieutenant Reinhardt... As well as Captain Barton. The Committee believes that these two soldiers should be portrayed as role models for the entire Federation.",
  ui_story_5083_50830900_42_dialog_content = "We're still at war here. This is no time to be playing games!",
  ui_story_5083_50830900_43_dialog_content = "It's precisely because we're at war that the Committee sees the need for such exemplary soldiers to bolster public sentiment.",
  ui_story_5083_50830900_44_dialog_content = "... What exactly do you people have in mind?",
  ui_story_5083_50830900_45_dialog_content = "Why not promote my vice-commander, then? He may be an idiot, but he's skilled enough to take charge of the entire Mechanized Infantry Division.",
  ui_story_5083_50830900_46_dialog_content = "That should be easy enough to arrange, sir. As for you, Lieutenant Reinhardt, we are still discussing a possible reward for you. Would you be so kind as to come with me? Right now, please.",
  ui_story_5083_50830900_47_dialog_content = "Lead the way.",
  ui_story_5083_50830900_48_dialog_content = "If there's nothing else, Grand Marshal, then we'll be taking our leave as well.",
  ui_story_5083_50830900_49_dialog_content = "... You're dismissed.",
  ui_story_5083_50830900_50_dialog_content = "Hang on a second! Dogg, Commander Pango... Didn't something seem off about that meeting just now?",
  ui_story_5083_50830900_51_dialog_content = "That Committee member barely paid attention to the Grand Marshal. He was even ruder to him than me...",
  ui_story_5083_50830900_52_dialog_content = "Say something, would you? I can't be the only one who thinks it's weird! They didn't even bother consulting the Grand Marshal about my promotion!",
  ui_story_5083_50830900_53_dialog_content = "...",
  ui_story_5083_50830900_54_dialog_content = "That's none of your concern, boy.",
  ui_story_5083_50830900_55_dialog_content = "I know the Committee holds a lot of power over us, but—",
  ui_story_5083_50830900_56_dialog_content = "I told you it's none of your concern! There's no point trying to make sense of those people, Barton... Or talking about them, for that matter.",
  ui_story_5083_50830900_57_dialog_content = "Just accept your promotion and work hard to train new recruits for the 2nd Legion—",
  ui_story_5083_50830900_58_dialog_content = "And don't ever let me catch you slacking.",
  ui_story_5083_50831000_1_dialog_content = "Hey, Reinhardt! Got a second to talk?",
  ui_story_5083_50831000_2_dialog_content = "You're from the 2nd Legion, right? What brings you here at a time like this? If you're here to pick a fight, I'm a better opponent than Reinhardt.",
  ui_story_5083_50831000_3_dialog_content = "Calm down Wrath, he's not here to start anything. Commander Barton is a friend of mine.",
  ui_story_5083_50831000_4_dialog_content = "... I've been thinking about it for days now, but I still can't figure it out. Why are they doing this to you, Reinhardt? On top of not promoting you, your own Legion Commander punished you for saving Undercity 19!",
  ui_story_5083_50831000_5_dialog_content = "Let's talk somewhere privately.",
  ui_story_5083_50831000_6_dialog_content = "I'm just gonna go ahead and ask, Reinhardt: what's your connection to the Committee?",
  ui_story_5083_50831000_7_dialog_content = "I'm not stupid; anyone can see that you're connected to them somehow, especially since they never seem to leave you alone.",
  ui_story_5083_50831000_8_dialog_content = "When that secretary barged into the Grand Marshal's meeting room last time, he was actually there for you, wasn't he?",
  ui_story_5083_50831000_9_dialog_content = "What did he want from you? And why... Why aren't they protecting you?",
  ui_story_5083_50831000_10_dialog_content = "As my friend, I've been looking for the right opportunity to tell you about these things, Barton.",
  ui_story_5083_50831000_11_dialog_content = "For starters, you're absolutely right: the Committee does pay special attention to me. As for the reason... Maybe it's because they've chosen me for something.",
  ui_story_5083_50831000_12_dialog_content = "I'm not entirely sure what it is... But it seems like they have a special training plan in mind for me, one that will unlock my full combat potential.",
  ui_story_5083_50831000_13_dialog_content = "That might be the reason they decided to make an appearance during that meeting.",
  ui_story_5083_50831000_14_dialog_content = "As for why they didn't stop my commander from punishing me... I figure it's probably a warning of some sort.",
  ui_story_5083_50831000_15_dialog_content = "A warning, huh... Does this mean Dogg was right about you? Are you only here because someone on the committee is backing you up?",
  ui_story_5083_50831000_16_dialog_content = "Are you seriously that kind of person, Reinhardt?",
  ui_story_5083_50831000_17_dialog_content = "Not even in the slightest! If anything, I'm just a pawn in the grand scheme of things.",
  ui_story_5083_50831000_18_dialog_content = "Even though the Committee is training me to become even stronger... They're just as concerned with keeping me under their control.",
  ui_story_5083_50831000_19_dialog_content = "Barton... If I tell you any more of my story, you'll end up on my \"pirate ship\" just like last time.",
  ui_story_5083_50831000_20_dialog_content = "Are you okay with that?",
  ui_story_5083_50831000_21_dialog_content = "I trusted you with my life before, didn't I? Why would I say no this time?",
  ui_story_5083_50831000_22_dialog_content = "As the fighting intensifies, every soldier has the potential to become fuel for the flames of victory... This is especially true for the people on the Committee.",
  ui_story_5083_50831000_23_dialog_content = "My sister and I, as well as one of my friends, are all a part of their plan... And although they say they're only testing us, something about it doesn't feel right.",
  ui_story_5083_50831000_24_dialog_content = "Not just anyone can withstand their special training, especially not children... After going through it myself, I know just how brutal it can be.",
  ui_story_5083_50831000_25_dialog_content = "After seeing everything that I've seen, I don't believe that the Grand Marshal is ignorant of the Committee's actions... In fact, I think he condones them.",
  ui_story_5083_50831000_26_dialog_content = "I don't doubt the Grand Marshal's conviction towards the war, but I can see the fear and exhaustion in his eyes. The will to keep fighting isn't enough to secure the future, at least not on its own.",
  ui_story_5083_50831000_27_dialog_content = "... You once told me about your <color=#FFB400>little dream</color> of becoming the Grand Marshal someday.",
  ui_story_5083_50831000_28_dialog_content = "It's still true. One day, I'm going to be the strongest and most decisive Grand Marshal of Illumina!",
  ui_story_5083_50831000_29_dialog_content = "I'm sure someone told you not to ask questions about the Committee, right Barton? But the truth is, Illumina will never be able to set sail until we break free from them.",
  ui_story_5083_50831000_30_dialog_content = "Heh, you think this pirate ship of yours is big enough to carry everyone in Illumina?",
  ui_story_5083_50831000_31_dialog_content = "Didn't you know? Even a baby bird must break free from its egg to find its place in the world. To take greater steps forward, we need to free ourselves from our shackles.",
  ui_story_5083_50831000_32_dialog_content = "If we truly want to free all of Astra and begin anew... We have to start by liberating Illumina from the people controlling it from behind the scenes.",
  ui_story_5083_50831000_33_dialog_content = "You have to be serious if you want to rebel against the forces in power.",
  ui_story_5083_50831000_34_dialog_content = "You won't accomplish any of that with words alone, Reinhardt. So tell me, how can I help you?",
  ui_story_5083_50831000_35_dialog_content = "By joining forces with me and helping me root out the corruption in Illumina.",
  ui_story_5083_50831000_36_dialog_content = "Right now, Illumina's soldiers are bound by all kinds of shackles. Unsure of the meaning behind their sacrifices, they simply live and fight, knowing that they may have to die for us someday.",
  ui_story_5083_50831000_37_dialog_content = "And those who refuse to fight get hunted down by the <color=#FFB400>Executioners</color>. Is this really the best that Illumina can hope for?",
  ui_story_5083_50831000_38_dialog_content = "We weren't given a choice when we came into this world, but our people should know what they're fighting and dying for!",
  ui_story_5083_50831000_39_dialog_content = "And it starts with you, me, and every single person who believes in a better future! Once we start down this road, it's only a matter of time before Illumina finds true enlightenment.",
  ui_story_5083_50831000_40_dialog_content = "Only then can we hope to save all of Astra, and once we begin anew... We can chase after even greater dreams.",
  ui_story_5083_50831000_41_dialog_content = "If you want to get rid of Illumina's corruption, you have to be ready for the worst possible outcome: another war.",
  ui_story_5083_50831000_42_dialog_content = "I never had any intention of obeying those indecisive old fools.",
  ui_story_5083_50831000_43_dialog_content = "I'll let my soul ignite if that's what it takes to get rid of their foul deception. As long as it lights the way forward for all of Illumina, I'll have no regrets.",
  ui_story_5083_50831000_44_dialog_content = "It's almost guaranteed that I'll have to face them as a <color=#FFB400>traitor</color>, which means I'll need every ally I can get!",
  ui_story_5083_50831000_45_dialog_content = "That's the spirit, Reinhardt! As long as you never lose sight of that light, my life will always be in your hands!",
  ui_story_5083_50831000_46_dialog_content = "Whether it's me or my soldiers, rest assured that we'll follow any order you give us.",
  ui_story_5083_50831000_47_dialog_content = "It's just...",
  ui_story_5083_50831000_48_dialog_content = "Just what?",
  ui_story_5083_50831000_49_dialog_content = "Heh... Hahahaha! It's just that after getting demoted so much, you have a long climb ahead of you if you want to become Grand Marshal!",
  ui_story_5083_50831000_50_dialog_content = "So you'd better watch out, or else I might beat you to it!",
  ui_story_5083_50831000_51_dialog_content = "I'll be sure to congratulate you with all my heart if you make Grand Marshal first.",
  ui_story_5083_50831000_52_dialog_content = "Though I guess the position itself isn't what's important.",
  ui_story_5083_50831000_53_dialog_content = "Yeah, you're right.",
  ui_story_5083_50831000_54_dialog_content = "There's one other thing—I really don't want to hide any of this from Commander Pango, given that he practically brought me up.",
  ui_story_5083_50831000_55_dialog_content = "We need all the friends we can get right? Besides... The last thing I want is to make an enemy out of him.",
  ui_story_5083_50831000_56_dialog_content = "Don't worry, you can tell him everything that we talked about here.",
  ui_story_5083_50831000_57_dialog_content = "You're trusting me with your life; it's only fair that I do the same for you.",
  ui_story_5083_50831000_58_dialog_content = "I believe in your judgment, as well as the people you trust most.",
  ui_story_5083_50831000_59_dialog_content = "So what are we waiting for? Why not get everyone together and talk things out?",
  ui_story_5083_50831000_60_dialog_content = "I hear the mess hall is offering some tasty new food. Let's call everyone over to the Allocation Area and talk.",
  ui_story_5083_50831000_61_dialog_content = "<size=45>Sounds good to me!</size>",
  ui_story_5083_50831100_1_dialog_content = "I asked my friends to call on a few people who might be sympathetic to our cause. It would help if we could get Denier to join us as well... But let's just head over there for now.",
  ui_story_5083_50831100_2_dialog_content = "Maybe I should head back to camp first? That way, I can get Dogg and the old man to come along too.",
  ui_story_5083_50831100_3_dialog_content = "Don't worry, my friends will pass the message on to Dogg if they see him. As for Commander Pango, he might feel a little uncomfortable in a room full of young and potentially-rebellious soldiers.",
  ui_story_5083_50831100_4_dialog_content = "And after getting on his bad side so many times, I think I should be more prepared before approaching him about this.",
  ui_story_5083_50831100_5_dialog_content = "Ha! So you're scared of the old man too, eh?",
  ui_story_5083_50831100_6_dialog_content = "J-Just keep your voice down and follow me!",
  ui_story_5083_50831100_7_dialog_content = "By the way, is there anything you'd like to eat? Or maybe a hobby or interest?",
  ui_story_5083_50831100_8_dialog_content = "You can hang out until everyone meets up. I'll go grab us a table in the cafeteria.",
  ui_story_5083_50831100_9_dialog_content = "No. Why would I run around if there's no war?",
  ui_story_5083_50831100_10_dialog_content = "Then what do you do on your time off in the base?",
  ui_story_5083_50831100_11_dialog_content = "Stay in the barracks or do my own drills.",
  ui_story_5083_50831100_12_dialog_content = "What? That's pretty lame.",
  ui_story_5083_50831100_13_dialog_content = "No, it's not! We have nothing better to do in the meantime, anyway.",
  ui_story_5083_50831100_14_dialog_content = "Not to mention it's a mess everywhere you go with the war going on.",
  ui_story_5083_50831100_15_dialog_content = "I'd at least hang out with the girls on my leave, but you seem to be a homebody like Gronru.",
  ui_story_5083_50831100_16_dialog_content = "That's not 100% true. I keep up with the latest trends too.",
  ui_story_5083_50831100_17_dialog_content = "I even know where the secret playground is nearby.",
  ui_story_5083_50831100_18_dialog_content = "Alright, you go hang out while I go grab a table and pick up Helios and others on the way.",
  ui_story_5083_50831100_19_dialog_content = "Oh, by the way, Helios is my childhood buddy. He is very nice, and you two will definitely get along.",
  ui_story_5083_50831100_20_dialog_content = "I have no idea where to go, much less hangout...",
  ui_story_5083_50831100_21_dialog_content = "I would have gone back to the base and given Dogg a heads-up if I knew.",
  ui_story_5083_50831100_22_dialog_content = "Beep—Please try to enjoy your leisure time, Barton.",
  ui_story_5083_50831100_23_dialog_content = "I don't even know where I'm going, so I guess Gronru's \"secret playground\" is my only option.",
  ui_story_5083_50831100_24_dialog_content = "Would someone like Gronru be interested in such a thing, though?",
  ui_story_5083_50831100_25_dialog_content = "She's the type who would say, \"Wow, the future of Illumina! So boring. I'm going home to play games.\"",
  ui_story_5083_50831100_26_dialog_content = "What are you doing wandering outside my secret arcade? Looking to fight the Naval King again?",
  ui_story_5083_50831100_27_dialog_content = "That came out of nowhere... Hey, where did my drone go? Did it run off again? How shy can it be?",
  ui_story_5083_50831100_28_dialog_content = "Got a party to invite you to. Didn't Reinhardt tell you? We're meeting up in the cafeteria to discuss some things.",
  ui_story_5083_50831100_29_dialog_content = "Party? I haven't heard about it... Sounds fun and I want to go!",
  ui_story_5083_50831100_30_dialog_content = "Be careful not to get snookered again. You might not get out of it.",
  ui_story_5083_50831100_31_dialog_content = "We're almost there. Anything you'd like to eat?",
  ui_story_5083_50831100_32_dialog_content = "It's obvious you have no clue what's tasty or not, Barton.",
  ui_story_5083_50831100_33_dialog_content = "I ain't got the time to be picky. Illumina would be in big trouble if we soldiers start hating military rations.",
  ui_story_5083_50831100_34_dialog_content = "We strive to improve the food over here, just to please the taste buds on the frontline.",
  ui_story_5083_50831100_35_dialog_content = "Such as the Dehydrated Umbraton Grilled Fish and the chocolate energy bars. You'll know when you try it!",
  ui_story_5083_50831100_36_dialog_content = "It's tasty, but you just went to town on it, Barton. Are you going to have room left for later?",
  ui_story_5083_50831100_37_dialog_content = "*munch* My appetite's bigger than normal. That's a requisite for being a good soldier.",
  ui_story_5083_50831100_38_dialog_content = "I guess if you win next time, I'll send you to sample the new products for me and save myself a trip.",
  ui_story_5083_50831100_39_dialog_content = "Hey, what are you doing there, Barton?",
  ui_story_5083_50831100_40_dialog_content = "I was sent to come get you... What's going on? You're stuffing yourself!",
  ui_story_5083_50831100_41_dialog_content = "Never mind that and try this compressed cherry cookie!",
  ui_story_5083_50831100_42_dialog_content = "What? No, thanks. I think I might get full with just one bite.",
  ui_story_5083_50831100_43_dialog_content = "Oh, come on, try it. It's really good.",
  ui_story_5083_50831100_44_dialog_content = "I'm here on business, so take that away... I can't believe you're not treating it seriously!",
  ui_story_5083_50831100_45_dialog_content = "It's actually not bad.",
  ui_story_5083_50831100_46_dialog_content = "Give me another one.",
  ui_story_5083_50831100_47_dialog_content = "Take it easy or you'll be too stuffed for later! Come, let's go see Reinhardt.",
  ui_story_5083_50831100_48_dialog_content = "What are you guys up to...?",
  ui_story_5083_50831100_49_dialog_content = "Something fun! And you're in it. Don't you try to escape after eating.",
  ui_story_5083_50831100_50_dialog_content = "Here! I found a corner spot. Come quickly!",
  ui_story_5083_50831100_51_dialog_content = "Oh, I learned a lot of new things so we'll be sparring soon.",
  ui_story_5083_50831100_52_dialog_content = "Seriously?",
  ui_story_5083_50831100_53_dialog_content = "Hello, my name is Helios. Thank you for getting Reinhardt home safely.",
  ui_story_5083_50831100_54_dialog_content = "I'm Barton. This here is Dogg. You can cut the formalities. We're Illumina, after all.",
  ui_story_5083_50831100_55_dialog_content = "Not to mention Reinhardt helped me quite a bit, too.",
  ui_story_5083_50831100_56_dialog_content = "We have a problem! Denier is caught in the crowd fighting for food and can't get out. I need two people to come with me!",
  ui_story_5083_50831100_57_dialog_content = "What's with the brouhaha?",
  ui_story_5083_50831100_58_dialog_content = "You weren't kidding about not paying attention to food, I see. The new offerings are a priority for the frontline, so Gannon only gets the excess.",
  ui_story_5083_50831100_59_dialog_content = "They're said to be extremely delicious, so fights aren't uncommon.",
  ui_story_5083_50831100_60_dialog_content = "Then I must help her!",
  ui_story_5083_50831100_61_dialog_content = "Really, Reinhardt, you got everyone together just to fight for food in the cafeteria?",
  ui_story_5083_50831100_62_dialog_content = "It's a big stain on the Legion's honor if we can't even secure a meal! Everyone, follow me into battle! Except for Reinhardt.",
  ui_story_5083_50831100_63_dialog_content = "Ah, young and enthusiastic, I see!",
  ui_story_5083_50831100_64_dialog_content = "So, do we just wait here?",
  ui_story_5083_50831100_65_dialog_content = "I don't think we should get involved.",
  ui_story_5083_50831100_66_dialog_content = "Denier got you your favorite pudding, Gronru!",
  ui_story_5083_50831100_67_dialog_content = "Really? Okay, let me gear up for a raid!",
  ui_story_5083_50831100_68_dialog_content = "Hot, hot... There were so many people, I couldn't even get a tray.",
  ui_story_5083_50831100_69_dialog_content = "Let me help you... Ouch!",
  ui_story_5083_50831100_70_dialog_content = "Told you it's hot.",
  ui_story_5083_50831100_71_dialog_content = "Out of my way! See, Barton, I got double what you got.",
  ui_story_5083_50831100_72_dialog_content = "Where did you get that tray?",
  ui_story_5083_50831100_73_dialog_content = "This is what it means to be the elite of the elite and the commander of commandos.",
  ui_story_5083_50831100_74_dialog_content = "Still couldn't get Denier out of there, but I got enough for us all.",
  ui_story_5083_50831100_75_dialog_content = "Here come the drinks! A must for this occasion!",
  ui_story_5083_50831100_76_dialog_content = "How about a contest?",
  ui_story_5083_50831100_77_dialog_content = "I'm down!",
  ui_story_5083_50831100_78_dialog_content = "Did you forget something, Reinhardt?",
  ui_story_5083_50831100_79_dialog_content = "Oh, Denier, Gronru, and Vaughn are still jostling by the sweets.",
  ui_story_5083_50831100_80_dialog_content = "There's a huge crowd for those, so let's have a round while we wait.",
  ui_story_5083_50831100_81_dialog_content = "I should check on them.",
  ui_story_5083_50831100_82_dialog_content = "Don't be in such a hurry. Reinhardt said we have time for a round.",
  ui_story_5083_50831100_83_dialog_content = "I guess that's fine. We do have the time.",
  ui_story_5083_50831100_84_dialog_content = "Well then, cheers?",
  ui_story_5083_50831100_85_dialog_content = "Cheers!",
  ui_story_5083_50831100_86_dialog_content = "<color=#e8d9bb>The Brightest Generation of Illumina holds their first gathering in a corner with laughter.</color>",
  ui_story_5083_50831100_87_dialog_content = "<color=#e8d9bb>I just cannot move my eyes off the festivity. I want to capture this moment, even if it's fleeting.</color>",
  ui_story_5083_50831100_88_dialog_content = "How about a song? Show off the fight song you wrote, Dogg.",
  ui_story_5083_50831100_89_dialog_content = "Let go of me, you fool, and sing it yourself!",
  ui_story_5083_50831100_90_dialog_content = "They sure are taking their time...",
  ui_story_5083_50831100_91_dialog_content = "Don't worry about your sister. She's old enough not to get lost.",
  ui_story_5083_50831100_92_dialog_content = "Then let's have another toast to our awesome partnership!",
  ui_story_5083_50831100_93_dialog_content = "What awesome partnership are you talking about?",
  ui_story_5083_50831100_94_dialog_content = "No point in turning away, because here it comes!",
  ui_story_5083_50831100_95_dialog_content = "<size=45>Cheers!</size>",
  ui_story_5083_50831200_1_dialog_content = "...",
  ui_story_5083_50831200_2_dialog_content = "To be honest, I didn't think you could snooker us in.",
  ui_story_5083_50831200_3_dialog_content = "You fool, Barton. Do you even realize what you're saying?",
  ui_story_5083_50831200_4_dialog_content = "I think I made myself very clear... And I have faith in Reinhardt!",
  ui_story_5083_50831200_5_dialog_content = "She's gone insane.",
  ui_story_5083_50831200_6_dialog_content = "Calm down, Barton. She's been relegated to the lowest rank.",
  ui_story_5083_50831200_7_dialog_content = "So maybe she's using you, or even us 2nd Legion.",
  ui_story_5083_50831200_8_dialog_content = "I defended Undercity 19 for days with her.",
  ui_story_5083_50831200_9_dialog_content = "She would die for them, so how could she be bad?",
  ui_story_5083_50831200_10_dialog_content = "She would, would she?",
  ui_story_5083_50831200_11_dialog_content = "Perhaps the current Illumina isn't much to write home about, and many of the problems can't be solved easily, but...",
  ui_story_5083_50831200_12_dialog_content = "Fulfilling your objectives means you must stand against the Grand Marshal and your friends.",
  ui_story_5083_50831200_13_dialog_content = "I don't agree, not while we're still fighting the Eclipsites.",
  ui_story_5083_50831200_14_dialog_content = "I will never consent to that!",
  ui_story_5083_50831200_15_dialog_content = "I've fought for Illumina my whole life. I see everyone as my own blood.",
  ui_story_5083_50831200_16_dialog_content = "I will not tolerate any betrayal and will never assist you!",
  ui_story_5083_50831200_17_dialog_content = "I see. I thought you wouldn't see it that way.",
  ui_story_5083_50831200_18_dialog_content = "But I think you can understand where I come from.",
  ui_story_5083_50831200_19_dialog_content = "We're not aiming to be another Lumopolis. We just want to be the pillar that holds up Illumina.",
  ui_story_5083_50831200_20_dialog_content = "Changes only come after that...",
  ui_story_5083_50831200_21_dialog_content = "Enough! I don't want to hear any more!",
  ui_story_5083_50831200_22_dialog_content = "...",
  ui_story_5083_50831200_23_dialog_content = "I trained you and I believe in my judgment.",
  ui_story_5083_50831200_24_dialog_content = "I believe you can trust Reinhardt with your life.",
  ui_story_5083_50831200_25_dialog_content = "But even should the worst happen, I don't want to fight old comrades... and I don't want to have to kill you, Barton.",
  ui_story_5083_50831200_26_dialog_content = "I didn't train you to fight Illumina, or any Aurorian, for that matter.",
  ui_story_5083_50831200_27_dialog_content = "That's not what we want, either! We only believe in justice and striding for the future...",
  ui_story_5083_50831200_28_dialog_content = "Keep talking and I'll lock you in a cell myself.",
  ui_story_5083_50831200_29_dialog_content = "Take it easy, Barton. You're not sure what to do just yet.",
  ui_story_5083_50831200_30_dialog_content = "Take your time and think it over.",
  ui_story_5083_50831200_31_dialog_content = "Take your time and think it over? You actually mean keep taking this nonsense, right?",
  ui_story_5083_50831200_32_dialog_content = "I've been promoted to lieutenant colonel and am a battalion commander. I didn't think I still have to train rookies.",
  ui_story_5083_50831200_33_dialog_content = "Any drill sergeant could do that. Where I should be is on the frontline!",
  ui_story_5083_50831200_34_dialog_content = "And the photoshoots for the Committee... I ain't no supermodel.",
  ui_story_5083_50831200_35_dialog_content = "Why can't they pay attention to the real heroes out in front? I'm wasting my time talking about how safe it is back here!",
  ui_story_5083_50831200_36_dialog_content = "It's still too early for you.",
  ui_story_5083_50831200_37_dialog_content = "What do you mean?",
  ui_story_5083_50831200_38_dialog_content = "Only when allies help you in the future can you become...",
  ui_story_5083_50831200_39_dialog_content = "Beep—At least Barton hasn't been punished.",
  ui_story_5083_50831200_40_dialog_content = "Oh, how did that slip my mind.",
  ui_story_5083_50831200_41_dialog_content = "I should talk to my buddies rather than babbling by myself.",
  ui_story_5083_50831200_42_dialog_content = "Too bad Dogg didn't see eye to eye with me.",
  ui_story_5083_50831200_43_dialog_content = "Never mind, I got to see Reinhardt. Do you know where she is?",
  ui_story_5083_50831200_44_dialog_content = "Beep—Follow me, Barton.",
  ui_story_5083_50831200_45_dialog_content = "This is Gronru's shop... But she's tight with those two so she should know where Reinhardt is.",
  ui_story_5083_50831200_46_dialog_content = "Who are you talking to? She is not in. I'm in charge while she's away, so tell me your business.",
  ui_story_5083_50831200_47_dialog_content = "Say, aren't you supposed to be on base, Propaganda for Illumina?",
  ui_story_5083_50831200_48_dialog_content = "I sneaked out.",
  ui_story_5083_50831200_49_dialog_content = "But never mind that. Where's Reinhardt? Where did she go?",
  ui_story_5083_50831200_50_dialog_content = "Doing her special drills and dreaming about being the Grand Marshal.",
  ui_story_5083_50831200_51_dialog_content = "Aren't you on good terms? How come you're so disapproving of her?",
  ui_story_5083_50831200_52_dialog_content = "Who knows?",
  ui_story_5083_50831200_53_dialog_content = "Maybe my big sis can't relate to me anymore...",
  ui_story_5083_50831200_54_dialog_content = "Even though you beat me in a simulation, I got advice for you.",
  ui_story_5083_50831200_55_dialog_content = "You can never be Reinhardt. You are not the same.",
  ui_story_5083_50831200_56_dialog_content = "Anything you're not comfortable with, you should make it clear to your dear sister.",
  ui_story_5083_50831200_57_dialog_content = "She's always looked out for you... Don't hold stuff in or no one will know.",
  ui_story_5083_50831200_58_dialog_content = "So what do you want with her?",
  ui_story_5083_50831200_59_dialog_content = "Don't worry about it. I can't talk to her if she's not around. Just let her know I dropped by.",
  ui_story_5083_50831200_60_dialog_content = "Sure.",
  ui_story_5083_50831200_61_dialog_content = "<color=#e8d9bb>Denier's words put Barton at ease. He returned to the base and resumed his tasks for the Committee following disciplinary action.</color>",
  ui_story_5083_50831200_62_dialog_content = "<color=#e8d9bb>But he never got a reply...</color>",
  ui_story_5083_50831200_63_dialog_content = "<color=#e8d9bb>Gannon City announced a serious lab explosion with Reinhardt, her team, and Gronru missing in action.</color>",
  ui_story_5083_50831301_1_dialog_content = "<color=#e8d9bb>It's spring again, but the Darkover Crisis continues. No one knows where the Eclipsites come from and why they keep growing in numbers.</color>",
  ui_story_5083_50831301_2_dialog_content = "<color=#e8d9bb>They still run rampant on Astra and slaughter lives, which is enough to make everyone fight to the end.</color>",
  ui_story_5083_50831301_3_dialog_content = "<color=#e8d9bb>In the escalating war, an urgent message reaches Gannon, indicating Eclipsite sightings near the city's defense.</color>",
  ui_story_5083_50831301_4_dialog_content = "What's going on? Undercity 13 has self-destructed, and we've sealed all surface access from there.",
  ui_story_5083_50831301_5_dialog_content = "Undercity 19 is still operational. No request for assistance, so they probably held the pass.",
  ui_story_5083_50831301_6_dialog_content = "All undercities along the line remain operational. No breach was reported.",
  ui_story_5083_50831301_7_dialog_content = "Perhaps it's just loose Eclipsites coming over the mountains or popping up from underground ruins like before.",
  ui_story_5083_50831301_8_dialog_content = "Yes, but make sure they are all exterminated with extreme prejudice, nevertheless.",
  ui_story_5083_50831301_9_dialog_content = "Send one more team to track down the source.",
  ui_story_5083_50831301_10_dialog_content = "The war is intense right now. The 1st Legion in perimeter defense probably has no soldier to spare.",
  ui_story_5083_50831301_11_dialog_content = "Eclipsites don't just show up out of thin air. Complacency will only kill us!",
  ui_story_5083_50831301_12_dialog_content = "If the Legion can't spare anyone, we'll handle it ourselves.",
  ui_story_5083_50831301_13_dialog_content = "I still have two whole battalions under me. This will be their opportunity to flex their muscles.",
  ui_story_5083_50831301_14_dialog_content = "You're right. We can't afford to lose anything in the war.",
  ui_story_5083_50831301_15_dialog_content = "Sorry, but it seems you've forgotten I'm here. Commander Barton and his men must follow the committee's assignments. That's a priority.",
  ui_story_5083_50831301_16_dialog_content = "I'm making a request to the Grand Marshal. It has nothing to do with you.",
  ui_story_5083_50831301_17_dialog_content = "Pardon me, but it's my job to deliver the message and report everything back to the Committee—including your meetings.",
  ui_story_5083_50831301_18_dialog_content = "Listen you, we're the ones defending Gannon here, so cool your jet!",
  ui_story_5083_50831301_19_dialog_content = "Since Barton and Dogg still have to do propaganda for the Committee, perhaps they shouldn't leave the city.",
  ui_story_5083_50831301_20_dialog_content = "Maybe you can take this one, Pango, with your team and one of the battalions.",
  ui_story_5083_50831301_21_dialog_content = "Sure, but it makes no sense that my second-in-charge died in combat while these two perfectly good, young soldiers are here doing busywork!",
  ui_story_5083_50831301_22_dialog_content = "I already lectured you about consequences, Pango.",
  ui_story_5083_50831301_23_dialog_content = "Bring Dogg with you. I approved his enlistment request myself, so I'll take full responsibility.",
  ui_story_5083_50831301_24_dialog_content = "It's my order and you can quote me, Secretary of the Committee.",
  ui_story_5083_50831301_25_dialog_content = "It is what it is. I just can't stand not finding out where the Eclipsites come from.",
  ui_story_5083_50831301_26_dialog_content = "Stay back and drill the soldiers this time, Barton.",
  ui_story_5083_50831301_27_dialog_content = "No way, I have a bad feeling about this.",
  ui_story_5083_50831301_28_dialog_content = "As the Twin Shields, the two undercities fulfilled their purpose, so why are Eclipsites showing up around Gannon now?",
  ui_story_5083_50831301_29_dialog_content = "That was common before, and they are closer now only because the 1st Legion is stretched too thin due to the intense campaign.",
  ui_story_5083_50831301_30_dialog_content = "Are you sure it's not a problem?",
  ui_story_5083_50831301_31_dialog_content = "They haven't let me out of Gannon or go on any operation for a long time now, yet you get sent into the fierce battle.",
  ui_story_5083_50831301_32_dialog_content = "I'm even starting to second-guess the Grand Marshal...",
  ui_story_5083_50831301_33_dialog_content = "Shut up! Has your brain stopped working from being cooped up, and have you even forgotten our tenet?",
  ui_story_5083_50831301_34_dialog_content = "Your eyes are full of anger and defiance! Have they snuffed out every last thread of honor in you?!",
  ui_story_5083_50831301_35_dialog_content = "Get over here, you punk!",
  ui_story_5083_50831301_36_dialog_content = "Look at that light over! The Central Tower has never dimmed. You grew up under that light, so you watch over it with your life!",
  ui_story_5083_50831301_37_dialog_content = "I don't care what issues you have with the higher-ups, but remember this—you're always Illumina.",
  ui_story_5083_50831301_38_dialog_content = "I was just worried about you...",
  ui_story_5083_50831301_39_dialog_content = "Then dedicate yourself to the cause and don't project your person issues onto Illumina.",
  ui_story_5083_50831301_40_dialog_content = "The Grand Marshal may appear to be frazzled or even weak, but he's not the type to sell allies out.",
  ui_story_5083_50831301_41_dialog_content = "I will not tolerate another insult to our soldiers from you again!",
  ui_story_5083_50831301_42_dialog_content = "But at least bring me along! I just can't let go, so let me...",
  ui_story_5083_50831301_43_dialog_content = "Forget it, Barton. I'm sure that's already been tried.",
  ui_story_5083_50831301_44_dialog_content = "Don't worry, I got your back. If a fight does happen, I'll call for backup right away and ask for you by name.",
  ui_story_5083_50831301_45_dialog_content = "That way, you can't be held back anymore.",
  ui_story_5083_50831301_46_dialog_content = "...",
  ui_story_5083_50831301_47_dialog_content = "I'm just as good, so no reason not to trust me, right?",
  ui_story_5083_50831301_48_dialog_content = "Just you wait, Barton. I'll never be a second fiddle. You better change your arrogant ways.",
  ui_story_5083_50831301_49_dialog_content = "Curses! It's really bugging me, like something terrible is about to happen.",
  ui_story_5083_50831301_50_dialog_content = "Why am I getting so restless...",
  ui_story_5083_50831301_51_dialog_content = "Beep—You got a new message, Barton.",
  ui_story_5083_50831301_52_dialog_content = "Unknown Sender: \"Reinhardt was knocked unconscious trying to save people in the lab accident.\"",
  ui_story_5083_50831301_53_dialog_content = "...?",
  ui_story_5083_50831301_54_dialog_content = "\"Sorry, I got overconfident... didn't suspect flaws in the data... □□... Danger... \"",
  ui_story_5083_50831301_55_dialog_content = "\"I'll take responsibility for this... while recuperating... □□... Worry not, Denier is with Reinhardt...\"",
  ui_story_5083_50831301_56_dialog_content = "Error: Eavesdropping detected. Signal interrupted.",
  ui_story_5083_50831301_57_dialog_content = "That sounded like Gronru. But why, and what happened?",
  ui_story_5083_50831301_58_dialog_content = "The message has too many encryptions to trace the origin.",
  ui_story_5083_50831301_59_dialog_content = "This is bad. It's getting more and more tangled for me.",
  ui_story_5083_50831301_60_dialog_content = "Why was Reinhardt involved? What happened to Gronru? And why was the message monitored?",
  ui_story_5083_50831301_61_dialog_content = "What happened without me knowing? Damn it, this is killing me...",
  ui_story_5083_50831301_62_dialog_content = "Beep—Immediate rest and de-stress are recommended, Barton.",
  ui_story_5083_50831301_63_dialog_content = "No, I can't take any breaks now!",
  ui_story_5083_50831301_64_dialog_content = "I can't just stand by and do nothing.",
  ui_story_5083_50831301_65_dialog_content = "Barton...",
  ui_story_5083_50831301_66_dialog_content = "I must go and catch up to Dogg and the others.",
  ui_story_5083_50831301_67_dialog_content = "But you didn't receive any order, Barton.",
  ui_story_5083_50831301_68_dialog_content = "I don't care!",
  ui_story_5083_50831301_69_dialog_content = "Even making mistakes is better than doing nothing at all!",
  ui_story_5083_50831301_70_dialog_content = "It's all because of that light, old man! It's because of it that we must keep pushing ahead!",
  ui_story_5083_50831301_71_dialog_content = "I don't care what's going to happen anymore! I can't let anything bad happen to any of them!",
  ui_story_5083_50831301_72_dialog_content = "2nd Legion, assemble!",
  ui_story_5083_50831301_73_dialog_content = "We found traces of battle, Commander Barton. The Commander likely fought Eclipsites here before the legion went missing.",
  ui_story_5083_50831301_74_dialog_content = "Given the scale of the battle, it's probably not loose Eclipsites. I believe the Commander fell back.",
  ui_story_5083_50831301_75_dialog_content = "Quick, follow the tracks, scout the terrains, and make way for the convoy!",
  ui_story_5083_50831301_76_dialog_content = "It's not too late. I'm sure we'll make it...",
  ui_story_5083_50831302_1_dialog_content = "How is it?",
  ui_story_5083_50831302_2_dialog_content = "Communication is still blocked. This is weird because Eclipsites don't have the technology.",
  ui_story_5083_50831302_3_dialog_content = "I believe we're surrounded.",
  ui_story_5083_50831302_4_dialog_content = "What's our status?",
  ui_story_5083_50831302_5_dialog_content = "Only twenty out of the two hundred covering the rear survived. We also lost one-third of our commandos.",
  ui_story_5083_50831302_6_dialog_content = "The Eclipsites outnumbered us by more than we expected. We've lost control of the situation.",
  ui_story_5083_50831302_7_dialog_content = "Maybe an undercity along the line of defense has been breached for this to happen.",
  ui_story_5083_50831302_8_dialog_content = "Or there could be a traitor. Regardless, I'll lead a team to break the siege and allow you to leave.",
  ui_story_5083_50831302_9_dialog_content = "You must take the news back to Gannon to avoid greater losses.",
  ui_story_5083_50831302_10_dialog_content = "No, many installations have not been properly recovered and the 1st Legion Outpost is still intact. I can't just leave.",
  ui_story_5083_50831302_11_dialog_content = "But...",
  ui_story_5083_50831302_12_dialog_content = "<color=#e8d9bb>BOOM!</color>",
  ui_story_5083_50831302_13_dialog_content = "What's going on? Are we under Eclipsite attack?",
  ui_story_5083_50831302_14_dialog_content = "Are you okay? Where's Commander Pango?",
  ui_story_5083_50831302_15_dialog_content = "What are you doing here, you brat?",
  ui_story_5083_50831302_16_dialog_content = "Glad to see you're okay, but I don't think this is the time to ask me that!",
  ui_story_5083_50831302_17_dialog_content = "You're just in time. Did you see any Eclipsite?",
  ui_story_5083_50831302_18_dialog_content = "My mech team has breached their line. I met scouts from the 1st Legion on the way and let them know already.",
  ui_story_5083_50831302_19_dialog_content = "We have installations we need to recover. How many transports can you spare, Barton? We have to do this ASAP!",
  ui_story_5083_50831302_20_dialog_content = "That won't be a problem. But what's going on here? I can't get any signals.",
  ui_story_5083_50831302_21_dialog_content = "We tried sending SOS flares already.",
  ui_story_5083_50831302_22_dialog_content = "Only the watchtower could see the flares, and I'm not sure they have the signal to relay it to Gannon.",
  ui_story_5083_50831302_23_dialog_content = "It's all right. If you let the scouts know already, help should be here soon.",
  ui_story_5083_50831302_24_dialog_content = "Bad new, the Eclipsites are trying to overcome our barrage with sheer numbers!",
  ui_story_5083_50831302_25_dialog_content = "We also spotted a <color=#FFB400>gargantuan Eclipsite</color> closing in that must be deterred!",
  ui_story_5083_50831302_26_dialog_content = "<color=#FFB400>Gargantuan Eclipse</color>? The legendary <color=#FFB400>Siege Eclipsite</color>?",
  ui_story_5083_50831302_27_dialog_content = "It would be hard to kill that bastard without some serious firepower...",
  ui_story_5083_50831302_28_dialog_content = "Split the tank division in two, one to cover our retreat and one to defend the front!",
  ui_story_5083_50831302_29_dialog_content = "Get ten carriers with four commandos each to recover the surface installations around Gannon.",
  ui_story_5083_50831302_30_dialog_content = "Copy!",
  ui_story_5083_50831302_31_dialog_content = "<color=#e8d9bb>The bombardment signals the inception of war. Yet, the echoes of an unusual ringing drown out all noises.</color>",
  ui_story_5083_50831302_32_dialog_content = "Come ride with me, Dogg! Let's go get rid of that super-sized Eclipsite!",
  ui_story_5083_50831302_33_dialog_content = "My unit still got the turrets salvaged from Undercity 19, and those suckers deal massive damage!",
  ui_story_5083_50831302_34_dialog_content = "No!",
  ui_story_5083_50831302_35_dialog_content = "You two go and leave me and my team behind.",
  ui_story_5083_50831302_36_dialog_content = "This is a planned assault but we're not the target... Gannon is.",
  ui_story_5083_50831302_37_dialog_content = "It's not an operation just you two morons can handle.",
  ui_story_5083_50831302_38_dialog_content = "Leave now and notify Gannon! The sooner, the better!",
  ui_story_5083_50831302_39_dialog_content = "What are you saying? We can't abandon you in a time like this!",
  ui_story_5083_50831302_40_dialog_content = "They outnumbered us, but that's more of a reason to stick together.",
  ui_story_5083_50831302_41_dialog_content = "You hear the <color=#FFB400>ringing</color>? That's the Dark Zone Abomination that obliterated Undercity 13.",
  ui_story_5083_50831302_42_dialog_content = "In the Battle of Dark Zone, that bell heralded our defeat.",
  ui_story_5083_50831302_43_dialog_content = "If you don't go now, none of us will make it out alive!",
  ui_story_5083_50831302_44_dialog_content = "But...",
  ui_story_5083_50831302_45_dialog_content = "Now!",
  ui_story_5083_50831302_46_dialog_content = "I can't leave you behind, because you're more than a superior to me... At least let me stay with you.",
  ui_story_5083_50831302_47_dialog_content = "I understand.",
  ui_story_5083_50831302_48_dialog_content = "But no child should pass before their parents.",
  ui_story_5083_50831302_49_dialog_content = "I already lost a child, Dogg. I can't afford to lose you too.",
  ui_story_5083_50831302_50_dialog_content = "Oh...!",
  ui_story_5083_50831302_51_dialog_content = "You old man...",
  ui_story_5083_50831302_52_dialog_content = "I... get it.",
  ui_story_5083_50831302_53_dialog_content = "Get out of here if you get it. Out of my sight so you're out of my mind!",
  ui_story_5083_50831302_54_dialog_content = "I got a battle to fight!",
  ui_story_5083_50831302_55_dialog_content = "What are you doing, Dogg?!",
  ui_story_5083_50831302_56_dialog_content = "Take Commander Pango... uh, Pops. The commandos will carve out a path for you.",
  ui_story_5083_50831302_57_dialog_content = "This is not the time for you to play hero!",
  ui_story_5083_50831302_58_dialog_content = "I've always envied you, Barton...",
  ui_story_5083_50831302_59_dialog_content = "As an elite like you, I'm always a step behind, always the second fiddle.",
  ui_story_5083_50831302_60_dialog_content = "This isn't the time for that, fool!",
  ui_story_5083_50831302_61_dialog_content = "Let me finish. I'm always jealous that you're better than me, can go farther than me, and are better treated than me...",
  ui_story_5083_50831302_62_dialog_content = "You always surged forward, with everybody following you willingly...",
  ui_story_5083_50831302_63_dialog_content = "In you, I see the power to conquer the darkness befitting of an elite.",
  ui_story_5083_50831302_64_dialog_content = "You're more decisive than me, so I'll always be a second to you.",
  ui_story_5083_50831302_65_dialog_content = "I'm happy to know, though, that I worked hard enough to be just a notch below you.",
  ui_story_5083_50831302_66_dialog_content = "So I want to hold off on the Eclipsites just like you so you can make it home.",
  ui_story_5083_50831302_67_dialog_content = "<color=#e8d9bb>The ringings are getting close as the blasters become ever quieter. The line of defense recedes to make way for a retreat.</color>",
  ui_story_5083_50831302_68_dialog_content = "This just means more people will be sacrificed! I have to stay and help!",
  ui_story_5083_50831302_69_dialog_content = "Everybody dies sometimes. Aren't we all prepared for that the first time we picked up a gun?",
  ui_story_5083_50831302_70_dialog_content = "But for the future of the legion and Illumina, this is not the place for that, for someone like you.",
  ui_story_5083_50831302_71_dialog_content = "Let me give you the best assistance you'll ever have. Do you thing after I make an opening.",
  ui_story_5083_50831302_72_dialog_content = "The future of Illumina depends on you.",
  ui_story_5083_50831302_73_dialog_content = "Stop that nonsense. We still have tanks...",
  ui_story_5083_50831302_74_dialog_content = "Remember the story I told you? Pango sacrificed his wife and child for me.",
  ui_story_5083_50831302_75_dialog_content = "I've been thinking who am I to deserve such an honor.",
  ui_story_5083_50831302_76_dialog_content = "I've been living with guilt. Many times, I was dead in my mind.",
  ui_story_5083_50831302_77_dialog_content = "You idiot! If you didn't survive, then who would've been there to push me and make me go the extra mile?",
  ui_story_5083_50831302_78_dialog_content = "Yeah, I could feel it when you talked to me about the dream. It moved me to the core.",
  ui_story_5083_50831302_79_dialog_content = "Even though I wanted to retort out of instinct, I didn't because I knew I was willing to die for that cause.",
  ui_story_5083_50831302_80_dialog_content = "Please give us the opportunity, Barton. We're not dying for nothing but the glory and hopes of a greater Illumina.",
  ui_story_5083_50831302_81_dialog_content = "The tank unit has successfully breached the opposition!",
  ui_story_5083_50831302_82_dialog_content = "But the gargantuan Eclipsite is making it impossible for us to withdraw safely!",
  ui_story_5083_50831302_83_dialog_content = "Relay my order for all commandos to stay behind and cover for our fellow soldiers!",
  ui_story_5083_50831302_84_dialog_content = "Inform the mechanized units to give them as much ammo as possible, then we take the rest and fall back to Gannon!",
  ui_story_5083_50831302_85_dialog_content = "Barton, you're my brother, my enemy, my nightmare, the reason for me being a second fiddle.",
  ui_story_5083_50831302_86_dialog_content = "And I'm the reason why you're the best!",
  ui_story_5083_50831302_87_dialog_content = "Take this and go.",
  ui_story_5083_50831302_88_dialog_content = "You stay alive until I bring reinforcements!",
  ui_story_5083_50831302_89_dialog_content = "Outta my way, puny Illumina insects!",
  ui_story_5083_50831302_90_dialog_content = "Fellows, this is what commandos are made for! Let us fight for each other! <size=45>Charge!</size>",
  ui_story_5083_50831302_91_dialog_content = "<color=#e8d9bb>Dogg bellowed the fight song at the top of his lungs and strides forward. All commandos followed and charged the horde.</color>",
  ui_story_5083_50831302_92_dialog_content = "<size=45>Go to hell.</size>",
  ui_story_5083_50831302_93_dialog_content = "Fly hard and strong, do not stop until the dream becomes real!",
  ui_story_5083_50831302_94_dialog_content = "Go, Barton... Push ever forward toward a bright future...",
  ui_story_5083_50831400_1_dialog_content = "<color=#e8d9bb>The 1st Legion scouts brought back news that all commandos were killed in action. They turned back the Darkover army at the expense of their lives.</color>",
  ui_story_5083_50831400_2_dialog_content = "<color=#e8d9bb>Alarms blared throughout Gannon when full mobilization was declared. It was all hands on deck against the impending Eclipsites.</color>",
  ui_story_5083_50831400_3_dialog_content = "It's too late to make amends. An entire battalion sacrificed for nothing!",
  ui_story_5083_50831400_4_dialog_content = "This is a classified meeting, Colonel Barton. Please proceed no further.",
  ui_story_5083_50831400_5_dialog_content = "The Grand Marshall is still formulating a plan. Stop interfering or else.",
  ui_story_5083_50831400_6_dialog_content = "Shoot, I dare you.",
  ui_story_5083_50831400_7_dialog_content = "Please step back, Colonel Barton!",
  ui_story_5083_50831400_8_dialog_content = "If you ain't got the guts to pull the trigger, don't point that thing at me.",
  ui_story_5083_50831400_9_dialog_content = "Why are you yelling about this time, brat?!",
  ui_story_5083_50831400_10_dialog_content = "Come back here before you embarrass yourself in front of the Grand Marshal!",
  ui_story_5083_50831400_11_dialog_content = "You're conscious, sir...",
  ui_story_5083_50831400_12_dialog_content = "Salutations, Grand Marshal!",
  ui_story_5083_50831400_13_dialog_content = "...",
  ui_story_5083_50831400_14_dialog_content = "Hey, stop holding me back! I want answers from him!",
  ui_story_5083_50831400_15_dialog_content = "Why did you refuse to even send just two battalions? Why didn't you deploy the mechanized unit in the first place?",
  ui_story_5083_50831400_16_dialog_content = "They wouldn't be trapped if they had transportation...",
  ui_story_5083_50831400_17_dialog_content = "Calm down!",
  ui_story_5083_50831400_18_dialog_content = "Dogg and everyone else, they are dead. How can I be calm!",
  ui_story_5083_50831400_19_dialog_content = "You trusted the wrong people! Those guys have no strategies but subterfuge to speak of, that's why Dogg and others died in vain!",
  ui_story_5083_50831400_20_dialog_content = "They're targeting us... but why won't they just come at me?",
  ui_story_5083_50831400_21_dialog_content = "Damn it, why won't they come at me!",
  ui_story_5083_50831400_22_dialog_content = "Stop it before you embarrass the 2nd Legion too. How would Dogg feel about this?",
  ui_story_5083_50831400_23_dialog_content = "This is the second time you left Gannon with the mechanized unit! You're lucky the Grand Marshal hasn't come down on you!",
  ui_story_5083_50831400_24_dialog_content = "He's responsible for Dogg's death!",
  ui_story_5083_50831400_25_dialog_content = "It's obvious he's the culprit...",
  ui_story_5083_50831400_26_dialog_content = "Dogg is the Grand Marshal's only son.",
  ui_story_5083_50831400_27_dialog_content = "Quit selling me lies, old man!",
  ui_story_5083_50831400_28_dialog_content = "Follow me.",
  ui_story_5083_50831400_29_dialog_content = "Roog and I are old war buddies. Just before he was appointed the Grand Marshal, his pregnant wife was trapped in an undercity.",
  ui_story_5083_50831400_30_dialog_content = "I led a rescue army but it was too late. The undercity fell. On the record, there were no survivors.",
  ui_story_5083_50831400_31_dialog_content = "But when I found his wife's body, I noticed Dogg lying in his mother's arms. He was quiet and never cried.",
  ui_story_5083_50831400_32_dialog_content = "I have no idea how she gave birth to a child in such an adverse environment and helped him survive... It's a miracle.",
  ui_story_5083_50831400_33_dialog_content = "I still remember how sad Roog was when I brought Dogg back. He loved his wife dearly, but had to observe his duty as a soldier.",
  ui_story_5083_50831400_34_dialog_content = "No one knew about that child, so he entrusted the kid to me. There was something on his mind at the time and he wanted to focus on the war.",
  ui_story_5083_50831400_35_dialog_content = "Impossible...",
  ui_story_5083_50831400_36_dialog_content = "That's the fact. The undercity I was defending was invaded six years ago. The Committee uncovered Dogg's true story when they went through the usual procedure.",
  ui_story_5083_50831400_37_dialog_content = "I don't if that had anything to do with it, but Roog became indecisive and grew distant from me after that.",
  ui_story_5083_50831400_38_dialog_content = "As a Grand Marshal, even though he grew stronger and stronger, he acted more and more conservatively.",
  ui_story_5083_50831400_39_dialog_content = "I don't understand it, but I'll bet my life on him having the best interest of Illumina in heart.",
  ui_story_5083_50831400_40_dialog_content = "Even if his aim may be a little off, he would never hurt his own child.",
  ui_story_5083_50831400_41_dialog_content = "Did you tell that fool who his father is?",
  ui_story_5083_50831400_42_dialog_content = "Of course.",
  ui_story_5083_50831400_43_dialog_content = "He sacrificed his wife to evacuate me and the other noncombatants.",
  ui_story_5083_50831400_44_dialog_content = "I've been thinking, who am I to deserve such an honor.",
  ui_story_5083_50831400_45_dialog_content = "That fool has been carrying the guilt of who he really is with him all these years...",
  ui_story_5083_50831400_46_dialog_content = "So I regret telling him very much.",
  ui_story_5083_50831400_47_dialog_content = "...",
  ui_story_5083_50831400_48_dialog_content = "Quick, take as much as you can and fill up all the sandbags... Halt, you there. This is the 1st Legion squad heading to the front!",
  ui_story_5083_50831400_49_dialog_content = "Reinhardt?",
  ui_story_5083_50831400_50_dialog_content = "You're discharged from the hospital, I see.",
  ui_story_5083_50831400_51_dialog_content = "That was a long time ago. What are you doing hanging around here when Illumina's facing a crisis?",
  ui_story_5083_50831400_52_dialog_content = "The vehicles are loaded, Colonel Reinhardt. We'll be leaving now.",
  ui_story_5083_50831400_53_dialog_content = "Have a safe trip!",
  ui_story_5083_50831400_54_dialog_content = "Hmm, not enough people. This can only spell trouble for the commander...",
  ui_story_5083_50831400_55_dialog_content = "You feel a bit different to me...",
  ui_story_5083_50831400_56_dialog_content = "I do? I'm busy with mobilization, so I don't have time for chitchat.",
  ui_story_5083_50831400_57_dialog_content = "Hey, wait a minute, Reinhardt...",
  ui_story_5083_50831400_58_dialog_content = "You still remember what we talked about before?",
  ui_story_5083_50831400_59_dialog_content = "What did the Committee do to you?",
  ui_story_5083_50831400_60_dialog_content = "You mean promoting me to colonel?",
  ui_story_5083_50831400_61_dialog_content = "No! Why do you...",
  ui_story_5083_50831400_62_dialog_content = "I know what you want to say. As for the Committee, I have to bear it for now. The war is the real concern.",
  ui_story_5083_50831400_63_dialog_content = "I have to report to the commander. You're probably a little confused, but I hope you perk up. You're a hero of Illumina, after all.",
  ui_story_5083_50831400_64_dialog_content = "Heh, \"Hero of Illumina\"? What title should Dogg and the others who won't make it back be called, then?",
  ui_story_5083_50831400_65_dialog_content = "The Committee has no right to deem who's the hero and who's not!",
  ui_story_5083_50831400_66_dialog_content = "Reinhardt...",
  ui_story_5083_50831400_67_dialog_content = "Beep—Please follow me, Barton.",
  ui_story_5083_50831400_68_dialog_content = "Well, at least you haven't changed a bit, my... navigator.",
  ui_story_5083_50831400_69_dialog_content = "Let's go. Wherever you're taking me can't be worse than this.",
  ui_story_5083_50831400_70_dialog_content = "The monument... Has Dogg's name been added?",
  ui_story_5083_50831400_71_dialog_content = "Beep—Look, Barton.",
  ui_story_5083_50831400_72_dialog_content = "<color=#e8d9bb>Under the towering memorial, a haunched figure stared at the names without any expression.</color>",
  ui_story_5083_50831400_73_dialog_content = "That's the Grand Marshal.",
  ui_story_5083_50831400_74_dialog_content = "Dogg's real <color=#FFB400>father</color>...",
  ui_story_5083_50831400_75_dialog_content = "<color=#e8d9bb>Barton paused. He wanted to go forward but changed his mind and remained where he stood.</color>",
  ui_story_5083_50831400_76_dialog_content = "Dogg...",
  ui_story_5083_50831400_77_dialog_content = "<color=#e8d9bb>The haggard man in the distance shed a silent tear. He wasn't a Grand Marshal but a heartbroken father.</color>",
  ui_story_5083_50831400_78_dialog_content = "<color=#e8d9bb>He finally left in heavy footsteps to yield the way to Barton.</color>",
  ui_story_5083_50831400_79_dialog_content = "Every soldier's name has been added. This is the final resting place for all children of Illumina.",
  ui_story_5083_50831400_80_dialog_content = "Beep—Barton...",
  ui_story_5083_50831400_81_dialog_content = "Who can I trust other than you now? Everyone has a secret, with endless layers too...",
  ui_story_5083_50831400_82_dialog_content = "Even if the Grand Marshal and others are innocent, how can I trust them...?",
  ui_story_5083_50831400_83_dialog_content = "Take a look, Barton.",
  ui_story_5083_50831400_84_dialog_content = "Is this a picture of all of us together?",
  ui_story_5083_50831400_85_dialog_content = "Did you take this photo for us? Thank you.",
  ui_story_5083_50831400_86_dialog_content = "Dogg is gone, Reinhardt is not the same, and who knows where the rest went.",
  ui_story_5083_50831400_87_dialog_content = "Everybody in this picture has scattered...",
  ui_story_5083_50831400_88_dialog_content = "But I have to carry the load and push forward, right?",
  ui_story_5083_50831400_89_dialog_content = "Even it's just me left, I'll still take the helm.",
  ui_story_5083_50831500_1_dialog_content = "<color=#e8d9bb>As the battle for Gannon intensified, the Committee finally relented for Barton to take a resupplied army back to the frontline.</color>",
  ui_story_5083_50831500_2_dialog_content = "<color=#e8d9bb>However, the situation didn't get better with the Darkover threatening Gannon borders. To avoid a siege, the Grand Marshal ordered an evacuation.</color>",
  ui_story_5083_50831500_3_dialog_content = "Commander Barton, the Darkover has retreated. What is your order?",
  ui_story_5083_50831500_4_dialog_content = "Push the line of defense but take it slow. No, strike that. No risky moves. We're in a better position for logistical transports right now.",
  ui_story_5083_50831500_5_dialog_content = "The tank units are requesting a counterstrike, Commander Barton.",
  ui_story_5083_50831500_6_dialog_content = "Absolutely not! Stop thinking about killing the enemy when we're fighting a defensive battle! We just need to turn them away.",
  ui_story_5083_50831500_7_dialog_content = "But the 1st Legion is still engaged in a bitter fight... Shouldn't we help?",
  ui_story_5083_50831500_8_dialog_content = "Nothing we can do about that. We can take any risk. I can't let you go out blind...",
  ui_story_5083_50831500_9_dialog_content = "What are you doing stuck here like a turtle? There's a lot of Eclipsites out there for you to chase down!",
  ui_story_5083_50831500_10_dialog_content = "But someone will die...",
  ui_story_5083_50831500_11_dialog_content = "How can you fight a war without anyone dying? What's important is what you are fighting for!",
  ui_story_5083_50831500_12_dialog_content = "Didn't you use to know better, brat? Don't go soft on me now!",
  ui_story_5083_50831500_13_dialog_content = "I don't see the light anymore...",
  ui_story_5083_50831500_14_dialog_content = "?!",
  ui_story_5083_50831500_15_dialog_content = "With the ever-growing Central Tower ahead, I've been charging forward for Illumina.",
  ui_story_5083_50831500_16_dialog_content = "I grew up chasing it, trying to reach it... But I don't see it now.",
  ui_story_5083_50831500_17_dialog_content = "I can't find a reason why my soldiers should fight for me. I don't want them to die because of my orders.",
  ui_story_5083_50831500_18_dialog_content = "I know I should be leading them, but I can't even find my own footing now...",
  ui_story_5083_50831500_19_dialog_content = "When did you get so wishy-washy too, brat?",
  ui_story_5083_50831500_20_dialog_content = "You make decisions and give orders based on the report you got to complete objectives. Isn't that enough?",
  ui_story_5083_50831500_21_dialog_content = "Illumina soldiers aren't dumb. They know what they're fighting for!",
  ui_story_5083_50831500_22_dialog_content = "Even if they can't explain it well, just ask, and every one of them will tell you the cause for which they would die!",
  ui_story_5083_50831500_23_dialog_content = "Out of the headquarters now and into the trenches! You'll see the direction their resolve is telling you to go!",
  ui_story_5083_50831500_24_dialog_content = "Every one of our Illumina soldiers grew up under the light. How could you forget about that?",
  ui_story_5083_50831500_25_dialog_content = "They grew up under the light...",
  ui_story_5083_50831500_26_dialog_content = "Come up with a better plan if you think the casualty is going to be high! But never leave your men hanging!",
  ui_story_5083_50831500_27_dialog_content = "Griping alone solves nothing! Is this how you repay the dead for their sacrifice?",
  ui_story_5083_50831500_28_dialog_content = "Would the soldiers still follow you if they saw you like this?",
  ui_story_5083_50831500_29_dialog_content = "Don't you still get a lot of people who trust you? Why are you so down on yourself?!",
  ui_story_5083_50831500_30_dialog_content = "What made you think you have the right to speak for everyone? You're not the only hero around here! Give them a chance!",
  ui_story_5083_50831500_31_dialog_content = "You're right. I was weak and confused.",
  ui_story_5083_50831500_32_dialog_content = "There's no future if you stand still, and no reward without risk!",
  ui_story_5083_50831500_33_dialog_content = "Every wants to serve the light. Since they're still with you, you have to make sure the glow isn't blurred.",
  ui_story_5083_50831500_34_dialog_content = "You might command the soldiers, but they chose you to lead them.",
  ui_story_5083_50831500_35_dialog_content = "Remember this, Barton, you will find whatever it is behind the call to duty on the battlefield.",
  ui_story_5083_50831500_36_dialog_content = "If you don't know who to trust, trust your comrades. It doesn't matter what kind of leader you become, they will follow.",
  ui_story_5083_50831500_37_dialog_content = "The 1st Legion could hold the line! The gargantuan Eclipsite ripped an opening for its kind to swarm the Gannon Escalator!",
  ui_story_5083_50831500_38_dialog_content = "The Grand Marshal gave the order to <color=#FFB400>abandon the city</color>!",
  ui_story_5083_50831500_39_dialog_content = "What? Abandon our home?",
  ui_story_5083_50831500_40_dialog_content = "Is he crazy? This is the heart of Illumina and our home! It's supposed to be the beacon that never goes out!",
  ui_story_5083_50831500_41_dialog_content = "My apologies, but that is the order. The Grand Marshal would like some troops to stay and cover for civilians' evacuation.",
  ui_story_5083_50831500_42_dialog_content = "Then the other troops will come back, reinforce, and besiege the Darkover.",
  ui_story_5083_50831500_43_dialog_content = "Pass on my order. All personnel, fall back! The 2nd Legion will cover the retreat!",
  ui_story_5083_50831500_44_dialog_content = "Let's go pick a fight, sir!",
  ui_story_5083_50831500_45_dialog_content = "<color=#e8d9bb>The 2nd Legion turned and rushed toward Gannon against the fleeing crowd.</color>",
  ui_story_5083_50831500_46_dialog_content = "<color=#e8d9bb>What followed was days of nonstop battle. The legion suffered great losses but defended the escalator valiantly.</color>",
  ui_story_5083_50831500_47_dialog_content = "<color=#e8d9bb>In the end, however, countless Eclipsites managed to penetrate the facility—</color><color=#FFB400>Gannon has fallen, officially.</color>",
  ui_story_5083_50831500_48_dialog_content = "The final group of personnel has left. Your turn to go now, Barton.",
  ui_story_5083_50831500_49_dialog_content = "Our carriers have taken too much damage to evacuate everybody.",
  ui_story_5083_50831500_50_dialog_content = "There you go again, old man.",
  ui_story_5083_50831500_51_dialog_content = "I'm taking people down there. They're all veterans, unlike the rookies you got.",
  ui_story_5083_50831500_52_dialog_content = "What are you babbling about? It's a lost cause...",
  ui_story_5083_50831500_53_dialog_content = "I'm going to defend the Central Tower no matter what! Preserving the power hub is to preserve the heart of Gannon!",
  ui_story_5083_50831500_54_dialog_content = "If it's destroyed like Undercity 13 was, the light will go out in Gannon and no Illumina folk can find their purpose.",
  ui_story_5083_50831500_55_dialog_content = "I can't allow that to happen to those still fighting hard!",
  ui_story_5083_50831500_56_dialog_content = "Then take me with you!",
  ui_story_5083_50831500_57_dialog_content = "I'm glad you're not melodramatic like Dogg, Barton. I won't repeat anything sentimental twice.",
  ui_story_5083_50831500_58_dialog_content = "I've always believed in you, my personally honed elite.",
  ui_story_5083_50831500_59_dialog_content = "So this is the final lesson.",
  ui_story_5083_50831500_60_dialog_content = "When necessary, even a general must pave the way for the future generation!",
  ui_story_5083_50831500_61_dialog_content = "I know you'll be the best leader for the 2nd Legion, Barton. It's in your hands. Now get the heck out of here!",
  ui_story_5083_50831500_62_dialog_content = "You can't make me leave, Commander Pango. Don't make me knock you out too.",
  ui_story_5083_50831500_63_dialog_content = "Guards, take him to the evacuation carrier... even if that means breaking his legs!",
  ui_story_5083_50831500_64_dialog_content = "What? Let me go!",
  ui_story_5083_50831500_65_dialog_content = "You can't do this to me, old man!",
  ui_story_5083_50831500_66_dialog_content = "Farewell, my problem child...",
  ui_story_5083_50831601_1_dialog_content = "Sorry you have to stick around, guys.",
  ui_story_5083_50831601_2_dialog_content = "Major, I want your men to blaze a path to the power source for us at all costs. Can you do that?",
  ui_story_5083_50831601_3_dialog_content = "Yes, sir!",
  ui_story_5083_50831601_4_dialog_content = "What are the estimated losses for you?",
  ui_story_5083_50831601_5_dialog_content = "We will all perish, sir!",
  ui_story_5083_50831601_6_dialog_content = "...",
  ui_story_5083_50831601_7_dialog_content = "But we will do it, sir!",
  ui_story_5083_50831601_8_dialog_content = "Alright... When we get there, I'll follow your orders!",
  ui_story_5083_50831601_9_dialog_content = "Hello, sir!",
  ui_story_5083_50831601_10_dialog_content = "First Battalion, get ready to counterstrike!",
  ui_story_5083_50831601_11_dialog_content = "Have no fear. We just have to hold until daylight. The Grand Marshal will come back for us once they've dealt with their Eclipsites.",
  ui_story_5083_50831601_12_dialog_content = "I still got a Lumamber, good enough to send out an SOS.",
  ui_story_5083_50831601_13_dialog_content = "The rest is up to us, just got to hold until dawn.",
  ui_story_5083_50831601_14_dialog_content = "So this is the end? With us running away while Gannon burns?",
  ui_story_5083_50831601_15_dialog_content = "Beep—Barton...",
  ui_story_5083_50831601_16_dialog_content = "Ambush! Ambush!",
  ui_story_5083_50831601_17_dialog_content = "What? Let me fight...",
  ui_story_5083_50831601_18_dialog_content = "Wake up, Barton.",
  ui_story_5083_50831601_19_dialog_content = "What's going on...?",
  ui_story_5083_50831601_20_dialog_content = "The convoy is under attack. Get up and fight.",
  ui_story_5083_50831601_21_dialog_content = "<size=45>Damn it!</size>",
  ui_story_5083_50831601_22_dialog_content = "My hands might be tied, but I'm in a foul mood so don't piss me off!",
  ui_story_5083_50831601_23_dialog_content = "Roar!",
  ui_story_5083_50831601_24_dialog_content = "Punched me in the jaw again.",
  ui_story_5083_50831601_25_dialog_content = "Curses... Someone get these cuffs off me!",
  ui_story_5083_50831601_26_dialog_content = "Wait a minute... I was hit in the jaw and it didn't hurt at all?",
  ui_story_5083_50831601_27_dialog_content = "Don't just stand there, keep fighting!",
  ui_story_5083_50831601_28_dialog_content = "Over my dead body!",
  ui_story_5083_50831601_29_dialog_content = "It must be a dream. I didn't have an iron jaw when I was young.",
  ui_story_5083_50831601_30_dialog_content = "I get it now... This is the nightmare I was trapped in.",
  ui_story_5083_50831601_31_dialog_content = "Beep—Have you remembered at last, Barton?",
  ui_story_5083_50831601_32_dialog_content = "What is it that's trapping you?",
  ui_story_5083_50831601_33_dialog_content = "I lost my way... But I always believed that as long as I kept fighting, the light would shine before me.",
  ui_story_5083_50831601_34_dialog_content = "Yet you're still trapped here.",
  ui_story_5083_50831601_35_dialog_content = "I don't know. I don't remember anything... I don't think I fled, but don't remember what I did after that...",
  ui_story_5083_50831601_36_dialog_content = "I only remember the commander in that battle...",
  ui_story_5083_50831601_37_dialog_content = "Then I was at the showdown, fighting with all I got but was hurt badly, and that's how I got fitted with the \"iron jaw.\"",
  ui_story_5083_50831601_38_dialog_content = "A lot of the soldiers didn't get that and saw me as a coward who abandoned his commander. I was an alien to them.",
  ui_story_5083_50831601_39_dialog_content = "I wanted to fight to the death next to Commander Pango... Forget it, I don't care if it was just a dream.",
  ui_story_5083_50831601_40_dialog_content = "Nightmares got nothing on me. There's always next time! I don't care how many tries, I will change it...",
  ui_story_5083_50831601_41_dialog_content = "Accept the outcome and wait till next time.. Is this how you forgive yourself, Barton?",
  ui_story_5083_50831601_42_dialog_content = "If you can leave it behind, why do you always come back here?",
  ui_story_5083_50831601_43_dialog_content = "Do you know how many times you've been through this? And how many \"next times\" did you have?",
  ui_story_5083_50831601_44_dialog_content = "Why you...",
  ui_story_5083_50831601_45_dialog_content = "When will the \"next time\" be?",
  ui_story_5083_50831601_46_dialog_content = "Who are you?",
  ui_story_5083_50831601_47_dialog_content = "It's been made clear to you since the beginning. I'll always be your navigator, Barton.",
  ui_story_5083_50831601_48_dialog_content = "To me, who can see the light but not touch it, that path has been under your feet all along since I knew you.",
  ui_story_5083_50831601_49_dialog_content = "Wait, you mean you are...",
  ui_story_5083_50831601_50_dialog_content = "We have to go, Colonel Barton.",
  ui_story_5083_50831601_51_dialog_content = "Where can we go? Undercity 19?",
  ui_story_5083_50831601_52_dialog_content = "The Gannon has fallen... Will we ever get it back?",
  ui_story_5083_50831601_53_dialog_content = "<size=45>Damn it!</size>",
  ui_story_5083_50831601_54_dialog_content = "<color=#e8d9bb>With a scream, Barton shatters the manacle.</color>",
  ui_story_5083_50831601_55_dialog_content = "That's right, I'm a black sheep, the defiant \"Sharpened Round\"!",
  ui_story_5083_50831601_56_dialog_content = "Why should I tolerate this?",
  ui_story_5083_50831601_57_dialog_content = "I'm starting a revolution and the time is now!",
  ui_story_5083_50831601_58_dialog_content = "All of you in the 2nd Legion!",
  ui_story_5083_50831601_59_dialog_content = "Colonel Barton? Our mission is to take you to safety. Please don't make it hard on us.",
  ui_story_5083_50831601_60_dialog_content = "No, we have no safety to speak of!",
  ui_story_5083_50831601_61_dialog_content = "On an Astra ravaged by Eclipsites, there's only one home we can go back to.",
  ui_story_5083_50831601_62_dialog_content = "You all trained there, so you ought to still remember how bright that light is!",
  ui_story_5083_50831601_63_dialog_content = "We weren't born to wander! Where can we go back if we do not go to Gannon?",
  ui_story_5083_50831601_64_dialog_content = "Our superior is fighting for his life and he needs help! Did you hear the bugle? Gannon is calling us!",
  ui_story_5083_50831601_65_dialog_content = "If we're destined to die in battle, I want to die with all of you under my command, to die in the fight for Gannon!",
  ui_story_5083_50831601_66_dialog_content = "I shall bring you home. Even if it ends up with only your names on a plaque...",
  ui_story_5083_50831601_67_dialog_content = "As long as the beacon's light remains, those who follow us will have the will to carry forward!",
  ui_story_5083_50831601_68_dialog_content = "I'm willing to follow you, Colonel Barton. The Grand Marshal's order was for us to defend Gannon. We'll never defy it.",
  ui_story_5083_50831601_69_dialog_content = "Me too! I've been following Barton since the beginning. I believe in that very Barton who charged with us.",
  ui_story_5083_50831601_70_dialog_content = "My platoon leaders and fellow recruits died protecting me. I don't mind sacrificing myself to protect Gannon.",
  ui_story_5083_50831601_71_dialog_content = "Count me in. Anybody wanting to get to Colonel Barton has to go through us first.",
  ui_story_5083_50831601_72_dialog_content = "You guys...",
  ui_story_5083_50831601_73_dialog_content = "It's daybreak, Barton.",
  ui_story_5083_50831601_74_dialog_content = "Yes, I see the path... All of your lights pointed the way for me.",
  ui_story_5083_50831601_75_dialog_content = "Company, about face! Let's end this night... Let's take Gannon back!",
  ui_story_5083_50831601_76_dialog_content = "<color=#e8d9bb>So the soldiers turned round and marched toward Gannon.</color>",
  ui_story_5083_50831601_77_dialog_content = "<color=#e8d9bb>They all realized they would die there, but no one slowed down.</color>",
  ui_story_5083_50831601_78_dialog_content = "<color=#e8d9bb>Without their glow, there wouldn't be dawn in Astra.</color>",
  ui_story_5083_50831601_79_dialog_content = "<color=#e8d9bb>The Darkover Crisis that tormented the land for eight years might be over because of the resilient stalwarts who came before. As their successors, it's my duty to carry on till the end.</color>",
  ui_story_5083_50831601_80_dialog_content = "Your men are decimated, insignificant Aurorian. All lives shall perish before me, the <color=#FFB400>Doomsday Bell</color>.",
  ui_story_5083_50831601_81_dialog_content = "Spit!",
  ui_story_5083_50831601_82_dialog_content = "<color=#e8d9bb>The humongous enemy approached the Central Tower. Covering its stone skin coursing with flames was a collage of ugly metal scraps for armor.</color>",
  ui_story_5083_50831601_83_dialog_content = "<color=#e8d9bb>Anyone examining the stamps on the scraps could recognize they came from different undercities. They represented the monster's victories like badges of honor.</color>",
  ui_story_5083_50831601_84_dialog_content = "<color=#e8d9bb>It was disquietingly creepy and infuriating at the same.</color>",
  ui_story_5083_50831601_85_dialog_content = "<color=#e8d9bb>As it lumbered forward, the scraps clashed to dull clangs as if ringing a spiteful requiem.</color>",
  ui_story_5083_50831601_86_dialog_content = "Ah, you are shivering, Tiny One. Yes, I can smell your fear. Even the banner in your hand is wavering.",
  ui_story_5083_50831601_87_dialog_content = "All pests are alike. They all fear the strong. That's their instinct. Kneel for me to crush you in delight.",
  ui_story_5083_50831601_88_dialog_content = "Yeah, I'm shaking... I didn't think I would be this scared at my age.",
  ui_story_5083_50831601_89_dialog_content = "Maybe it's instinct, like you said.",
  ui_story_5083_50831601_90_dialog_content = "So you admit it? Then kneel and beg for mercy! This is my greatest joy.",
  ui_story_5083_50831601_91_dialog_content = "Are you kidding, you ugly goof? Do you think you're facing a bunch of cowards?",
  ui_story_5083_50831601_92_dialog_content = "You have no idea how different you are from us!",
  ui_story_5083_50831601_93_dialog_content = "There won't be any joy for you. All you'll see is how unbreakable the backbones of Illumina people are!",
  ui_story_5083_50831601_94_dialog_content = "Aurorians have fear, but so do Eclipsites, and you'll never learn to cope with it like we do.",
  ui_story_5083_50831601_95_dialog_content = "I say no... No chance of you crossing our line!",
  ui_story_5083_50831601_96_dialog_content = "Then I shall put that to the test.",
  ui_story_5083_50831601_97_dialog_content = "Sorry, sir, this is the best we can do... Why hasn't help arrived yet...?",
  ui_story_5083_50831601_98_dialog_content = "I see it's time to deceive your soldiers. Go ahead, show the Lumamber and tell them help is on the way.",
  ui_story_5083_50831601_99_dialog_content = "That's the lie every officer pulled in every undercity I destroyed...",
  ui_story_5083_50831601_100_dialog_content = "No help came even when I drew the last breath out of them. It's the most ridiculous hypocrisy for Illumina.",
  ui_story_5083_50831601_101_dialog_content = "I'm sorry, my comrades. You trusted me with your lives, yet I could not promise anything in exchange.",
  ui_story_5083_50831601_102_dialog_content = "But please believe me when I say Illumina would never abandon its defenders!",
  ui_story_5083_50831601_103_dialog_content = "<color=#e8d9bb>Pango released the Lumamber and pulled the level in prayer. Light arced across the darkness over the fallen Gannon and into the sky.</color>",
  ui_story_5083_50831601_104_dialog_content = "<color=#e8d9bb>The soldiers fighting hard in Gannon stared at the flash in unison, with reflections of </color><color=#FFB400>hope</color><color=#e8d9bb> shining in their eyes.</color>",
  ui_story_5083_50831601_105_dialog_content = "You are alone, but you still lie to yourself and call it faith. Well, crushing faithful warriors is much more enjoyable than crushing ordinary pests!",
  ui_story_5083_50831601_106_dialog_content = "Damn you, Eclipsite, this is why you'll never get it... We Illumina soldiers are called the \"Defenders of Astra\" for a reason!",
  ui_story_5083_50831601_107_dialog_content = "I am Syurton. Remember this name, the name of your destroyer!",
  ui_story_5083_50831601_108_dialog_content = "Kill them all. Destroy the Central Tower. I want Gannon razed into oblivion.",
  ui_story_5083_50831601_109_dialog_content = "The 2nd Legion never backs down!",
  ui_story_5083_50831601_110_dialog_content = "<color=#e8d9bb>The signal in the sky dimmed and ultimately fell. All hopes seemed to be lost in the darkness.</color>",
  ui_story_5083_50831601_111_dialog_content = "2nd Legion? I heard that a few days ago. He even cut me on the head and back.",
  ui_story_5083_50831601_112_dialog_content = "Too bad he and his soldiers were pathetic. I kept his blade, though. See this here? Not a bad souvenir.",
  ui_story_5083_50831601_113_dialog_content = "Dogg! I'm so sorry...",
  ui_story_5083_50831601_114_dialog_content = "<color=#e8d9bb>Filled with despair, the veterans clutched their weapons and readied to charge the gargantuan entity.</color>",
  ui_story_5083_50831601_115_dialog_content = "<color=#e8d9bb>However, stars always shine brightest in the darkest of night.</color>",
  ui_story_5083_50831601_116_dialog_content = "<size=45>That's far enough!</size>",
  ui_story_5083_50831601_117_dialog_content = "<size=45>Try this on for size!</size>",
  ui_story_5083_50831601_118_dialog_content = "You're the one digging your grave, you stupid oaf!",
  ui_story_5083_50831601_119_dialog_content = "<color=#e8d9bb>An armored vehicle descended and crashed into the gargantuan Eclipsite's back, with the turret dealing maximum damage at such close range.</color>",
  ui_story_5083_50831601_120_dialog_content = "Ahhhh!",
  ui_story_5083_50831601_121_dialog_content = "I got you... Ouch!",
  ui_story_5083_50831601_122_dialog_content = "Thanks, pal!",
  ui_story_5083_50831601_123_dialog_content = "This is ridiculous, blowing up the vehicle! And you almost...",
  ui_story_5083_50831601_124_dialog_content = "It ain't me without the crazy, right?",
  ui_story_5083_50831601_125_dialog_content = "This is the real me, you see!",
  ui_story_5083_50831601_126_dialog_content = "What are you doing back here, you fool?!",
  ui_story_5083_50831601_127_dialog_content = "Didn't you send the SOS? Don't I count as a legitimate backup?",
  ui_story_5083_50831601_128_dialog_content = "The upside has fallen. I came in a vehicle and now have no way back even if you don't want me here.",
  ui_story_5083_50831601_129_dialog_content = "Why you...!",
  ui_story_5083_50831601_130_dialog_content = "This is the third time already! Don't keep telling me to leave, old man!",
  ui_story_5083_50831601_131_dialog_content = "I got a message for the Eclipsites: Even in the underground where you don't see the sun, they still don't own the place!",
  ui_story_5083_50831601_132_dialog_content = "Gannon will be bright again, for sure!",
  ui_story_5083_50831601_133_dialog_content = "Fool, we'll probably be dead before help arrives!",
  ui_story_5083_50831601_134_dialog_content = "In that case, I hope the light from the beacon will shine on our bodies.",
  ui_story_5083_50831601_135_dialog_content = "The explosion nearly knocked me off the edge, pest.",
  ui_story_5083_50831601_136_dialog_content = "What? Still alive in two pieces?",
  ui_story_5083_50831601_137_dialog_content = "Do you think I could be killed by mere explosions after destroying so many undercities? I am the <color=#FFB400>nemesis of all that's living</color>!",
  ui_story_5083_50831601_138_dialog_content = "That's funny, calling yourself the nemesis of all that's living, only to have been alive the whole time.",
  ui_story_5083_50831601_139_dialog_content = "Shut up and let's do this!",
  ui_story_5083_50831601_140_dialog_content = "Just wait till me and the guys send you to hell!",
  ui_story_5083_50831602_1_dialog_content = "You can't kill me!",
  ui_story_5083_50831602_2_dialog_content = "Heh, all that talk of unbreakable backbones... I don't see you getting up.",
  ui_story_5083_50831602_3_dialog_content = "Damn you! Go to hell!",
  ui_story_5083_50831602_4_dialog_content = "You can go there with him too!",
  ui_story_5083_50831602_5_dialog_content = "<color=#e8d9bb>Barton ducked a fist blow and ran up the creature's arm.</color>",
  ui_story_5083_50831602_6_dialog_content = "<color=#e8d9bb>Before Syurton could react, he yanked the trophy—Dogg's knife—off.</color>",
  ui_story_5083_50831602_7_dialog_content = "<color=#e8d9bb>The two blades meld into one in Barton's grip and became his. He dodged and attacked Syurton relentlessly.</color>",
  ui_story_5083_50831602_8_dialog_content = "<color=#e8d9bb>In a flash, Syurton's neck was sliced open, causing it to flail and lash out in flame.</color>",
  ui_story_5083_50831602_9_dialog_content = "<color=#e8d9bb>But Barton just continued to slash away as flames gushed. The impeccable assault was the result of countless </color><color=#FFB400> practices </color><color=#e8d9bb> in the base.</color>",
  ui_story_5083_50831602_10_dialog_content = "<color=#e8d9bb>And what was more horrifying was the murderous glare in Barton's eyes.</color>",
  ui_story_5083_50831602_11_dialog_content = "<color=#e8d9bb>He leaped through the fire, split the darkness and plunged the blade deep into Syurton's neck.</color>",
  ui_story_5083_50831602_12_dialog_content = "Off me!",
  ui_story_5083_50831602_13_dialog_content = "Don't even think about hurting Colonel Barton! Aim for the eyes!",
  ui_story_5083_50831602_14_dialog_content = "This is the end... And this is how I use guns, sir!",
  ui_story_5083_50831602_15_dialog_content = "<color=#e8d9bb>Barton drew and fired a gun. The bullet struck the double blade and buried it entirely inside Syurton.</color>",
  ui_story_5083_50831602_16_dialog_content = "<color=#e8d9bb>He then pressed a remote to denote the explosives he planted inside his blade.</color>",
  ui_story_5083_50831602_17_dialog_content = "<color=#e8d9bb>No one could have guessed Barton would sacrifice his and his close friend's weapons for victory.</color>",
  ui_story_5083_50831602_18_dialog_content = "No! <color=#FFB400>Mother</color>...",
  ui_story_5083_50831602_19_dialog_content = "Enjoy your humiliation in the abyss, you stupid oaf.",
  ui_story_5083_50831602_20_dialog_content = "Are you sure this is fine?",
  ui_story_5083_50831602_21_dialog_content = "Dogg will forever be in our hearts and on the memorial.",
  ui_story_5083_50831602_22_dialog_content = "His will is enough to carry us forward. Nothing else is necessary.",
  ui_story_5083_50831602_23_dialog_content = "Oh, are you okay, Commander Pango?",
  ui_story_5083_50831602_24_dialog_content = "Don't touch him. That blow broke his spine.",
  ui_story_5083_50831602_25_dialog_content = "Watch out, Colonel Barton, the smaller Eclipsites are still on the move!",
  ui_story_5083_50831602_26_dialog_content = "Take care... of the 2nd Legion banner... You're the commander now, Barton... Lead the men... and fight to the last breath...",
  ui_story_5083_50831602_27_dialog_content = "Trust... your fellow Illumina... help will come...",
  ui_story_5083_50831602_28_dialog_content = "He's out!",
  ui_story_5083_50831602_29_dialog_content = "Damn you, damn you!",
  ui_story_5083_50831602_30_dialog_content = "The 2nd Legion will never compromise!",
  ui_story_5083_50831602_31_dialog_content = "The 2nd Legion will never compromise!",
  ui_story_5083_50831602_32_dialog_content = "<color=#e8d9bb>The gargantuan Eclipsite is dead, but the battle rages on. More small Eclipsites swarmed the only way in and fought the soldiers.</color>",
  ui_story_5083_50831602_33_dialog_content = "<color=#e8d9bb>With the banner in hand, Barton fought alongside the warriors until their backs were to the power station.</color>",
  ui_story_5083_50831602_34_dialog_content = "<color=#e8d9bb>When he looked around, very few men were left.</color>",
  ui_story_5083_50831602_35_dialog_content = "This is far enough!",
  ui_story_5083_50831602_36_dialog_content = "Even it's just us left, we'll never compromise... never compromise...",
  ui_story_5083_50831602_37_dialog_content = "I will fight with you to the final moment, Barton.",
  ui_story_5083_50831602_38_dialog_content = "We'll follow Colonel Barton to our dying breath.",
  ui_story_5083_50831602_39_dialog_content = "We'll die defending this passage!",
  ui_story_5083_50831602_40_dialog_content = "What am I doing? What a fool I am! Why do I think of it just now?",
  ui_story_5083_50831602_41_dialog_content = "I already knew how this would end.",
  ui_story_5083_50831602_42_dialog_content = "Back then, we were forced to retreat after narrowly beating that big oaf, but Pango stayed and fought.",
  ui_story_5083_50831602_43_dialog_content = "Everyone with him died, and he fell into a coma from injuries for more than a decade.",
  ui_story_5083_50831602_44_dialog_content = "...",
  ui_story_5083_50831602_45_dialog_content = "I don't have eyes like yours, PlayerName, so I envy how you can always see the light.",
  ui_story_5083_50831602_46_dialog_content = "But I'm not lost, because I truly believe there will be light if we fight to the end.",
  ui_story_5083_50831602_47_dialog_content = "When I first met you, you were indeed on a path of hope.",
  ui_story_5083_50831602_48_dialog_content = "I am honored to know you. It was you who saved both of us countless times.",
  ui_story_5083_50831602_49_dialog_content = "You are a hero, yet tormented by nightmares... I wanted to guide you...",
  ui_story_5083_50831602_50_dialog_content = "I'm not afraid to get lost with you by my side, and nightmares are nothing to me.",
  ui_story_5083_50831602_51_dialog_content = "But I just can't let it go...",
  ui_story_5083_50831602_52_dialog_content = "Did reinforcement ever come for Commander Pango?",
  ui_story_5083_50831602_53_dialog_content = "Right, how could I forget...?",
  ui_story_5083_50831602_54_dialog_content = "Commander Pango, the true \"nightmare\" to me...",
  ui_story_5083_50831602_55_dialog_content = "The future of Illumina is full of hope, but did we really abandon the veterans in the past?",
  ui_story_5083_50831602_56_dialog_content = "I get rattled just thinking about it. I don't wish for them to die with regret and despair.",
  ui_story_5083_50831602_57_dialog_content = "No, Barton, the Illumina would never abandon its defenders.",
  ui_story_5083_50831602_58_dialog_content = "Fortunately, you're finally here. Please look.",
  ui_story_5083_50831602_59_dialog_content = "Come with me, vanguards. On the double and don't keep the vets waiting!",
  ui_story_5083_50831602_60_dialog_content = "The noncombatants are safe. Now let's take Gannon back!",
  ui_story_5083_50831602_61_dialog_content = "<color=#e8d9bb>Reinhardt showed up, swinging a fiery spear and breaching the Eclipsites' line. The blaze lit up the city like the morning sun.</color>",
  ui_story_5083_50831602_62_dialog_content = "I see light...",
  ui_story_5083_50831602_63_dialog_content = "Look, Commander Pango, light! Help is here! They're back!",
  ui_story_5083_50831602_64_dialog_content = "We're not abandoned. Wake up and see!",
  ui_story_5083_50831602_65_dialog_content = "<color=#e8d9bb>The bells tolled in Gannon, heralding the arrival of the reinforcement, declaring the return of the city's rightful occupants.</color>",
  ui_story_5083_50831602_66_dialog_content = "<size=45>Commander Pango...!</size>",
  ui_story_5083_50831602_67_dialog_content = "Quit crying, you brat... I'm not dead yet...",
  ui_story_5083_50831602_68_dialog_content = "I ain't deaf... Of course I heard...",
  ui_story_5083_50831602_69_dialog_content = "They came around just in time... I thought I'd never see them...",
  ui_story_5083_50831602_70_dialog_content = "This is awesome... Really, so awesome...",
  ui_story_5083_50831602_71_dialog_content = "The legion and Illumina's future is in your hands now, brat... Watch your temper and be more serious...",
  ui_story_5083_50831602_72_dialog_content = "I will, Commander Pango. I won't let you down.",
  ui_story_5083_50831602_73_dialog_content = "Let them take care of the commander, Barton. We should go now.",
  ui_story_5083_50831602_74_dialog_content = "Follow that light in your heart... That's your faith.",
  ui_story_5083_50831602_75_dialog_content = "This is the final <color=#FFB400>trip</color>. It's time to leave the nightmare behind.",
  ui_story_5083_50831602_76_dialog_content = "Oh, of course. Nothing's gonna hold me down again!",
  ui_story_5083_50831602_77_dialog_content = "Goodbye, Commander Pango.",
  ui_story_5083_50831602_78_dialog_content = "?!",
  ui_story_5083_50831602_79_dialog_content = "The dream is turning back into reality... Is that your memory?",
  ui_story_5083_50831602_80_dialog_content = "Commander Pango and the vets never quit and didn't even allow the banner to fall.",
  ui_story_5083_50831602_81_dialog_content = "They held Gannon and defended our light.",
  ui_story_5083_50831602_82_dialog_content = "Sleep, Barton... It's a new day, and resting is easy for you when you are home.",
  ui_story_5083_50831602_83_dialog_content = "Commander Pango... PlayerName... Everyone... Thank you all... for letting us walk the path without a doubt...",
  ui_story_5083_50831602_84_dialog_content = "<color=#e8d9bb>I witnessed how resilient the stars were, rising and brightening the night sky.</color>",
  ui_story_5083_50831602_85_dialog_content = "<color=#e8d9bb>As well as the courage of Aurorians, who give off the brilliance of life even in the face of death.</color>",
  ui_story_5083_50831602_86_dialog_content = "<color=#e8d9bb>Heroes preserved kindles that built into a blaze, incinerating the Darkover to welcome the dawn.</color>",
  ui_story_5083_50831602_87_dialog_content = "<color=#e8d9bb>Even when a star lost its glow and fell, those it shone on would remain steadfast on the path, keep searching their way until daybreak.</color>",
  ui_story_5083_50831602_88_dialog_content = "<color=#e8d9bb>And that would be enough...</color>",
  ui_story_5083_50831602_89_dialog_content = "<color=#e8d9bb>Thank you all, stars from the past.</color>"
}
return config
